# «полтора/полутора» — единственная дробь, которую закон пишет словом.
_WORD_NUMBER_FRACTIONS: dict[str, str] = {
    "полтора": "1.5", "полторы": "1.5", "полутора": "1.5",
}
_WORD_NUMBER_LEXEMES: frozenset[str] = frozenset(
    (
        *_WORD_NUMBER_UNITS,
        *_WORD_NUMBER_TENS,
        *_WORD_NUMBER_HUNDREDS,
        *_WORD_NUMBER_MULTIPLIERS,
        *_WORD_NUMBER_FRACTIONS,
    )
)
_WORD_NUMBER_TOKEN_RE = re.compile(
    rf"(?P<literal>{_NUMBER_PATTERN})|(?P<word>[а-яёa-z]+)",
    re.IGNORECASE,
)


def _word_number_token_key(token: str) -> str:
    return token.casefold().replace("ё", "е")


def _word_number_group_value(
    tokens: list[tuple[int, int, str]],
) -> str | None:
    """Число словесной группы или None, если группа его не задаёт."""

    total = 0
    current = 0
    seen_value = False
    fraction: str | None = None
    for _, _, raw in tokens:
        key = _word_number_token_key(raw)
        if key in _WORD_NUMBER_FRACTIONS:
            if seen_value or fraction is not None:
                return None
            fraction = _WORD_NUMBER_FRACTIONS[key]
            continue
        if key in _WORD_NUMBER_MULTIPLIERS:
            scale = _WORD_NUMBER_MULTIPLIERS[key]
            if fraction is not None:
                # «полутора миллионов» = 1 500 000
                total += int(float(fraction) * scale)
                fraction = None
                seen_value = True
                continue
            if not seen_value:
                # Голый множитель («тысяч рублей») количества не задаёт.
                return None
            total += (current or 1) * scale
            current = 0
            continue
        if fraction is not None:
            return None
        if key in _WORD_NUMBER_HUNDREDS:
            current += _WORD_NUMBER_HUNDREDS[key]
        elif key in _WORD_NUMBER_TENS:
            current += _WORD_NUMBER_TENS[key]
        elif key in _WORD_NUMBER_UNITS:
            current += _WORD_NUMBER_UNITS[key]
        else:
            try:
                current += int(_normalize_number(raw))
            except (TypeError, ValueError):
                return None
        seen_value = True
    if fraction is not None:
        return None if seen_value else fraction
    if not seen_value:
        return None
    return str(total + current)


def _word_number_groups(value: str) -> list[tuple[int, int, str]]:
    """Максимальные словесные числительные группы: (начало, конец, число)."""

    tokens = [
        (match.start(), match.end(), match.group(0))
        for match in _WORD_NUMBER_TOKEN_RE.finditer(value)
    ]
    groups: list[tuple[int, int, str]] = []
    index = 0
    while index < len(tokens):
        first = tokens[index]
        key = _word_number_token_key(first[2])
        if key not in _WORD_NUMBER_LEXEMES and not first[2][:1].isdigit():
            index += 1
            continue
        run = [first]
        cursor = index + 1
        while cursor < len(tokens):
            gap = value[tokens[cursor - 1][1]:tokens[cursor][0]]
            if gap.strip() or not gap:
                break
            next_key = _word_number_token_key(tokens[cursor][2])
            if next_key not in _WORD_NUMBER_LEXEMES:
                break
            run.append(tokens[cursor])
            cursor += 1
        index = cursor
        if first[2][:1].isdigit() and not any(
            _word_number_token_key(item[2]) in _WORD_NUMBER_MULTIPLIERS
            for item in run[1:]
        ):
            # Голая цифра остаётся ровно тому разбору, что был до правки.
            continue
        number = _word_number_group_value(run)
        if number is None:
            continue
        groups.append((run[0][0], run[-1][1], number))
    return groups


def _expand_word_numbers(value: str) -> str:
    """Словесные числительные — цифрами, БЕЗ сдвига остальных смещений.

    Число дописывается в конец собственной группы и добивается слева
    пробелами, поэтому длина строки и позиции всех прочих токенов остаются
    прежними: единица измерения по-прежнему стоит вплотную справа, а весь
    существующий цифровой разбор видит текст ровно там же, где видел его до
    правки.  Группа, в которую цифры не помещаются, остаётся словом — тогда
    поведение просто прежнее.
    """

    groups = _word_number_groups(value) if value else []
    if not groups:
        return value
    characters = list(value)
    for start, end, number in groups:
        width = end - start
        if len(number) > width:
            continue
        characters[start:end] = number.rjust(width)
    return "".join(characters)


@dataclass(frozen=True)
class _Fact:
    value: str
    unit: str
    category: str


@dataclass(frozen=True)
class _RangeFact:
    first: str
    second: str
    unit: str
    category: str


@dataclass(frozen=True)
class _QualitativeClaim:
    action: str
    object: str = ""
    polarity: str = "positive"
    modality: str = "availability"
    relation: str = ""
    ratio: Fraction | None = None
    authority: str = ""
    references: frozenset[str] = frozenset()
    qualifiers: frozenset[str] = frozenset()


@dataclass(frozen=True)
class _Evidence:
    facts: frozenset[_Fact]
    ranges: frozenset[_RangeFact]
    categories: frozenset[str]
    qualitative_claims: frozenset[_QualitativeClaim]


def _normalized_text(value: str) -> str:
    return unicodedata.normalize("NFKC", value).replace("\r\n", "\n").replace(
        "\r", "\n"
    )


def _repair_source_layout(value: str) -> str:
    value = _normalized_text(value)
    value = re.sub(r"(?i)\bш\s*\n\s*траф\b", "штраф", value)
    value = re.sub(
        r"(?<!\d)(\d{1,3})\.\s+(\d{3})(?=\s*\$)",
        r"\1.\2",
        value,
    )
    value = re.sub(
        r"(?<!\d)(\d{1,3})\s*\n\s*(\d{1,3})"
        r"(?=\s*[.,]\s*\d{3}\s*\$)",
        r"\1\2",
        value,
    )
    value = re.sub(
        r"(?<!\d)(\d{1,3})\s*\n\s*(?=[.,]\s*\d{3}\s*\$)",
        r"\1",
        value,
    )
    value = re.sub(
        r"(?<!\d)(\d{1,3})\s+([.,]\d{3})(?=\s*\$)",
        r"\1\2",
        value,
    )
    value = re.sub(r"\n\s*(?=[,;])", " ", value)
    value = re.sub(
        r"(?m)(?<!\d)(\d{1,2})\s*\n\s*(\d{1,2}[.,]\d{3})(?=\s*\$)",
        r"\1\2",
        value,
    )
    value = re.sub(
        r"(?m)(?<!\d)(\d{1,3})\s*\n\s*([.,]\d{3})(?=\s*\$)",
        r"\1\2",
        value,
    )
    value = re.sub(
        r"(?i)("
        r"(?:"
        r"(?:смягч|уменьш|сниж|увелич|повыш)\w*"
        r"[^.!?;\n]{0,100}\bнаказани\w*[^.!?;\n]{0,80}|"
        r"\bнаказани\w*[^.!?;\n]{0,100}"
        r"(?:смягч|уменьш|сниж|увелич|повыш)\w*[^.!?;\n]{0,80}"
        r")\bв"
        r")\s*\n\s*(\d+\s+раз\w*\b)",
        r"\1 \2",
        value,
    )
    return value


def _normalize_number(raw: str) -> str:
    compact = raw.replace("\u00a0", " ").strip()
    if " " in compact:
        groups = compact.split()
        if (
            groups
            and 1 <= len(groups[0]) <= 3
            and all(len(group) == 3 for group in groups[1:])
            and all(group.isdigit() for group in groups)
        ):
            compact = "".join(groups)
    if "." in compact or "," in compact:
        separator = "." if "." in compact else ","
        groups = compact.split(separator)
        if (
            1 <= len(groups[0]) <= 3
            and len(groups) > 1
            and all(len(group) == 3 for group in groups[1:])
            and all(group.isdigit() for group in groups)
        ):
            compact = "".join(groups)
        else:
            compact = compact.replace(",", ".")
    if "." in compact:
        integer, fraction = compact.split(".", 1)
        return f"{int(integer)}.{fraction.rstrip('0') or '0'}"
    return str(int(compact))


def _mask_non_evidence_numbers(value: str) -> str:
    value = _STANDALONE_CODE_REFERENCE_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
    )
    value = _PRESCRIBED_REFERENCE_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
    )
    value = _REFERENCE_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
    )
    value = _ARTICLE_HEADER_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
    )
    value = _STRUCTURAL_NUMBER_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
    )
    return _LEADING_SUBSECTION_CODE_RE.sub(
        lambda match: re.sub(r"\d", " ", match.group(0)),
        value,
        count=1,
    )


def _categories_with_positions(value: str) -> list[tuple[int, int, str]]:
    matches: list[tuple[int, int, str]] = []
    for category, patterns in _CATEGORY_PATTERNS.items():
        for pattern in patterns:
            matches.extend(
                (match.start(), match.end(), category)
                for match in pattern.finditer(value)
            )
    return matches


def _unit_near(value: str, start: int, end: int, category: str) -> str:
    left = max(0, start - 12)
    right = min(len(value), end + 24)
    context = value[left:right]
    relative_end = end - left
    suffix = context[relative_end:]
    if (
        "$" in value[max(0, start - 2):min(len(value), end + 3)]
        or re.match(r"\s*доллар", suffix, re.IGNORECASE)
    ):
        return "money"
    if re.search(r"\s*%", suffix):
        return "percent"
    immediate_units = [
        (match.start(), unit)
        for unit, pattern in _TIME_UNIT_PATTERNS
        if (match := pattern.search(suffix[:24])) is not None
    ]
    if immediate_units:
        return min(immediate_units)[1]
    if category == "wanted" or re.match(
        r"\s*уров(?:ень|ня|ней|ню|не|ням|нями)?\b",
        suffix,
        re.IGNORECASE,
    ):
        return "wanted"
    if category in {"fine", "bail", "compensation"}:
        return "money"
    if re.search(r"(?:розыск|зв(?:\.|езд)|\*)", context, re.IGNORECASE):
        return "wanted"
    return "generic"


_CLAIM_CATEGORY_SEGMENT_BREAK_RE = re.compile(
    r"[;,\n]|\bи\b|\bлибо\b|\bили\b|\bа\s+также\b",
    re.IGNORECASE,
)


def _claim_category(
    value: str,
    start: int,
    end: int,
    *,
    default: str | None,
) -> str:
    unit = _unit_near(value, start, end, "sanction")
    if default is not None:
        compatible_units = {
            "fine": {"money", "percent", "generic"},
            "prison": {
                "seconds",
                "minutes",
                "hours",
                "days",
                "months",
                "years",
                "generic",
            },
            "arrest": {
                "seconds",
                "minutes",
                "hours",
                "days",
                "months",
                "years",
                "generic",
            },
            "wanted": {"wanted", "generic"},
        }
        if unit in compatible_units.get(default, {"generic"}):
            return default
    positioned = _categories_with_positions(value)

    def gap_to_number(item: tuple[int, int, str]) -> str:
        if item[1] <= start:
            return value[item[1]:start]
        if item[0] >= end:
            return value[end:item[0]]
        return ""

    positioned = [
        item
        for item in positioned
        if not _NUMBER_RE.search(gap_to_number(item))
    ]
    if unit == "money":
        allowed = {"fine", "bail", "compensation"}
        positioned = [item for item in positioned if item[2] in allowed]
    elif unit in {"seconds", "minutes", "hours", "days", "months", "years"}:
        allowed = {
            "fine",
            "prison",
            "arrest",
            "license",
            "dismissal",
            "suspension",
            "blacklist",
            "access_ban",
            "ban",
            "discipline",
        }
        positioned = [item for item in positioned if item[2] in allowed]
    elif unit == "wanted":
        positioned = [item for item in positioned if item[2] == "wanted"]
    if not positioned:
        return "sanction"

    def distance(item: tuple[int, int, str]) -> tuple[int, int, int]:
        # Метка, отделённая от числа сочинительной или клаузальной границей,
        # проигрывает метке своего же оборота, даже если стоит ближе по
        # символам.  Без этого «арест на срок до 15 суток И штраф в размере
        # 10000 рублей» отдавал срок ШТРАФУ (до «штраф» 8 символов, до
        # «арест» 11), и дословно взятый из источника фрагмент «арест на срок
        # до 15 суток» отвергался обеими штрафными ногами как несовпадающий
        # по категории.
        item_start, item_end, _ = item
        if item_end < start:
            gap = value[item_end:start]
            crossed = 1 if _CLAIM_CATEGORY_SEGMENT_BREAK_RE.search(gap) else 0
            return crossed, start - item_end, -item_end
        if item_start > end:
            gap = value[end:item_start]
            crossed = 1 if _CLAIM_CATEGORY_SEGMENT_BREAK_RE.search(gap) else 0
            return crossed, item_start - end, item_start
        return 0, 0, item_start

    return min(positioned, key=distance)[2]


_PROTECTED_ABBREVIATION_RE = re.compile(
    r"(?<!\w)(?:(?:ст|ч|п|пп)\.|"
    r"т\s*\.\s*(?:е|к|д|п|н)\s*\.|"
    r"г\.(?=\s+[А-ЯЁ]))",
    re.IGNORECASE,
)
_SENTENCE_CLOSERS = frozenset("\"'»”’)]}")


@lru_cache(maxsize=1024)
def _hard_clause_boundary_spans(value: str) -> tuple[tuple[int, int], ...]:
    """Return punctuation offsets and split ends without changing text offsets."""

    protected_dots = {
        index
        for match in _PROTECTED_ABBREVIATION_RE.finditer(value)
        for index in range(match.start(), match.end())
        if value[index] == "."
    }
    boundaries: list[tuple[int, int]] = []
    for index, character in enumerate(value):
        if character in ";\n":
            boundaries.append((index, index + 1))
            continue
        if character not in ".!?":
            continue
        if character == "." and index in protected_dots:
            continue
        if (
            character == "."
            and 0 < index < len(value) - 1
            and value[index - 1].isdigit()
            and value[index + 1].isdigit()
        ):
            continue
        split_end = index + 1
        while (
            split_end < len(value)
            and value[split_end] in _SENTENCE_CLOSERS
        ):
            split_end += 1
        if split_end == len(value) or value[split_end].isspace():
            boundaries.append((index, split_end))
    return tuple(boundaries)


def _split_sentences(line: str) -> Iterable[str]:
    start = 0
    for _, split_end in _hard_clause_boundary_spans(line):
        sentence = line[start:split_end].strip()
        if sentence:
            yield sentence
        start = split_end
    tail = line[start:].strip()
    if tail:
        yield tail


def _label_default(label: str) -> str | None:
    folded = label.casefold()
    if "залог" in folded:
        return "bail"
    if "розыск" in folded:
        return "wanted"
    if "штраф" in folded:
        return "fine"
    return None


def _starts_structural_block(value: str) -> bool:
    return (
        _BLOCK_BOUNDARY_RE.match(value) is not None
        or _LEADING_SUBSECTION_CODE_RE.match(value) is not None
    )


def _find_label(value: str) -> re.Match[str] | None:
    return _LABEL_RE.search(value) or _INLINE_LABEL_RE.search(value)


def _source_contexts(full_text: str) -> list[tuple[str, str | None]]:
    value = _repair_source_layout(full_text)
    lines = value.splitlines()
    contexts: list[tuple[str, str | None]] = []

    for index, line in enumerate(lines):
        label = _find_label(line)
        if label is not None:
            label_default = _label_default(label.group("label"))
            block = [line[label.start("label"):].strip()]
            for following in lines[index + 1:index + 8]:
                stripped = following.strip()
                if not stripped or _starts_structural_block(stripped):
                    break
                if _find_label(stripped):
                    break
                block.append(stripped)
            contexts.append(("\n".join(block), label_default))

        if _WANTED_PIPE_RE.search(line):
            contexts.append((line.strip(), "wanted"))
        if _STRUCTURED_WANTED_HEADER_RE.search(line):
            contexts.append((line.strip(), "wanted"))

        for sentence in _split_sentences(line):
            if (
                _INLINE_CONSEQUENCE_RE.search(sentence)
                or _IDENTITY_HOLD_RE.search(sentence)
                or _NEGATIVE_LIABILITY_RE.search(sentence)
            ):
                contexts.append((sentence, None))

        if _LIST_HEADING_RE.search(line):
            contexts.append((line.strip(), None))
            for following in lines[index + 1:]:
                stripped = following.strip()
                if not stripped or _starts_structural_block(stripped):
                    break
                contexts.append((stripped, None))

        qualifier = re.match(
            r"^\s*(примечание|пояснение|исключение)\s*:\s*(.*)$",
            line,
            re.IGNORECASE,
        )
        if qualifier is not None:
            previous = next(
                (
                    lines[previous_index].strip()
                    for previous_index in range(index - 1, -1, -1)
                    if lines[previous_index].strip()
                ),
                "",
            )
            nearby_label = any(
                _find_label(candidate)
                for candidate in lines[max(0, index - 3):index]
            )
            linked_to_sanction = (
                _INLINE_CONSEQUENCE_RE.search(previous) is not None
                or nearby_label
            )
            qualifier_kind = qualifier.group(1).casefold()
            qualifier_body = qualifier.group(2).strip()
            qualifier_lines: list[str] = []
            if qualifier_body:
                qualifier_lines.append(qualifier_body)
            else:
                for following in lines[index + 1:index + 5]:
                    stripped = following.strip()
                    if not stripped or _starts_structural_block(stripped):
                        break
                    qualifier_lines.append(stripped)
            qualifier_text = " ".join(qualifier_lines)
            applicability_note = re.search(
                r"(?:не\s+может\s+быть\s+применен|"
                r"не\s+применяется|исключени|"
                r"применим\w*\s+только)",
                qualifier_text,
                re.IGNORECASE,
            )
            if linked_to_sanction and (
                qualifier_kind in {"пояснение", "исключение"}
                or applicability_note is not None
            ):
                if qualifier_text:
                    contexts.append(
                        (
                            f"{qualifier.group(1)}: {qualifier_text}",
                            "sanction",
                        )
                    )

    deduplicated: list[tuple[str, str | None]] = []
    seen: set[tuple[str, str | None]] = set()
    for item in contexts:
        if item not in seen:
            seen.add(item)
            deduplicated.append(item)
    return deduplicated


def _extract_claims(
    value: str,
    *,
    default_category: str | None,
) -> tuple[set[_Fact], set[_RangeFact], set[str]]:
    masked = _mask_non_evidence_numbers(value)
    masked_characters = list(masked)
    for numeric_list in _CLOSED_UK_ARTICLE_LIST_RE.finditer(value):
        number_start, number_end = numeric_list.span("numbers")
        masked_characters[number_start:number_end] = " " * (
            number_end - number_start
        )
    masked = "".join(masked_characters)
    facts: set[_Fact] = set()
    ranges: set[_RangeFact] = set()
    categories = {
        category for _, _, category in _categories_with_positions(masked)
    }
    if default_category is not None:
        categories.add(default_category)

    # Словесные числительные разбираются тем же аппаратом, что и цифры:
    # группа замещается числом БЕЗ сдвига смещений (длина сохраняется),
    # поэтому единица измерения, категория и диапазон читаются ровно теми
    # же правилами, что и для «15 суток».  Колонка categories считана выше,
    # до замещения, чтобы перечень категорий остался побайтово прежним.
    masked = _expand_word_numbers(masked)

    for match in _NUMBER_RE.finditer(masked):
        category = _claim_category(
            masked,
            match.start(),
            match.end(),
            default=default_category,
        )
        unit = _unit_near(masked, match.start(), match.end(), category)
        facts.add(
            _Fact(
                _normalize_number(match.group("number")),
                unit,
                category,
            )
        )

    for match in _RANGE_RE.finditer(masked):
        category = _claim_category(
            masked,
            match.start(),
            match.end(),
            default=default_category,
        )
        unit = _unit_near(masked, match.start(), match.end(), category)
        first = _normalize_number(match.group("first"))
        second = _normalize_number(match.group("second"))
        ranges.add(
            _RangeFact(first, second, unit, category)
        )
        facts.add(_Fact(first, unit, category))
        facts.add(_Fact(second, unit, category))

    for match in _UNICODE_STAR_RE.finditer(masked):
        if default_category == "wanted" or re.search(
            r"\bрозыск", masked, re.IGNORECASE
        ):
            facts.add(_Fact(str(len(match.group(0))), "wanted", "wanted"))
    for match in _UNICODE_STAR_RANGE_RE.finditer(masked):
        ranges.add(
            _RangeFact(
                str(len(match.group("first"))),
                str(len(match.group("second"))),
                "wanted",
                "wanted",
            )
        )

    for match in _WANTED_PIPE_RE.finditer(masked):
        first = _normalize_number(match.group("first"))
        facts.add(_Fact(first, "wanted", "wanted"))
        if match.group("second") is not None:
            second = _normalize_number(match.group("second"))
            facts.add(_Fact(second, "wanted", "wanted"))
            ranges.add(_RangeFact(first, second, "wanted", "wanted"))

    for match in _WANTED_TEXT_RE.finditer(masked):
        facts.add(
            _Fact(
                _normalize_number(match.group("number")),
                "wanted",
                "wanted",
            )
        )
    return facts, ranges, categories


def _reference_family(value: str) -> str:
    folded = value.casefold()
    if re.search(r"\bук\b|уголовн\w*\s+кодекс", folded):
        return "UK"
    if re.search(r"\bак\b|административн\w*\s+кодекс", folded):
        return "AK"
    if re.search(r"\bпк\b|процессуальн\w*\s+кодекс", folded):
        return "PK"
    return ""


def _normalize_legal_code(raw: str) -> str:
    parts = raw.replace(",", ".").split(".")
    return ".".join(str(int(part)) for part in parts)


def _legal_references(value: str) -> frozenset[str]:
    references: set[str] = set()
    spans = [
        *list(_REFERENCE_RE.finditer(value)),
        *list(_PRESCRIBED_REFERENCE_RE.finditer(value)),
    ]
    for match in spans:
        nearby = value[
            max(0, match.start() - 24):min(len(value), match.end() + 48)
        ]
        family = _reference_family(nearby)
        for number in re.finditer(
            r"(?<![\w])\d+(?:[.,]\d+)*(?![\w])",
            match.group(0),
        ):
            normalized = _normalize_legal_code(number.group(0))
            references.add(f"{normalized}:{family}" if family else normalized)
    for match in _STANDALONE_CODE_REFERENCE_RE.finditer(value):
        normalized = _normalize_legal_code(match.group("number"))
        family = _reference_family(match.group("family"))
        references.add(f"{normalized}:{family}")
    return frozenset(references)


@lru_cache(maxsize=1024)
def _hard_clause_boundaries(value: str) -> tuple[int, ...]:
    return tuple(
        position
        for position, _ in _hard_clause_boundary_spans(value)
    )


def _local_clause_prefix(value: str, start: int) -> str:
    boundaries = _hard_clause_boundaries(_relation_syntax_surface(value))
    boundary_index = bisect_left(boundaries, start) - 1
    boundary = boundaries[boundary_index] if boundary_index >= 0 else -1
    return value[max(boundary + 1, start - 80):start]


def _hard_clause_bounds(
    value: str,
    start: int,
    end: int,
) -> tuple[int, int]:
    boundaries = _hard_clause_boundaries(_relation_syntax_surface(value))
    left_index = bisect_left(boundaries, start) - 1
    right_index = bisect_left(boundaries, end)
    left = boundaries[left_index] if left_index >= 0 else -1
    right = (
        boundaries[right_index]
        if right_index < len(boundaries)
        else len(value)
    )
    return left + 1, right


def _literal_hard_clause_bounds(
    value: str,
    start: int,
    end: int,
) -> tuple[int, int]:
    """Bound by literal sentence punctuation without masking parentheses.

    The general syntax surface deliberately turns balanced wrappers into
    fences.  Permission clauses are the narrow exception: a parenthesized
    ``(после того, как получит разрешение ...)`` still governs the adjacent
    action, while literal ``.;!?`` and newlines must remain hard boundaries.
    """

    boundary_surface = _relation_identity_boundary_surface(value)
    boundaries = tuple(
        position
        for position, _split_end in _hard_clause_boundary_spans(
            boundary_surface
        )
    )
    left_index = bisect_left(boundaries, start) - 1
    right_index = bisect_left(boundaries, end)
    left = boundaries[left_index] if left_index >= 0 else -1
    right = (
        boundaries[right_index]
        if right_index < len(boundaries)
        else len(value)
    )
    return left + 1, right


def _bounded_clause(value: str, start: int, end: int) -> str:
    left, right = _hard_clause_bounds(value, start, end)
    return value[left:right]


_SOFT_RELATION_SEPARATOR_RE = re.compile(
    r",\s*(?:(?:а(?!\s+(?:также|именно)\b)|но|однако|зато)|"
    r"(?:затем|далее|после\s+чего))\s+",
    re.IGNORECASE,
)
_COORDINATING_CONJUNCTION_RE = re.compile(
    r"(?P<separator>,?\s+)(?P<connector>и|а|но)\s+",
    re.IGNORECASE,
)
_OPEN_FINITE_PREDICATE_FRAGMENT = (
    r"[а-яё-]{3,}(?:"
    r"ается|аются|яются|уется|уются|ется|ются|ится|атся|ятся|утся|"
    r"ает|ают|яют|яет|уют|ует|ит|ят|ут|"
    r"ться|чь|ть|ти|"
    r"ил|ила|или|ило|ал|ала|али|ало|ыл|ыла|ыли|ыло|"
    r"ен|ена|ено|ены|ан|ана|ано|аны|ян|яна|яно|яны"
    r")"
)
_OPEN_FINITE_PREDICATE_RE = re.compile(
    rf"\b(?P<action>{_OPEN_FINITE_PREDICATE_FRAGMENT})\b",
    re.IGNORECASE,
)
_RELATION_BOUNDED_IRREGULAR_FINITE_RE = re.compile(
    r"\b(?:"
    r"дал|дала|дало|дали|был|была|было|были|"
    r"взял|взяла|взяло|взяли|ел|ела|ели|пил|пила|пили|"
    r"(?:(?:при|по|у|с|за|от|под|пере|вы)?ня)(?:л|ла|ло|ли)|"
    r"(?:(?:вы|при|у|за|пере|про|от|под|в|воз|вос)н[её]с)"
    r"(?:ла|ло|ли)?|"
    r"(?:уш|приш|вош|выш|переш|прош|подош|отош|обош|заш)"
    r"(?:[её]л|ла|ло|ли)|"
    r"(?:сч[её]л|сочла|сочло|сочли|уч[её]л|учла|учло|учли)|"
    r"(?:(?:пере|при|вы|от|за|по|про|на|с|у)?да)(?:ет|ёт|ют)|"
    r"(?:ид|вед|нес|бер|жив|жд|зов|вез|раст)(?:ет|ёт|ут)|"
    r"(?:призна|созда|изда)(?:ет|ёт|ют)|"
    r"закрыт(?:а|о|ы)?"
    r")\b",
    re.IGNORECASE,
)
_STRICT_OPEN_FINITE_PREDICATES = frozenset(
    {
        # Personal custody, confiscation and dissolution are high-impact
        # legal effects.  A generated mandatory statement must never become
        # source-free merely because the verb is outside the older closed
        # action scanner.
        "open:арест",
        "open:конфиск",
        "open:распуск",
        # Institutional termination is a high-impact state change even when
        # the concrete organization noun is outside the closed object lexicon.
        "open:ликвид",
        # ``X применяется к Y`` is role-sensitive: swapping X and Y reverses
        # the legal rule.
        "open:примен",
    }
)
_STRICT_GENERIC_PATIENT_PREDICATES = frozenset(
    {
        # These high-impact transitive actions regularly govern human or
        # organization nouns outside the closed object dictionary.  Keep a
        # bounded lexical patient instead of silently dropping the role.
        "закры",
        "депортир",
        "выдвор",
        "освобод",
        "обыск",
        "задерж",
        "допусти",
        "предъяв",
        "утверд",
        "возбуд",
        "завер",
    }
)
_RELATION_PREDICATE_RE = re.compile(
    r"\b(?:"
    r"аннулир|отозв|отзов|изъя|изыма|изым|замороз|приостанов|приостанав|"
    r"отмен|лиш(?!ь\b)|прекращ|утрач|"
    r"выда|предостав|оформ|подпис|выпис|присва|депорт|выдвор|"
    r"налож|назнач|взыск|штраф|оштраф|"
    r"подтвержд|провер|выплач|компенс|"
    r"привлека|предусматрива|наказыва|действ|регулир|"
    r"увольн|запрещ|осуществл|выбира|устанавлива|закро|"
    r"постанов|разреш|обсужд|рассматр|упомина"
    r")\w*\b|"
    rf"\b{_OPEN_FINITE_PREDICATE_FRAGMENT}\b",
    re.IGNORECASE,
)
_COORDINATED_LICENSE_ACTION_RE = re.compile(
    r"^(?:аннулир|отозв|отзов|изъя|изыма|изым|замороз|приостанов|приостанав|"
    r"отмен|лиш(?!ь\b)|прекращ)\w*\b",
    re.IGNORECASE,
)
_EXPLICIT_CLAUSE_CONNECTOR_RE = re.compile(
    r",\s*(?:а\s+также|прич[её]м|тогда\s+как|"
    r"кроме\s+того|при\s+этом|вместе\s+с\s+тем),?\s+",
    re.IGNORECASE,
)
_EXPLICIT_RELATION_SUBJECT_RE = re.compile(
    r"\b(?:"
    r"(?:сотрудник\w*\s+)?(?:дорожн\w*\s+)?полиц\w*|шериф\w*|"
    r"суд(?:ы|ья|ьи)?|прокуратур\w*|прокурор\w*|"
    r"(?:вице-)?губернатор\w*|организаци\w*|"
    r"правительств\w*|парламент\w*|мэр\w*|"
    r"(?:федеральн|региональн)\w*\s+бюро|"
    r"[a-z]{2,12}"
    r")\b",
    re.IGNORECASE,
)
_RELATION_GOVERNED_PERSON_SUBJECT_RE = re.compile(
    r"\b(?:заявител\w*|владел(?:ец|ьц\w*)|собственник\w*|"
    r"граждан\w*|лиц(?:о|а|у|ом|е|ы|ам|ами|ах)?)\b",
    re.IGNORECASE,
)


def _relation_has_fresh_subject(value: str) -> bool:
    """Detect a new clause subject without truncating condition bodies.

    Governed people such as an applicant or owner are meaningful subject
    fences between coordinated predicates, but they may also be the subject
    *inside* a long ``если ...`` condition.  Keeping them out of the older
    institutional boundary regex prevents that condition from being cut at
    its first word while still stopping unsafe subject inheritance.
    """

    return (
        _EXPLICIT_RELATION_SUBJECT_RE.search(value) is not None
        or _RELATION_GOVERNED_PERSON_SUBJECT_RE.search(value) is not None
    )


def _relation_premodal_actor_group_is_nominative(value: str) -> bool:
    """Require every institutional head in a pre-modal group to be a subject.

    The complete actor grammar is intentionally case-tolerant because it is
    reused for passive and oblique roles.  A suffix such as ``прокурору и
    прокуратура`` can therefore look like a group even though its first member
    is the dative patient of an earlier clause.  Before suppressing a real
    clause separator, prove nominative subject morphology for every Russian
    head; already-bounded ASCII agencies are case-neutral.
    """

    scan = _relation_delimited_scan(value)
    if scan.malformed:
        return False
    syntax = list(value)
    for start, end, kind, _contract in (
        _relation_exact_identity_contract_spans(value, scan)
    ):
        if (
            kind == "parenthetical"
            and _relation_complete_actor_group(value[start + 1:end - 1])
            is not None
        ):
            # A complete actor expression wrapped in parentheses is grouping
            # syntax, not an opaque identity tail.  Its leaves still have to
            # prove nominative case: ``(to the Court and Prosecutor's Office)
            # and the Governor must ...`` cannot borrow only the final
            # nominative member and hide the oblique branch in a name span.
            continue
        syntax[start:end] = " " * (end - start)
    syntax_surface = "".join(syntax)
    found = False
    for head in _RELATION_POSTPOSED_ACTOR_HEAD_RE.finditer(syntax_surface):
        found = True
        if _RELATION_POSTPOSED_NOMINATIVE_ACTOR_RE.fullmatch(
            head.group("actor").strip()
        ) is None:
            return False
    for _head in _RELATION_POSTPOSED_ASCII_ACTOR_HEAD_RE.finditer(
        syntax_surface
    ):
        found = True
    return found


def _relation_premodal_prefix_is_complete_document_patient(value: str) -> bool:
    """Prove a typed document plus its complete bounded owner before actor."""

    surface = value.strip(" \t,;:—–-")
    if not surface:
        return False
    candidates = tuple(
        candidate
        for candidate in _relation_object_candidates(surface)
        if candidate[2] in _RELATION_DOCUMENT_PATIENT_OBJECTS
        and (
            candidate[0] == 0
            or _relation_anytime_complete_patient_qualifier_prefix(
                surface[:candidate[0]]
            )
        )
    )
    if any(
        _relation_anytime_complete_patient_surface(
            surface,
            direct_object=object_name,
        )
        for _start, _end, object_name in candidates
    ):
        return True
    for _start, object_end, _object_name in candidates:
        cursor = object_end
        whitespace = re.match(r"\s*", surface[cursor:])
        assert whitespace is not None
        scope = _RELATION_ANYTIME_PATIENT_SCOPE_RE.match(
            surface,
            cursor + whitespace.end(),
        )
        if scope is not None:
            cursor = scope.end()
        owner_surface = surface[cursor:]
        if (
            owner_surface.strip()
            and _closed_uk_object_first_owner_surface_contract(owner_surface)
        ):
            return True
    return False


def _relation_bounded_leading_subject_adjunct_is_owned(value: str) -> bool:
    """Prove one whole nominal condition or wrapped temporal adjunct.

    This helper is deliberately narrower than the general condition parser.
    It is used only for material immediately before a separately proved
    nominative subject.  A nominal ``при условии ...`` phrase may contain
    an institutional genitive (``решения суда``), while a complete
    parenthetical temporal phrase may frame the same subject.  Neither form
    may hide a modal, an unbounded finite clause or a hard separator.
    """

    surface = value.strip()
    if surface.endswith(","):
        surface = surface[:-1].rstrip()
    if not surface or surface.endswith(","):
        return False
    scan = _relation_delimited_scan(surface)
    if scan.malformed:
        return False

    nominal_condition = re.fullmatch(
        r"(?:только\s+)?при\s+услови\w*\s+"
        r"(?P<body>[^,;.!?\r\n]{1,180})",
        surface,
        re.IGNORECASE,
    )
    if nominal_condition is not None:
        body = nominal_condition.group("body").strip()
        return bool(
            body
            and _RELATION_MODAL_TOKEN_RE.search(body) is None
            and not any(
                _relation_bounded_predicate_is_finite(
                    predicate,
                    irregular=irregular,
                )
                for predicate, irregular in (
                    _relation_bounded_predicate_candidates(body)
                )
            )
        )

    if (
        surface[:1] not in {"(", "["}
        or surface[-1:] != {"(": ")", "[": "]"}[surface[0]]
        or not any(
            start == 0 and end == len(surface)
            for start, end in scan.spans
        )
    ):
        return False
    inner = surface[1:-1].strip()
    if _relation_supported_compound_temporal_adjunct(inner):
        return True
    temporal = re.fullmatch(
        r"(?:после|до|перед)\s+"
        r"(?P<body>[^,;.!?\r\n]{1,180})",
        inner,
        re.IGNORECASE,
    )
    if temporal is None:
        return False
    body = temporal.group("body").strip()
    return bool(
        body
        and _RELATION_MODAL_TOKEN_RE.search(body) is None
        and not any(
            _relation_bounded_predicate_is_finite(
                predicate,
                irregular=irregular,
            )
            for predicate, irregular in (
                _relation_bounded_predicate_candidates(body)
            )
        )
    )


def _relation_premodal_prefix_is_fully_owned(
    value: str,
    *,
    actor_group_surface: str,
) -> bool:
    """Prove every word before one complete pre-modal actor expression.

    Merely failing to recognise a previous finite verb is not evidence that
    arbitrary text belongs to the following actor.  Suppress the connector
    only when the prefix is empty, one complete typed patient/owner, or a
    bounded adjunct that the shared grammar removes without residue.
    """

    if not value.strip(" \t,;:—–-"):
        return True
    # Object-first syntax may carry a genuinely coordinated patient before
    # the operative actor (``license and pass the commission revokes``).
    # Prove every list member through the same typed-patient grammar instead
    # of treating the conjunction as free text.  A far clause connector still
    # fails because it cannot be consumed as a complete patient expression.
    if _relation_bounded_patient_expression_is_supported(value):
        return True
    if _relation_premodal_prefix_is_complete_document_patient(value):
        return True
    if _relation_bounded_leading_subject_adjunct_is_owned(value):
        return True

    permission_masked = _relation_mask_permission_roles(value)
    if not permission_masked.strip(" \t,;:()[]{}—–-"):
        return True

    detention_masked = list(value)
    for start, end in _closed_uk_bounded_detention_context_spans(value):
        detention_masked[start:end] = " " * (end - start)
    if not "".join(detention_masked).strip(" \t,;:()[]{}—–-"):
        return True

    temporal_scan = _relation_delimited_scan(value)
    temporal_adjunct = re.fullmatch(
        r"\s*(?:после|до|перед)\s+"
        r"(?P<body>[^,;.!?\r\n]{1,180})\s*,?\s*",
        temporal_scan.masked,
        re.IGNORECASE,
    )
    if (
        temporal_adjunct is not None
        and not temporal_scan.malformed
        and _RELATION_MODAL_TOKEN_RE.search(temporal_adjunct.group("body"))
        is None
        and _EXPLICIT_RELATION_SUBJECT_RE.search(
            temporal_adjunct.group("body")
        )
        is None
        and not any(
            _relation_bounded_predicate_is_finite(
                predicate,
                irregular=irregular,
            )
            for predicate, irregular in _relation_bounded_predicate_candidates(
                temporal_adjunct.group("body")
            )
        )
    ):
        return True

    combined = value + actor_group_surface
    reduced = _relation_prefix_without_adjuncts(combined).strip(
        " \t,;:—–-"
    )
    expected = actor_group_surface.strip(" \t,;:—–-")
    return " ".join(reduced.split()).casefold() == " ".join(
        expected.split()
    ).casefold()


def _relation_connector_is_inside_complete_premodal_actor(
    value: str,
    *,
    connector_start: int,
    connector_end: int,
    following_predicate_start: int,
    clause_start: int | None = None,
) -> bool | None:
    """Prove that a conjunction joins one complete governed subject.

    Broad predicate discovery can mistake an attributive patient modifier for
    an earlier finite verb (``Active licence ... police and prosecutor must
    revoke``).  The conjunction still cannot be a clause separator when a
    complete actor group spans it and ends immediately before the governing
    modal.  A real preceding clause is not consumed because its predicate or
    patient cannot form an actor-group leaf.
    """

    syntax_value = _relation_boolean_syntax_surface(value)
    prefix = syntax_value[connector_end:following_predicate_start]
    modals = tuple(_RELATION_MODAL_TOKEN_RE.finditer(prefix))
    subject_end = (
        connector_end + min(match.start() for match in modals)
        if modals
        else following_predicate_start
    )
    while subject_end > connector_end and value[subject_end - 1].isspace():
        subject_end -= 1
    hard_start = max(
        syntax_value.rfind(".", 0, connector_start) + 1,
        syntax_value.rfind(";", 0, connector_start) + 1,
        syntax_value.rfind("\n", 0, connector_start) + 1,
        clause_start or 0,
    )
    predicate_match = _RELATION_WORD_RE.match(
        syntax_value,
        following_predicate_start,
    )
    if predicate_match is not None:
        subject_proof = _relation_bounded_subject_proof_before_predicate(
            syntax_value[hard_start:following_predicate_start],
            predicate_match.group(0),
            require_owned_prefix=True,
        )
        if (
            subject_proof is not None
            and hard_start + subject_proof.actor_start <= connector_start
            and connector_end <= hard_start + subject_proof.actor_end
        ):
            # The actor span is proved independently from a following SOV
            # patient or temporal/permission adjunct.  This keeps the inner
            # connector in ``prosecutor and governor [licence] revoke`` owned
            # by one subject even after a preceding clause separator.
            return True
    scan = _relation_delimited_scan(value[hard_start:subject_end])
    if scan.malformed:
        return False
    saw_complete_group = False
    for token in _RELATION_WORD_RE.finditer(
        syntax_value,
        hard_start,
        connector_start,
    ):
        candidate_start = token.start()
        while True:
            opener = candidate_start - 1
            while opener >= hard_start and syntax_value[opener].isspace():
                opener -= 1
            if opener < hard_start or syntax_value[opener] not in "([":
                break
            candidate_start = opener
        surface = value[candidate_start:subject_end].strip(" \t,;:—–-")
        if not surface:
            continue
        group = (
            _relation_actor_group_with_joint_focus(surface)
            or _relation_complete_actor_group(surface)
        )
        if group is not None:
            saw_complete_group = True
            if not _relation_premodal_actor_group_is_nominative(surface):
                continue
            preceding_surface = value[hard_start:candidate_start]
            preceding = _relation_delimited_scan(
                preceding_surface
            )
            if (
                preceding.malformed
                or not _relation_premodal_prefix_is_fully_owned(
                    preceding_surface,
                    actor_group_surface=surface,
                )
            ):
                # ``Court notified the prosecutor and the prosecutor's office
                # must revoke`` may expose an actor-looking suffix only after
                # a real completed predicate.  Test that prefix *outside* the
                # proved group.  A complete typed patient/owner prefix is also
                # one role: ``licence of organization Filial`` must not turn
                # its proper name into a past-tense verb merely because the
                # operative actor follows it.
                return False
            return True
    return False if saw_complete_group else None


@dataclass(frozen=True)
class _RelationBoundedSubjectProof:
    """One nominative actor span plus fully owned pre-predicate material."""

    actor_start: int
    actor_end: int
    prefix_end: int


def _relation_mask_equal_length(
    value: str,
    patterns: Iterable[re.Pattern[str]],
) -> str:
    """Mask regex spans without invalidating offsets used by subject proofs."""

    masked = list(value)
    for pattern in patterns:
        for match in pattern.finditer(value):
            masked[match.start():match.end()] = " " * (match.end() - match.start())
    return "".join(masked)


