def _relation_action_modifier_key(value: str) -> str:
    """Canonicalize bounded compound spellings without losing semantics."""

    folded = " ".join(value.casefold().replace("ё", "е").split())
    if folded == "сразу же":
        return "сразу"
    if folded == "еще раз":
        return "еще-раз"
    return folded


