def _relation_productive_nominal_action_modifier_key(value: str) -> str:
    """Map one agreeing nominal adjective to a lossless adverbial key."""

    match = _RELATION_PRODUCTIVE_NOMINAL_ACTION_MODIFIER_RE.fullmatch(value)
    if match is None:
        return ""
    stem = match.group("stem").casefold().replace("ё", "е")
    return stem + ("и" if stem.endswith("ск") else "о")


