def _relation_bounded_weapon_scope_after_whitespace(
    value: str,
) -> re.Match[str] | None:
    """Match one exact weapon scope after presentation whitespace only."""

    whitespace = re.match(r"\s*", value)
    assert whitespace is not None
    return _RELATION_BOUNDED_PATIENT_SCOPE_TAIL_RE.match(
        value,
        whitespace.end(),
    )


def _relation_scope_adjective_agrees_with_patient(
    patient_surface: str,
    adjective_surface: str,
    *,
    role: str,
    family: str,
    adjective_pattern: str,
) -> bool:
    """Prove one postpositive scope adjective in the patient's real case."""

    if re.fullmatch(
        adjective_pattern,
        adjective_surface.strip(),
        re.IGNORECASE,
    ) is None:
        return False
    features = _relation_patient_head_features(
        family,
        patient_surface,
        role=role,
    )
    return bool(
        features
        and _relation_patient_leading_modifiers_agree(
            adjective_surface,
            features=features,
            role=role,
            family=family,
            head=patient_surface,
        )
    )


def _relation_weapon_adjective_agrees_with_license(
    license_surface: str,
    adjective_surface: str,
    *,
    role: str,
) -> bool:
    return _relation_scope_adjective_agrees_with_patient(
        license_surface,
        adjective_surface,
        role=role,
        family="license",
        adjective_pattern=_RELATION_BOUNDED_WEAPON_ADJECTIVE_PATTERN,
    )


def _relation_patient_scope_match_contract(
    match: re.Match[str],
) -> tuple[str, ...]:
    """Keep every conjunct and its operator in a bounded weapon scope."""

    groups = match.groupdict()
    connector = groups.get("scope_connector_acc") or groups.get(
        "scope_connector_gen"
    )
    extra = groups.get("scope_extra_acc") or groups.get("scope_extra_gen")
    if not connector or not extra:
        return ("scope:weapon",)
    operator = "and" if connector.casefold() == "и" else "or"
    extra_family = (
        "special-means"
        if extra.casefold().startswith("спецсредств")
        else "ammunition"
    )
    return (
        "scope:weapon",
        "scope-op:" + operator,
        "scope:" + extra_family,
    )

