def _relation_strip_governing_decision_suffix(value: str) -> str:
    """Return the active subject before a bounded decision-to-act phrase."""

    decision = re.search(
        r"\b(?:приня\w*|вынес\w*)\s+"
        r"(?:(?:[а-яё-]{3,}(?:ое|ее|ая|яя|ый|ий))\s+){0,4}"
        r"решени\w*"
        r"(?:\s+(?:немедленно|повторно|окончательно|затем|вновь|"
        r"лично|сразу)){0,4}(?:\s+(?:о|об))?\s*$|"
        r"\b(?:постанови\w*|решил\w*)"
        r"(?:\s+(?:немедленно|повторно|окончательно|затем|вновь|"
        r"лично|сразу)){0,4}\s*$",
        value,
        re.IGNORECASE,
    )
    if decision is None:
        return value
    subject = value[:decision.start()].rstrip()
    if re.search(r"\bне\s*$", subject, re.IGNORECASE) is not None:
        # ``Суд не вынес решение об отзыве`` does not prove that the court
        # performed the embedded revocation.  A negative non-event has no
        # operative actor for the embedded action; returning the whole phrase
        # would manufacture actor keys such as ``суд не постановил``.
        return ""
    return re.sub(
        r"(?:\s+\b(?:немедленно|повторно|окончательно|затем|вновь|"
        r"лично|сразу)\b){1,4}\s*$",
        "",
        subject,
        flags=re.IGNORECASE,
    ).rstrip()


@dataclass(frozen=True)
class _GoverningDecisionProjection:
    """One bounded decision that directly owns a nominal legal action.

    The parent decision is semantic evidence for its direct ``о/об X``
    complement only.  Actor identity, polarity and modality remain owned by
    the parent instead of being re-invented from the nested action noun.
    """

    actor: str
    modality: str
    polarity: str


_GOVERNING_DECISION_CONTROLLER_RE = re.compile(
    r"\b(?:приня\w*|вынес\w*|постанови\w*|решил\w*)\b",
    re.IGNORECASE,
)
_GOVERNING_DECISION_NONPERFORMED_RE = re.compile(
    r"\b(?:отказ\w*|планир\w*|намерева\w*|предлага\w*|"
    r"обсужда\w*|рассматрива\w*)\b",
    re.IGNORECASE,
)


def _relation_governing_decision_projection(
    value: str,
    action_start: int,
    action_end: int,
    *,
    projection: _PredicateRelation | None = None,
) -> _GoverningDecisionProjection | None:
    """Project a direct decision-to-act parent without losing its contract."""

    action_text = value[action_start:action_end]
    if (
        _relation_event(action_text) != "nominal"
        or _relation_predicate_key(action_text)
        != "regulated_revocation"
    ):
        return None
    relation = projection or _predicate_relation(
        value,
        action_start,
        action_end,
    )
    local_start = action_start - relation.start
    if not 0 <= local_start <= len(relation.text):
        return None
    governing_prefix = relation.text[:local_start].strip()
    decision_subject = _relation_strip_governing_decision_suffix(
        governing_prefix
    )
    if decision_subject == governing_prefix:
        return None

    # A controller such as ``refused/plans to issue a decision`` does not
    # assert the decision or its complement.  Keep the fence structural: an
    # unrelated finite predicate before the proved decision suffix also
    # prevents actor/modality inheritance.
    if (
        _GOVERNING_DECISION_NONPERFORMED_RE.search(decision_subject)
        is not None
        or _INTERVENING_FINITE_PREDICATE_RE.search(decision_subject)
        is not None
    ):
        return None

    negative_modal = re.search(
        r"\bне\s+(?:может|могут|вправе|"
        r"должен|должна|должно|должны|обязан\w*|"
        r"име\w*\s+право)\b",
        decision_subject,
        re.IGNORECASE,
    )
    negative_asserted = re.search(
        r"\bне\s+(?:приня\w*|вынес\w*|постанови\w*|решил\w*)\b",
        governing_prefix,
        re.IGNORECASE,
    )
    polarity = (
        "negative"
        if negative_modal is not None or negative_asserted is not None
        else "positive"
    )
    if _RELATION_MANDATORY_RE.search(decision_subject) is not None:
        modality = "mandatory"
    elif _RELATION_MAY_RE.search(decision_subject) is not None:
        modality = "may"
    elif _GOVERNING_DECISION_CONTROLLER_RE.search(governing_prefix):
        modality = "definite"
    else:
        return None

    actor_surface = _relation_prefix_without_adjuncts(
        decision_subject
    ).strip(" \t,;:—–-")
    actor = (
        _relation_complete_postposed_actor_key(actor_surface)
        if actor_surface
        else ""
    )
    if actor is None or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
        actor = ""
    return _GoverningDecisionProjection(
        actor=actor,
        modality=modality,
        polarity=polarity,
    )


def _authorities_for_action(
    clause: str,
    action_start: int,
    action_end: int,
    *,
    allow_issuer_anaphora: bool = False,
) -> set[str]:
    authorities: set[str] = set()
    projection = _predicate_relation(
        clause,
        action_start,
        action_end,
    )
    relation = projection.text
    authority_relation = _relation_mask_permission_roles(relation)
    authority_relation = _relation_mask_positive_anytime_scopes(
        authority_relation,
        projection,
    )
    local_action_start = action_start - projection.start
    local_action_end = action_end - projection.start
    governing_decision = _relation_governing_decision_projection(
        clause,
        action_start,
        action_end,
        projection=projection,
    )
    if governing_decision is not None and governing_decision.actor:
        decision_actor_authority = (
            _qualitative_authority_for_relation_actor(
                governing_decision.actor
            )
        )
        if decision_actor_authority:
            authorities.add(decision_actor_authority)
    prefix = authority_relation[
        max(0, local_action_start - 260):local_action_start
    ]
    suffix = authority_relation[
        local_action_end:min(len(relation), local_action_end + 180)
    ]

    for authority, pattern in _AUTHORITY_RELATIVE_PATTERNS:
        if re.search(
            pattern
            + r"(?:\s+\w+){0,3}\s*,\s*"
            r"котор(?:ая|ый|ое|ые)"
            r"(?:\s*\([^)]{0,180}\)|(?:\s+\w+){0,8})?\s*$",
            prefix,
            re.IGNORECASE,
        ):
            authorities.add(authority)

    for authority, pattern in _AUTHORITY_ACTIVE_PATTERNS:
        if re.search(
            pattern
            + r"(?:\s*,[^,;]{0,140},)?\s*"
            r"(?:(?:вправе|может|могут|обязан\w*|"
            r"долж(?:ен|на|но|ны)|име\w*\s+право)\s+|"
            r"(?:приня\w*|вынес\w*)\s+решени\w*\s+"
            r"(?:о|об)?\s*|постанови\w*\s+)?$",
            prefix,
            re.IGNORECASE,
        ):
            authorities.add(authority)

    # Preserve every actor in a clean coordinated subject list instead of
    # letting the authority nearest to the modal hide the earlier ones:
    # ``суд или прокуратура могут выдать ордер``.  The residue check is
    # deliberately fail-closed; ordinary prose around the named authorities
    # is not flattened into a roster.
    coordinated_actor_block = re.sub(
        r"\b(?:вправе|может|могут|обязан\w*|"
        r"долж(?:ен|на|но|ны)|име\w*\s+право)\s*$",
        "",
        prefix,
        flags=re.IGNORECASE,
    )
    coordinated_matches = [
        (match.start(), match.end(), authority)
        for authority, pattern in _AUTHORITY_ACTIVE_PATTERNS
        for match in re.finditer(
            pattern,
            coordinated_actor_block,
            re.IGNORECASE,
        )
    ]
    coordinated_authorities = {
        authority for _, _, authority in coordinated_matches
    }
    if len(coordinated_authorities) >= 2:
        residue = coordinated_actor_block
        for start, end, _ in sorted(
            coordinated_matches,
            key=lambda item: (item[0], item[1]),
            reverse=True,
        ):
            residue = residue[:start] + " " * (end - start) + residue[end:]
        residue = re.sub(
            r"\b(?:и|или|либо|"
            r"верховн\w*|федеральн\w*|региональн\w*|"
            r"генеральн\w*|главн\w*|окружн\w*|миров\w*)\b",
            " ",
            residue,
            flags=re.IGNORECASE,
        )
        if re.fullmatch(r"[\s,\/—–-]*", residue):
            authorities.update(coordinated_authorities)

    # Russian legal prose also uses inverted word order:
    # ``ордер выписывает министр, судья или губернатор``.  Treat a suffix as
    # a postposed subject list only when its first meaningful token is an
    # authority; later actor mentions therefore cannot leak backwards.
    postposed_matches = [
        (match.start(), authority)
        for authority, pattern in _AUTHORITY_ACTIVE_PATTERNS
        for match in re.finditer(pattern, suffix, re.IGNORECASE)
    ]
    if postposed_matches:
        first_actor_start = min(position for position, _ in postposed_matches)
        postposed_lead = suffix[:first_actor_start]
        if re.fullmatch(
            r"[\s,:—–-]*(?:(?:верховн|генеральн|главн|"
            r"федеральн|региональн|окружн|миров)\w*\s+){0,3}",
            postposed_lead,
            re.IGNORECASE,
        ):
            authorities.update(
                authority for _, authority in postposed_matches
            )

    for authority, pattern in _AUTHORITY_DATIVE_PATTERNS:
        if re.search(
            pattern
            + r"(?:\s+\w+){0,3}\s+"
            r"(?:разреша|допуска)\w*\s+$",
            prefix,
            re.IGNORECASE,
        ):
            authorities.add(authority)

    if re.search(r"\bсудебн\w*\s*$", prefix, re.IGNORECASE):
        authorities.add("court")

    for authority, pattern in _AUTHORITY_INSTRUMENTAL_PATTERNS:
        suffix_before_new_temporal_relation = re.split(
            r"\b(?:после|до)\s+",
            suffix,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0]
        if re.search(
            pattern,
            suffix_before_new_temporal_relation,
            re.IGNORECASE,
        ):
            authorities.add(authority)
        for prefix_actor in re.finditer(pattern, prefix, re.IGNORECASE):
            actor_tail = prefix[prefix_actor.end():]
            if re.fullmatch(
                r"\s*(?:(?:вправе|может|могут|должн\w*|"
                r"обязан\w*)\s+)?",
                actor_tail,
                re.IGNORECASE,
            ):
                authorities.add(authority)

    for authority, pattern in _AUTHORITY_DECISION_PATTERNS:
        for decision in re.finditer(
            pattern,
            authority_relation,
            re.IGNORECASE,
        ):
            if decision.end() <= local_action_start:
                between = authority_relation[
                    decision.end():local_action_start
                ]
            elif decision.start() >= local_action_end:
                between = authority_relation[
                    local_action_end:decision.start()
                ]
            else:
                between = ""
            if _INTERVENING_FINITE_PREDICATE_RE.search(between):
                continue
            authorities.add(authority)

    # A decision authored by the named authority is evidence only when that
    # decision itself is explicitly about the current action.
    action_lexeme = re.escape(clause[action_start:action_end])
    if re.search(
        r"\bрешени\w*\s+(?:по|об|о)\s+"
        + action_lexeme
        + r"[^.!?;\n]{0,100}\bвынесенн\w*\s+"
        r"(?:верховн\w*\s+)?судом\b",
        authority_relation,
        re.IGNORECASE,
    ):
        authorities.add("court")

    if re.search(
        r"\b(?:при\s+задержани\w*|по\s+требовани\w*)"
        r"[^.!?;\n]{0,80}\b(?:сотрудниками\s+)?"
        r"правоохранительн\w*\s+орган\w*\b",
        suffix,
        re.IGNORECASE,
    ):
        authorities.add("police")
    if re.search(
        r"\bлицами,\s*уполномоченн\w*\s+на\s+выдачу\b",
        suffix,
        re.IGNORECASE,
    ):
        authorities.add("licensing_authority")

    # Keep the qualitative family projection aligned with the stricter
    # role-aware parser.  A complete actor such as ``суд округа Блейн`` or
    # ``организация Альфа`` intentionally carries more identity than the
    # qualitative claim, but its family is still court/organization in both
    # active and passive word order.  Without this bridge, an exact safe
    # active↔passive paraphrase passed the relation gate and was then
    # spuriously rejected by the older family-only coverage layer.
    relation_actor = _relation_operative_actor(
        clause,
        projection,
        action_start,
        action_end,
        event=_relation_event(clause[action_start:action_end]),
    )
    relation_authority = _qualitative_authority_for_relation_actor(
        relation_actor
    )
    shared_relation_actor = _relation_shared_coordinated_subject_actor(
        clause,
        projection,
        action_start,
    )
    complete_active_actor = _relation_complete_postposed_actor_key(
        _relation_strip_governing_decision_suffix(
            _relation_prefix_without_adjuncts(prefix).strip()
        )
    )
    complete_postposed_actor = _relation_complete_postposed_actor_key(
        authority_relation[local_action_end:]
    )
    object_first_patient = _relation_object_first_patient_parts(
        _relation_prefix_without_adjuncts(prefix)
    )
    complete_passive_actors = {
        phrase.key
        for phrase in _relation_complete_passive_actor_phrases(suffix)
    }
    if (
        relation_authority
        and (
            complete_active_actor == relation_actor
            or complete_postposed_actor == relation_actor
            or shared_relation_actor == relation_actor
            or object_first_patient is not None
            or _relation_event(clause[action_start:action_end])
            in {"present_passive", "past_passive"}
        )
    ):
        authorities.add(relation_authority)
    if (
        relation_authority == "other:management"
        and _relation_actor_is_detailed_management(relation_actor)
    ):
        # In ``руководитель государственной организации`` the organization
        # token scopes the manager; it is not a second coordinated operative
        # actor.  Keep genuinely coordinated ``руководитель и организация``
        # untouched because it does not form one detailed management key.
        authorities.discard("other:organization")
    actor_identity_is_complete = (
        bool(relation_actor)
        and len(relation_actor.split()) > 1
        and (
            complete_active_actor == relation_actor
            or complete_postposed_actor == relation_actor
            or relation_actor in complete_passive_actors
        )
    )
    if (
        relation_authority
        and actor_identity_is_complete
        and not any(
            connector in relation_actor.split()
            for connector in ("и", "или", "либо")
        )
    ):
        # Family-only qualitative matching also sees institutional nouns
        # inside a proven complete identity.  Keep the owning (first) family,
        # but do not emit a second claim for ``губернатор`` in
        # ``директор отдела ... при губернаторе`` or for ``суд`` inside an
        # organization name.  A separately parsed decision authority remains
        # protected because it is a real relation role outside the identity.
        actor_tokens = relation_actor.split()
        embedded_authorities = {
            authority
            for start in range(len(actor_tokens))
            for width in range(1, min(3, len(actor_tokens) - start) + 1)
            if (
                authority := _qualitative_authority_for_relation_actor(
                    " ".join(actor_tokens[start:start + width])
                )
            )
        }
        decision_actor = _relation_decision_authority(projection.text)
        protected_authorities = {
            relation_authority,
            _qualitative_authority_for_relation_actor(decision_actor),
        }
        authorities.difference_update(
            embedded_authorities - protected_authorities
        )

    if allow_issuer_anaphora:
        lexical_actions = [
            action
            for action in _RELATION_ACTION_RE.finditer(
                clause,
                action_start,
                action_end,
            )
            if _relation_predicate_key(action.group("action"))
            == "regulated_revocation"
        ]
        lexical_start = (
            lexical_actions[-1].start("action")
            if lexical_actions
            else action_start
        )
        lexical_end = (
            lexical_actions[-1].end("action")
            if lexical_actions
            else action_end
        )
        event = _relation_event(clause[lexical_start:lexical_end])
        if event == "past_passive":
            event_prefix = clause[
                max(0, lexical_start - 80):lexical_start
            ]
            if (
                _RELATION_MODAL_PASSIVE_PREFIX_RE.search(event_prefix)
                is not None
            ):
                event = "prospective"
        for actor in _relation_leading_anaphoric_issuer_variants(
            clause,
            lexical_start,
            lexical_end,
            predicate=_relation_predicate_key(
                clause[lexical_start:lexical_end]
            ),
            event=event,
        ):
            actor_tokens = actor.split()
            if any(
                token.startswith(("прокуратур", "прокурор"))
                for token in actor_tokens
            ):
                authorities.add("prosecutor")
            elif any(token.startswith("суд") for token in actor_tokens):
                authorities.add("court")
            elif any(
                token.startswith(("губернатор", "вице-губернатор"))
                for token in actor_tokens
            ):
                authorities.add("governor")
            elif (
                actor == "licensing_authority"
                or any(
                    token.startswith("лицензирующ")
                    for token in actor_tokens
                )
            ):
                authorities.add("licensing_authority")
            elif any(
                token.startswith(head)
                for token in actor_tokens
                for head in ("руководител", "директор", "начальник")
            ):
                authorities.add("other:management")

    syntactic_event = _relation_event(clause[action_start:action_end])
    actor_variants, guarded_actor_group = _relation_passive_actor_variants(
        projection,
        action_start,
        action_end,
        event=syntactic_event,
    )
    if not actor_variants:
        actor_variants, guarded_actor_group = _relation_active_actor_variants(
            clause,
            projection,
            action_start,
            action_end,
            event=syntactic_event,
        )
    if not actor_variants and syntactic_event == "nominal":
        actor_variants, guarded_actor_group = (
            _relation_factual_nominal_actor_variants(
                clause,
                projection,
                action_start,
                action_end,
            )
        )
    if (
        relation_authority
        and relation_actor
        and relation_actor in actor_variants
    ):
        # The role-aware parser is the source of truth for complete dotted
        # identities as well.  Family regexes see the passive spelling but
        # can miss the same active ``LSPD St. Mary``/``организация деп. X``
        # spelling at the abbreviation dot; keep both layers aligned.
        authorities.add(relation_authority)
    group_keys = tuple(
        actor
        for actor in actor_variants
        if actor.startswith("__actor_group__:")
    )
    if guarded_actor_group or group_keys:
        explicit_members = tuple(
            actor
            for actor in actor_variants
            if not actor.startswith("__actor_group__:")
        )
        group_members = set(explicit_members)
        for group_key in group_keys:
            group_members.update(
                _relation_actor_group_members_from_key(group_key)
            )
        member_authorities = {
            authority
            for actor in group_members
            if (
                authority := _qualitative_authority_for_relation_actor(
                    actor
                )
            )
        }
        # Qualitative claims are also used for non-assertive topical search
        # phrases (``отзыв пропуска судом``) and for aggregate critical-
        # authority coverage.  Retain every named family here; the stricter
        # relation truth still keeps mandatory/slash/``и/или`` groups atomic
        # and rejects a generated finite assertion that selects one member.
        authorities.update(member_authorities)

    if (
        "other:management" in authorities
        and authorities.intersection(
            {
                "court",
                "police",
                "prosecutor",
                "governor",
                "justice_minister",
                "licensing_authority",
            }
        )
        and re.search(r"\bзаместител\w*\b", prefix, re.IGNORECASE)
        and re.search(
            r"\b(?:руководител|директор|начальник)\w*\b",
            prefix,
            re.IGNORECASE,
        )
        is None
    ):
        # ``заместитель генерального прокурора`` is one specific office,
        # not two independent authorities (prosecutor + generic manager).
        # Keep management when a real management head is also named.
        authorities.discard("other:management")

    return authorities


def _relation_action_spans(
    clause: str,
    patterns: Sequence[str],
) -> list[tuple[int, int]]:
    spans: set[tuple[int, int]] = set()
    for pattern in patterns:
        for match in re.finditer(pattern, clause, re.IGNORECASE):
            spans.add(match.span("action"))
    return sorted(spans)


_LICENSE_WORD_RE = (
    r"лицензи(?:я|и|ю|ей|ею|й|ям|ями|ях)\b"
)
_LICENSE_ACTIVE_ACTION_FRAGMENT = (
    r"(?:"
    r"аннулирова(?:ть|л|ла|ли|ет|ют)|аннулиру(?:ет|ют)|"
    r"отозва(?:ть|л|ла|ли)|отзыва(?:ть|ет|ют)|"
    r"отмени(?:ть|л|ла|ли|т|ят)|отменя(?:ть|ет|ют)|"
    r"изъя(?:ть|л|ла|ли)|изыма(?:ть|ет|ют)|"
    r"лиши(?:ть|л|ла|ли|т|ат)|лиша(?:ть|ет|ют)|"
    r"заморози(?:ть|л|ла|ли|т|ят)|"
    r"приостанови(?:ть|л|ла|ли|т|ят)|"
    r"приостанавлива(?:ть|ет|ют)|"
    r"прекрати(?:ть|л|ла|ли|т|ят)|прекраща(?:ть|ет|ют)"
    r")"
)
_LICENSE_NOUN_ACTION_FRAGMENT = (
    r"(?:аннулировани|отзыв|отмен|изъяти|лишени|"
    r"заморозк|приостановлени|прекращени)\w*"
)
_LICENSE_PASSIVE_ACTION_FRAGMENT = (
    r"(?:"
    r"(?:(?:может|могут|вправе|должн\w*|обязан\w*)\s+быть\s+)"
    r"(?:им\s+|ими\s+)?"
    r"(?:аннулирован|отозван|отменен|отменён|изъят|"
    r"приостановлен|заморожен|лишен|лишён)"
    r"(?:а|о|ы)?|"
    r"(?:аннулирован|отозван|отменен|отменён|изъят|"
    r"приостановлен|заморожен|лишен|лишён)"
    r"(?:а|о|ы)?|"
    r"(?:аннулируется|аннулируются|отзывается|отзываются|"
    r"отменяется|отменяются|"
    r"изымается|изымаются|замораживается|замораживаются|"
    r"приостанавливается|приостанавливаются)|"
    r"(?:становится|становятся|признается|признаются|"
    r"считается|считаются)\s+"
    r"недействительн\w*|"
    r"подлеж(?:ит|ат)\s+(?:изъяти|аннулировани|отзыв)\w*|"
    r"недействительн\w*"
    r")"
)
_INTERVENING_FINITE_PREDICATE_RE = re.compile(
    r"\b(?:"
    r"провер|подтвержд|выплач|упомина|обсужд|рассматр|"
    r"зарегистрир|применя|предусматрива|привлека|"
    r"вед(?:[её]т|ут)|в(?:е|ё)л(?:а|и)?"
    r")\w*\b|"
    r"\b[а-яё]{3,}(?:ается|яются|уется|ются|ется|"
    r"ает|яют|ует|уют|ит|ят|ут|"
    r"ил|ила|или|ал|ала|али|"
    r"(?:ан|ян|ен)(?:а|о|ы))\b",
    re.IGNORECASE,
)
_LICENSE_OBLIQUE_CONTEXT_RE = re.compile(
    r"\b(?:наличи|отсутстви|подтверждающ|зарегистрированн|"
    r"документ|справк|сведени|копи)\w*\b|"
    r"\b(?:по|при|без|о|об|для|согласно)\s+$",
    re.IGNORECASE,
)
_LICENSE_HOLDER_CONTEXT_RE = re.compile(
    r"\b(?:у\s+)?(?:лиц|граждан|человек)\w*\s*,?\s+"
    r"(?:имеющ|обладающ)\w*\b",
    re.IGNORECASE,
)
_LICENSE_CONTAINER_CONTEXT_RE = re.compile(
    r"\b(?:копи|доверенност|заявлени|документ|справк|сведени|"
    r"разрешени|право|порядок|получени|наличи|регистраци|"
    r"уч[её]т)\w*\b",
    re.IGNORECASE,
)
_LICENSE_SUBJECT_PREFIX_RE = re.compile(
    r"\b(?:для|по|при|без|о|об|согласно)\s+$|"
    r"\b(?:копи|документ|справк|сведени)\w*\s+$",
    re.IGNORECASE,
)


def _license_gap_has_other_relation(gap: str) -> bool:
    return (
        _INTERVENING_FINITE_PREDICATE_RE.search(gap) is not None
        or re.search(
            r"\b(?:затем|после\s+этого)\b",
            gap,
            re.IGNORECASE,
        )
        is not None
    )


def _active_license_object_is_direct(
    object_text: str,
    gap: str,
) -> bool:
    if _license_gap_has_other_relation(gap):
        return False
    if (
        _LICENSE_OBLIQUE_CONTEXT_RE.search(gap)
        or _LICENSE_HOLDER_CONTEXT_RE.search(gap)
        or _LICENSE_CONTAINER_CONTEXT_RE.search(gap)
    ):
        return False
    if object_text.casefold() == "лицензию":
        return True
    # ``лицензии`` is also genitive, so require a direct/coordinated object
    # rather than a prepositional or relative mention.
    if "," in gap:
        return False
    return True


def _noun_license_object_is_direct(gap: str) -> bool:
    normalized_gap = re.sub(
        r",\s*а\s+также\s+",
        " и ",
        gap,
        flags=re.IGNORECASE,
    )
    return (
        "," not in normalized_gap
        and not _license_gap_has_other_relation(normalized_gap)
        and _LICENSE_OBLIQUE_CONTEXT_RE.search(normalized_gap) is None
        and _LICENSE_CONTAINER_CONTEXT_RE.search(normalized_gap) is None
    )


def _license_action_is_embedded_mention(
    clause: str,
    action_start: int,
) -> bool:
    prefix = clause[max(0, action_start - 180):action_start]
    return (
        re.search(
            r"\b(?:обсужда|рассматрива|упомина|описыва|"
            r"предусматрива|содерж)\w*"
            r"(?:\s+\w+){0,6}\s*$|"
            r"\b(?:уведом|сообщ)\w*(?:\s+\w+){0,5}\s+об?\s*$",
            prefix,
            re.IGNORECASE,
        )
        is not None
    )


def _instrument_revocation_spans(clause: str) -> list[tuple[int, int]]:
    spans: set[tuple[int, int]] = set()

    for invalidation in re.finditer(
        r"\bлицензи(?:я|и)\b[^.!?;\n]{0,96}"
        r"\b(?P<action>(?:станови|счита)\w*\s+"
        r"недействительн\w*)\b",
        clause,
        re.IGNORECASE,
    ):
        spans.add(invalidation.span("action"))

    for expiry in re.finditer(
        r"\bлицензи(?:я|и)\b[^.!?;\n]{0,64}"
        r"\b(?P<action>(?:утрачива|теря)\w*\s+сил\w*)\b",
        clause,
        re.IGNORECASE,
    ):
        spans.add(expiry.span("action"))

    for license_match in re.finditer(
        rf"\b(?P<license>{_LICENSE_WORD_RE})",
        clause,
        re.IGNORECASE,
    ):
        subject_prefix = clause[
            max(0, license_match.start() - 48):license_match.start()
        ]
        if _LICENSE_SUBJECT_PREFIX_RE.search(subject_prefix):
            continue
        search_end = min(len(clause), license_match.end() + 180)
        for action in re.finditer(
            rf"\b(?P<action>{_LICENSE_PASSIVE_ACTION_FRAGMENT})\b",
            clause[license_match.end():search_end],
            re.IGNORECASE,
        ):
            action_start = license_match.end() + action.start("action")
            action_end = license_match.end() + action.end("action")
            projection = _predicate_relation(
                clause,
                action_start,
                action_end,
            )
            if not (
                projection.start
                <= license_match.start()
                < projection.end
            ):
                continue
            gap = clause[license_match.end():action_start]
            if "," in gap:
                compact_gap = re.sub(
                    r",\s*(?:котор\w*|выданн\w*|полученн\w*)"
                    r"[^,]{0,120},",
                    " ",
                    gap,
                    flags=re.IGNORECASE,
                )
            else:
                compact_gap = gap
            if _license_gap_has_other_relation(compact_gap):
                continue
            spans.add((action_start, action_end))
            break

    for action in re.finditer(
        rf"\b(?P<action>{_LICENSE_PASSIVE_ACTION_FRAGMENT}|"
        r"изъяти\w*\s+подлеж(?:ит|ат))\b",
        clause,
        re.IGNORECASE,
    ):
        projection = _predicate_relation(
            clause,
            action.start("action"),
            action.end("action"),
        )
        search_end = min(projection.end, action.end() + 96)
        for subject in re.finditer(
            r"\b(?P<subject>лицензия|лицензии)\b",
            clause[action.end():search_end],
            re.IGNORECASE,
        ):
            subject_start = action.end() + subject.start("subject")
            gap = clause[action.end():subject_start]
            if (
                _license_gap_has_other_relation(gap)
                or _LICENSE_OBLIQUE_CONTEXT_RE.search(gap)
            ):
                continue
            spans.add(action.span("action"))
            break

    for action in re.finditer(
        rf"\b(?P<action>{_LICENSE_ACTIVE_ACTION_FRAGMENT})\b",
        clause,
        re.IGNORECASE,
    ):
        if _license_action_is_embedded_mention(
            clause,
            action.start("action"),
        ):
            continue
        projection = _predicate_relation(
            clause,
            action.start("action"),
            action.end("action"),
        )
        local_action_start = action.start("action") - projection.start
        local_action_end = action.end("action") - projection.start
        object_first_prefix = _relation_prefix_without_adjuncts(
            projection.text[:local_action_start]
        ).strip()
        object_first_suffix = projection.text[local_action_end:]
        if (
            re.fullmatch(
                r"(?:(?:эт|данн|соответствующ|нов)\w*\s+){0,3}"
                r"лицензию",
                object_first_prefix,
                re.IGNORECASE,
            )
            is not None
            and (
                _relation_complete_postposed_actor_key(object_first_suffix)
                is not None
                or _RELATION_POSTPOSED_AGENCY_RE.match(
                    object_first_suffix
                )
                is not None
            )
        ):
            # Accusative ``лицензию`` makes the reversed order unambiguous:
            # ``лицензию может аннулировать суд``.  Preserve its authority
            # claim; masculine nom/acc forms are rejected by the shared
            # output ambiguity guard instead.
            spans.add(action.span("action"))
            continue
        search_end = min(projection.end, action.end() + 128)
        for object_match in re.finditer(
            r"\b(?P<object>лицензию|лицензии)\b",
            clause[action.end():search_end],
            re.IGNORECASE,
        ):
            object_start = action.end() + object_match.start("object")
            gap = clause[action.end():object_start]
            if _active_license_object_is_direct(
                object_match.group("object"),
                gap,
            ):
                spans.add(action.span("action"))
                break

    for action in re.finditer(
        rf"\b(?P<action>{_LICENSE_NOUN_ACTION_FRAGMENT})\b",
        clause,
        re.IGNORECASE,
    ):
        if _license_action_is_embedded_mention(
            clause,
            action.start("action"),
        ):
            continue
        projection = _predicate_relation(
            clause,
            action.start("action"),
            action.end("action"),
        )
        search_end = min(projection.end, action.end() + 112)
        for object_match in re.finditer(
            r"\bлицензии\b",
            clause[action.end():search_end],
            re.IGNORECASE,
        ):
            object_start = action.end() + object_match.start()
            gap = clause[action.end():object_start]
            if _noun_license_object_is_direct(gap):
                spans.add(action.span("action"))
                break

    return sorted(spans)


def _document_revocation_spans(clause: str) -> list[tuple[int, int]]:
    spans = set(
        _relation_action_spans(
        clause,
        (
            r"\b(?:пропуск|допуск)\w*[^.!?;\n]{0,160}?\b(?P<action>"
            r"(?:(?:может|вправе|должн\w*|обязан\w*)\s+быть\s+"
            r"(?:им\s+|ими\s+)?(?:аннулирован|отозван|отменен|отменён)\w*|"
            r"(?:аннулирован|отозван|отменен|отменён)\w*|"
            r"(?:аннулируется|отзывается|отменяется)\w*|"
            r"прекраща\w*\s+(?:сво\w*\s+)?действи\w*))\b",
            r"\b(?P<action>(?:аннулировани|отзыв|отмен|лишени)\w*)"
            r"[^.!?;\n]{0,96}\b(?:пропуск|допуск)\w*\b",
            r"\b(?P<action>(?:аннулирова(?:ть|л|ла|ли|ет|ют)|"
            r"аннулиру(?:ет|ют)|"
            r"отозва(?:ть|л|ла|ли)|отзыва(?:ет|ют)|"
            r"отмени(?:ть|л|ла|ли|т|ят)|отменя(?:ет|ют)))"
            r"[^.!?;\n]{0,96}\b(?:пропуск|допуск)\w*\b",
        ),
        )
    )
    for action in re.finditer(
        r"\b(?P<action>(?:аннулирова(?:ть|л|ла|ли)|"
        r"аннулиру(?:ет|ют)|"
        r"отозва(?:ть|л|ла|ли)|отзыва(?:ет|ют)|"
        r"отмени(?:ть|л|ла|ли|т|ят)|отменя(?:ет|ют)))\b",
        clause,
        re.IGNORECASE,
    ):
        projection = _predicate_relation(
            clause,
            action.start("action"),
            action.end("action"),
        )
        local_action_start = action.start("action") - projection.start
        local_action_end = action.end("action") - projection.start
        object_first_prefix = _relation_prefix_without_adjuncts(
            projection.text[:local_action_start]
        ).strip()
        object_first_suffix = projection.text[local_action_end:]
        if (
            re.fullmatch(
                r"(?:(?:эт|данн|соответствующ|нов)\w*\s+){0,3}"
                r"(?:пропуск|допуск)\w*",
                object_first_prefix,
                re.IGNORECASE,
            )
            is not None
            and (
                _relation_complete_postposed_actor_key(object_first_suffix)
                is not None
                or _RELATION_POSTPOSED_AGENCY_RE.match(
                    object_first_suffix
                )
                is not None
            )
        ):
            spans.add(action.span("action"))

    for action in re.finditer(
        r"\b(?P<action>(?:аннулируется|аннулируются|"
        r"отзывается|отзываются|отменяется|отменяются|"
        r"(?:аннулирован|отозван|отменен|отменён)(?:а|о|ы)?))\b",
        clause,
        re.IGNORECASE,
    ):
        projection = _predicate_relation(
            clause,
            action.start("action"),
            action.end("action"),
        )
        suffix = clause[
            action.end("action"):min(projection.end, action.end("action") + 96)
        ]
        if re.search(r"\b(?:пропуск|допуск)\w*\b", suffix, re.IGNORECASE):
            spans.add(action.span("action"))

    return sorted(spans)


_REGULATED_LEGAL_ACTION_PATTERNS: tuple[
    tuple[str, str, tuple[tuple[str, str], ...]],
    ...,
] = (
    (
        "issue",
        r"\b(?P<action>(?:выда|предостав|оформ|подпис|выпис)\w*)\b",
        (
            ("license", r"\bлицензи\w*\b"),
            ("warrant", r"\b(?:ордер|мандат)\w*\b"),
            ("authorization", r"\bразрешени\w*\b"),
            ("access_pass", r"\b(?:пропуск|допуск)\w*\b"),
        ),
    ),
    (
        "deport",
        r"\b(?P<action>(?:депортир|выдворя)\w*)\b",
        (
            ("person", r"\b(?:граждан|лиц|человек)\w*\b"),
        ),
    ),
    (
        "deprive",
        r"\b(?P<action>(?:лиша|лишить)\w*)\b",
        (
            ("citizenship", r"\bгражданств\w*\b"),
            ("license", r"\bлицензи\w*\b"),
            ("rights", r"\bправ\w*\b"),
        ),
    ),
)


def _regulated_action_is_context_only(
    projection: _PredicateRelation,
    action_start: int,
    action_end: int,
) -> bool:
    """Reject purpose/time mentions that do not assert the named action."""

    local_start = action_start - projection.start
    prefix = projection.text[max(0, local_start - 48):local_start]
    if (
        re.search(
            r"\b(?:для|до|перед|после|при|без|ради|"
            r"пут[её]м|посредством)\s+$|"
            r"\bв\s+целях\s+$",
            prefix,
            re.IGNORECASE,
        )
        is not None
    ):
        return True

    action_text = projection.text[
        action_start - projection.start:action_end - projection.start
    ]
    suffix = projection.text[
        action_end - projection.start:
        min(len(projection.text), action_end - projection.start + 120)
    ]
    return (
        re.search(
            r"(?:нн|ем|им)\w*(?:ый|ая|ое|ые|ого|ой|ому|ым|ых|ую|ыми)\b",
            action_text,
            re.IGNORECASE,
        )
        is not None
        and re.match(
            r"\s+(?:лицензи|ордер|мандат|разрешени|пропуск|допуск)\w*\b",
            suffix,
            re.IGNORECASE,
        )
        is not None
    )


def _regulated_action_objects(
    projection: _PredicateRelation,
    action_start: int,
    action_end: int,
    object_patterns: tuple[tuple[str, str], ...],
) -> tuple[str, ...]:
    """Return every direct regulated object governed by one predicate."""

    local_start = action_start - projection.start
    local_end = action_end - projection.start
    tail = projection.text[
        local_end:min(len(projection.text), local_end + 112)
    ]
    objects: list[str] = []
    for candidate_name, candidate_pattern in object_patterns:
        if re.search(candidate_pattern, tail, re.IGNORECASE):
            objects.append(candidate_name)
    if objects:
        return tuple(dict.fromkeys(objects))

    # Inverted statutory word order is common: ``Ордер ... выписывает X``.
    # The predicate projection already excludes coordinated relations; keep
    # the remaining backwards lookup bounded to the nearest object phrase.
    prefix = projection.text[max(0, local_start - 360):local_start]
    for candidate_name, candidate_pattern in object_patterns:
        matches = list(re.finditer(candidate_pattern, prefix, re.IGNORECASE))
        if not matches:
            continue
        gap = prefix[matches[-1].end():]
        if _INTERVENING_FINITE_PREDICATE_RE.search(gap) is None:
            objects.append(candidate_name)
    return tuple(dict.fromkeys(objects))


def _regulated_required_condition_object(
    value: str,
    *,
    action_start: int,
    object_patterns: tuple[tuple[str, str], ...],
) -> str:
    """Recover an object governed by an explicit required-conditions block."""

    line_start = value.rfind("\n", 0, action_start) + 1
    preceding = value[max(0, line_start - 700):line_start]
    condition_heading = re.search(
        r"\b(?:при\s+соблюдени\w*\s+)?"
        r"следующ\w*\s+услови\w*\s*:\s*$",
        preceding,
        re.IGNORECASE,
    )
    if condition_heading is None:
        return ""
    context = preceding[
        max(0, condition_heading.start() - 420):
    ]
    candidates: list[tuple[int, str]] = []
    for candidate_name, candidate_pattern in object_patterns:
        candidates.extend(
            (match.start(), candidate_name)
            for match in re.finditer(
                candidate_pattern,
                context,
                re.IGNORECASE,
            )
        )
    return max(candidates)[1] if candidates else ""


def _regulated_implicit_subject_object(
    value: str,
    *,
    projection: _PredicateRelation,
    action_start: int,
    action_end: int,
    object_patterns: tuple[tuple[str, str], ...],
) -> str:
    """Resolve a sentence-initial passive to the prior definition subject."""

    local_start = action_start - projection.start
    action_text = value[action_start:action_end]
    if (
        projection.text[:local_start].strip()
        or re.fullmatch(
            r"(?:выда|предостав|оформ)\w*(?:ется|ются)",
            action_text,
            re.IGNORECASE,
        )
        is None
    ):
        return ""

    boundaries = [
        span
        for span in _hard_clause_boundary_spans(
            value[:projection.start]
        )
        if span[0] < projection.start
    ]
    if not boundaries:
        return ""
    previous_end = boundaries[-1][0]
    previous_start = boundaries[-2][1] if len(boundaries) > 1 else 0
    previous = value[previous_start:previous_end].strip()
    if re.search(
        r"(?:[—–-]\s*(?:разрешени|документ)\w*|"
        r"\b(?:явля|представля)\w*)",
        previous,
        re.IGNORECASE,
    ) is None:
        return ""

    definition_head = re.split(r"\s+[—–-]\s+", previous, maxsplit=1)[0]
    for candidate_name, candidate_pattern in object_patterns:
        if re.search(candidate_pattern, definition_head, re.IGNORECASE):
            return candidate_name
    return ""


_RELATION_EXCLUSION_MARKER_FRAGMENT = (
    r"(?:"
    # A complete demonstrative discourse connector (``кроме того,`` /
    # ``кроме этого,``) starts a fresh clause.  A governed noun phrase such
    # as ``кроме того случая`` or ``кроме этого нарушения`` is still a real
    # exclusion and must retain its negative payload.
    r"кроме(?!\s+(?:того|этого)\s*(?:"
    r"[,;:.!?]|$|"
    r"(?=(?:суд|судь|полици|прокуратур|прокурор|губернатор|"
    r"правительств|парламент|министр|мэр|организаци|компани|"
    r"гражданин|лиц|работник|сотрудник|агент|"
    r"fib|usss|sang|lspd|lssd|lscsd|[A-Z]{2,12})\w*\b)"
    r"))|"
    r"за\s+(?:исключени\w*|вычетом|минусом)|"
    r"исключая|"
    r"не\s+(?:включая|считая)|"
    r"без\s+уч[её]та|"
    r"но\s+не"
    r")"
)
_RELATION_ROSTER_EXCLUSION_RE = re.compile(
    r"\b" + _RELATION_EXCLUSION_MARKER_FRAGMENT + r"\b",
    re.IGNORECASE,
)
_RELATION_GROUND_EXCLUSION_RE = re.compile(
    r"\b" + _RELATION_EXCLUSION_MARKER_FRAGMENT + r"\b",
    re.IGNORECASE,
)
_RELATION_GROUND_EXCLUSION_GOVERNED_PREFIX_CHAR_LIMIT = 720


def _relation_exclusion_marker_is_discourse(
    value: str,
    *,
    marker_start: int,
    marker_end: int,
) -> bool:
    """Return whether ``кроме того/этого`` opens a fresh discourse clause.

    A demonstrative followed by a real top-level separator is the connective
    ``besides`` rather than a subtractive legal-ground marker.  One balanced,
    bounded parenthetical aside may sit before that separator.  Governed noun
    phrases (``кроме того случая`` and ``кроме того (единственного) случая``)
    deliberately remain exclusions, while malformed wrappers remain
    fail-closed.
    """

    marker = value[marker_start:marker_end].casefold().replace("ё", "е")
    if marker != "кроме":
        return False
    demonstrative = re.match(
        r"\s+(?:того|этого)\b",
        value[marker_end:],
        re.IGNORECASE,
    )
    if demonstrative is None:
        return False
    cursor = marker_end + demonstrative.end()
    while cursor < len(value) and value[cursor].isspace():
        cursor += 1

    if cursor < len(value) and value[cursor] in "([":
        scan = _relation_delimited_scan(value)
        wrapper = next(
            (
                (start, end)
                for start, end in scan.spans
                if start == cursor
                and value[start:start + 1] in {"(", "["}
                and end - start <= 240
            ),
            None,
        )
        if wrapper is None:
            return False
        cursor = wrapper[1]
        while cursor < len(value) and value[cursor].isspace():
            cursor += 1

    return cursor >= len(value) or value[cursor] in ",;:.!?—–-"


def _relation_exclusion_matches(
    pattern: re.Pattern[str],
    syntax: str,
    *,
    semantic: str | None = None,
    start: int = 0,
    end: int | None = None,
) -> tuple[re.Match[str], ...]:
    """Return shared exclusion matches with discourse connectors removed."""

    source = syntax if semantic is None else semantic
    stop = len(syntax) if end is None else end
    return tuple(
        match
        for match in pattern.finditer(syntax, start, stop)
        if not _relation_exclusion_marker_is_discourse(
            source,
            marker_start=match.start(),
            marker_end=match.end(),
        )
    )


_RELATION_EXCLUSION_CONDITION_CASE_SCOPE_RE = re.compile(
    r"^\s*"
    r"(?:(?:[a-zа-яё-]+)\s+){0,8}случа\w*"
    r"(?:\s*,\s*[a-zа-яё-]+(?:\s+[a-zа-яё-]+){0,9})?"
    r"\s*,?\s*$",
    re.IGNORECASE,
)
_RELATION_EXCLUSION_CONDITION_CASE_SCOPE_CHAR_LIMIT = 360


def _relation_exclusion_governs_condition_case(
    value: str,
    *,
    condition_start: int,
) -> bool:
    """Return whether a bounded ``except ... cases when`` owns a condition.

    The exclusion marker is parsed by the same shared marker/discourse
    scanner as legal-ground and actor-roster exclusions.  This small grammar
    only establishes the syntactic link to a following condition: modifiers
    may appear before ``случай`` or in one comma-delimited postmodifier, but
    a different clause/list item cannot be swallowed into the exclusion.
    """

    syntax = _relation_quote_syntax_surface(value)
    hard_start = max(
        (
            boundary.end()
            for boundary in re.finditer(
                r"[;.!?\r\n]",
                syntax[:condition_start],
            )
        ),
        default=0,
    )
    scan_start = max(
        hard_start,
        condition_start
        - _RELATION_EXCLUSION_CONDITION_CASE_SCOPE_CHAR_LIMIT,
    )
    markers = _relation_exclusion_matches(
        _RELATION_GROUND_EXCLUSION_RE,
        syntax,
        semantic=value,
        start=scan_start,
        end=condition_start,
    )
    for marker in reversed(markers):
        governed = value[marker.end():condition_start]
        if _RELATION_EXCLUSION_CONDITION_CASE_SCOPE_RE.fullmatch(governed):
            return True
    return False


_RELATION_LEADING_GROUND_CONDITION_RE = re.compile(
    r"^\s*(?:если|только\s+если|в\s+случа\w*|при)\b",
    re.IGNORECASE,
)
_RELATION_LEGAL_GROUND_SIGNAL_RE = re.compile(
    r"\b(?:наруш|правонаруш|несоблюд|краж|убийств|мошенничеств|"
    r"преступлен|правил|требован|услови|основани|закон|норм)\w*\b",
    re.IGNORECASE,
)


def _relation_prefix_starts_operative_ground_condition(value: str) -> bool:
    """Recognize a complete condition that follows a leading exclusion."""

    if _RELATION_LEADING_GROUND_CONDITION_RE.match(value) is None:
        return False
    if _RELATION_LEGAL_GROUND_SIGNAL_RE.search(value) is None:
        return False
    return bool(
        _relation_object_candidates(value)
        or _EXPLICIT_RELATION_SUBJECT_RE.search(value) is not None
    )


@dataclass(frozen=True)
class _RelationGroundExclusionSpan:
    marker_start: int
    marker_end: int
    payload_start: int
    payload_end: int
    value: str


def _relation_ground_exclusion_payload_end(
    value: str,
    syntax: str,
    *,
    marker_end: int,
    action_start: int,
    action_end: int,
    hard_end: int,
) -> int:
    """Return the complete exclusion tail without swallowing a new clause."""

    if marker_end < action_start:
        # A leading condition normally ends at the last top-level comma before
        # its governed patient/actor.  Only the bounded tail can be that
        # patient/actor phrase: scanning every earlier list comma and reparsing
        # a progressively longer suffix made an action-first exclusion
        # quadratic.  An over-window/malformed prefix remains fail-closed by
        # staying inside the exclusion payload.
        leading_surface = value[marker_end:action_start]
        leading_scan = _relation_delimited_scan(leading_surface)
        if not leading_scan.malformed:
            for comma in re.finditer(r",", leading_scan.masked):
                exclusion_payload = leading_surface[:comma.start()]
                following_condition = leading_surface[comma.end():]
                if (
                    _RELATION_LEGAL_GROUND_SIGNAL_RE.search(
                        exclusion_payload
                    )
                    is not None
                    and _relation_prefix_starts_operative_ground_condition(
                        following_condition
                    )
                ):
                    return marker_end + comma.start()

        candidate_start = max(
            marker_end,
            action_start
            - _RELATION_GROUND_EXCLUSION_GOVERNED_PREFIX_CHAR_LIMIT
            - 1,
        )
        comma_matches = tuple(
            re.compile(r",").finditer(
                syntax,
                candidate_start,
                action_start,
            )
        )
        for comma in reversed(comma_matches):
            governed_prefix = value[comma.end():action_start].strip()
            if not governed_prefix:
                continue
            patient = _relation_prefix_is_known_patient(
                _relation_prefix_without_adjuncts(governed_prefix)
            )
            subject = (
                _EXPLICIT_RELATION_SUBJECT_RE.search(governed_prefix)
                is not None
            )
            if patient or subject:
                return comma.start()
        return action_start

    # A post-action exclusion may itself contain a comma-separated list.
    # Scan action positions once and advance a shared cursor with the commas.
    # Re-slicing/searching the whole remaining suffix for every comma made a
    # long legal list quadratic even though every boundary is local.
    actions = tuple(
        _RELATION_ACTION_RE.finditer(syntax, marker_end, hard_end)
    )
    action_index = 0
    for comma in re.compile(r",").finditer(syntax, marker_end, hard_end):
        while (
            action_index < len(actions)
            and actions[action_index].start("action") < comma.end()
        ):
            action_index += 1
        if action_index >= len(actions):
            continue
        next_action = actions[action_index]
        leading = value[
            comma.end():next_action.start("action")
        ]
        if (
            _EXPLICIT_RELATION_SUBJECT_RE.search(leading) is not None
            or _relation_prefix_is_known_patient(
                _relation_prefix_without_adjuncts(leading)
            )
        ):
            return comma.start()
    return hard_end


def _relation_ground_exclusion_has_context(
    value: str,
    syntax: str,
    *,
    marker_start: int,
    marker_end: int,
    action_start: int,
    action_end: int,
    hard_start: int,
) -> bool:
    """Distinguish a legal-ground exclusion from rosters and fresh clauses."""

    marker = syntax[marker_start:marker_end]
    if re.match(r"но\s+не", marker, re.IGNORECASE):
        following = (
            syntax[marker_end:action_start]
            if marker_end < action_start
            else syntax[marker_end:]
        ).lstrip()
        immediate_modal = _RELATION_MODAL_TOKEN_RE.match(following)
        immediate_action = _RELATION_ACTION_RE.match(following)
        if immediate_modal is not None or (
            immediate_action is not None
            and _relation_event(immediate_action.group("action"))
            != "nominal"
        ):
            # `но не обязан/закрывает` is a negative relation, not a member
            # removed from a legal-ground set.
            return False

    before = syntax[hard_start:marker_start]
    if marker_start < action_start:
        # Only the first governed action after a leading exclusion owns it.
        if _RELATION_ACTION_RE.search(syntax, marker_end, action_start):
            return False
        condition_intro = re.search(
            r"\b(?:если|только\s+если|в\s+случа\w*|при|за)\b",
            before,
            re.IGNORECASE,
        )
        condition_ground = re.search(
            r"\b(?:соверш|выяв|установ|доказ|зафиксир|наруш|"
            r"несоблюд|краж|убийств|мошенничеств|правил|требован|"
            r"услови|основани|закон|норм)\w*\b",
            before,
            re.IGNORECASE,
        )
        if condition_intro is not None and condition_ground is not None:
            return True

        # A subtractive marker may itself open the leading condition:
        # ``За вычетом убийства, лицензия изымается ...``.  Require a
        # top-level comma before the governed action and a typed legal-ground
        # payload.  Institutional rosters such as ``Кроме LSPD, полиция ...``
        # therefore remain owned by the actor-roster parser.
        marker_surface = syntax[marker_start:marker_end]
        if re.match(
            r"(?:за\s+(?:исключени\w*|вычетом|минусом)|"
            r"исключая|не\s+(?:включая|считая)|без\s+уч[её]та|кроме)",
            marker_surface,
            re.IGNORECASE,
        ) is None:
            return False
        separating_comma = syntax.find(",", marker_end, action_start)
        if separating_comma < 0:
            return False
        payload = value[marker_end:separating_comma]
        return bool(_operative_ground_qualifiers(payload))

    post_action = syntax[action_end:marker_start]
    if re.search(
        r"\b(?:за|при|в\s+случа\w*)\b|"
        r"\b(?:основани|услови|наруш|правонаруш|несоблюд)\w*\b",
        post_action,
        re.IGNORECASE,
    ) is not None:
        return True
    leading_condition = syntax[hard_start:action_start]
    return (
        re.search(
            r"\b(?:если|только\s+если|в\s+случа\w*|при)\b",
            leading_condition,
            re.IGNORECASE,
        )
        is not None
        and re.search(
            r"\b(?:соверш|выяв|установ|доказ|зафиксир|наруш|"
            r"несоблюд|краж|убийств|мошенничеств|правил|требован|"
            r"услови|основани|закон|норм)\w*\b",
            leading_condition,
            re.IGNORECASE,
        )
        is not None
    )


@lru_cache(maxsize=4096)
def _relation_ground_exclusion_spans(
    value: str,
    action_start: int,
    action_end: int,
) -> tuple[_RelationGroundExclusionSpan, ...]:
    """Parse complete, relation-local negative ground expressions once."""

    syntax = _relation_quote_syntax_surface(value)
    hard_start, hard_end = _hard_clause_bounds(
        syntax,
        action_start,
        action_end,
    )
    source_scan = _relation_delimited_scan(value)
    spans: list[_RelationGroundExclusionSpan] = []
    for marker in _relation_exclusion_matches(
        _RELATION_GROUND_EXCLUSION_RE,
        syntax,
        semantic=value,
        start=hard_start,
        end=hard_end,
    ):
        if not _relation_ground_exclusion_has_context(
            value,
            syntax,
            marker_start=marker.start(),
            marker_end=marker.end(),
            action_start=action_start,
            action_end=action_end,
            hard_start=hard_start,
        ):
            continue
        payload_end = _relation_ground_exclusion_payload_end(
            value,
            syntax,
            marker_end=marker.end(),
            action_start=action_start,
            action_end=action_end,
            hard_end=hard_end,
        )
        raw_payload = value[marker.end():payload_end].strip(
            " \t,;:—–-*•."
        )
        raw_payload_scan = _relation_delimited_scan(raw_payload)
        payload = raw_payload.strip(" \t,;:()[]{}—–-*•.")
        payload = re.sub(
            r"^не\s+|^случа\w*\s+",
            "",
            payload,
            count=1,
            flags=re.IGNORECASE,
        ).strip()
        if not payload:
            # An empty/malformed exclusion remains collision-safe and cannot
            # silently compare equal to no exclusion at all.
            canonical = "__ground_exclusion_unresolved__:" + hashlib.sha256(
                value[marker.start():payload_end].encode("utf-8")
            ).hexdigest()
        else:
            payload_scan = _relation_delimited_scan(payload)
            canonical = _canonical_relation_ground_exclusion(payload)
            if (
                raw_payload_scan.malformed
                and source_scan.malformed
                or payload_scan.malformed
                or not canonical
            ):
                canonical = (
                    "__ground_exclusion_unresolved__:"
                    + hashlib.sha256(raw_payload.encode("utf-8")).hexdigest()
                )
        spans.append(
            _RelationGroundExclusionSpan(
                marker_start=marker.start(),
                marker_end=marker.end(),
                payload_start=marker.end(),
                payload_end=payload_end,
                value=canonical,
            )
        )
    return tuple(dict.fromkeys(spans))


def _relation_roster_authorities(value: str) -> set[str]:
    return {
        authority
        for authority, pattern in _AUTHORITY_RELATIVE_PATTERNS
        if re.search(pattern, value, re.IGNORECASE) is not None
    }


def _relation_roster_exclusion_parts(
    syntax_value: str,
    semantic_value: str | None = None,
) -> tuple[str, str, set[str], int | None]:
    """Split one roster entry into included/excluded source-owned surfaces."""

    semantic = semantic_value if semantic_value is not None else syntax_value
    if len(semantic) != len(syntax_value):
        raise ValueError("roster entry surfaces must preserve offsets")
    scan = _relation_delimited_scan(syntax_value)
    markers = _relation_exclusion_matches(
        _RELATION_ROSTER_EXCLUSION_RE,
        scan.masked,
        semantic=syntax_value,
    )
    marker = markers[0] if markers else None
    if marker is None:
        # Parenthetical exclusions are ordinary roster grammar, while quoted
        # payload remains an opaque proper name.  The general delimiter scan
        # masks both, so reopen only balanced parentheses/brackets here.
        for start, end in scan.spans:
            surface = syntax_value[start:end]
            if not surface.startswith(("(", "[")):
                continue
            nested_markers = _relation_exclusion_matches(
                _RELATION_ROSTER_EXCLUSION_RE,
                surface,
            )
            if nested_markers:
                nested = nested_markers[0]
                marker = _RELATION_ROSTER_EXCLUSION_RE.search(
                    syntax_value,
                    start + nested.start(),
                    start + nested.end(),
                )
                break
    if marker is None:
        return semantic, "", _relation_roster_authorities(syntax_value), None
    positive = semantic[:marker.start()].strip(" \t,;:()[]—–-*•")
    excluded = semantic[marker.end():].strip(" \t,;:()[]—–-*•.")
    positive_authorities = _relation_roster_authorities(
        syntax_value[:marker.start()]
    )
    excluded_authorities = _relation_roster_authorities(
        syntax_value[marker.end():]
    )
    return (
        positive,
        excluded,
        positive_authorities - excluded_authorities,
        marker.start(),
    )


def _relation_roster_surface_authorities(value: str) -> frozenset[str]:
    """Return broad authority families owned by one roster surface."""

    authorities = set(_relation_roster_authorities(value))
    actor = _relation_actor_key(value)
    if actor:
        authority = _qualitative_authority_for_relation_actor(actor)
        if authority:
            authorities.add(authority)
    # Acronym-only local police identities are deliberately more exact than
    # ``_AUTHORITY_RELATIVE_PATTERNS``.  They still belong to the police
    # family when deciding whether ``Полиция, кроме LSPD`` widens the set.
    if re.search(r"\b(?:lspd|lssd)\b", value, re.IGNORECASE):
        authorities.add("police")
    return frozenset(authorities)


_RELATION_EXCLUSION_LIST_HEAD_RE = re.compile(
    r"^\s*(?P<head>"
    r"(?:отдел|отделени|департамент|управлени|подразделени|филиал|"
    r"коллеги|комисси|служб|агентств|организаци|учреждени|"
    r"суд|прокуратур|полици|бюро|fib|usss|sang|lspd|lssd|lscsd)\w*"
    r")\b",
    re.IGNORECASE,
)


def _relation_exclusion_list_head(value: str) -> str:
    match = _RELATION_EXCLUSION_LIST_HEAD_RE.match(value)
    if match is None:
        return ""
    return _canonical_argument_token(match.group("head"))


def _relation_top_level_exclusion_items(value: str) -> tuple[str, ...]:
    """Split an exclusion list without cutting a quoted or grouped name."""

    stripped = value.strip(" \t,;:()[]{}—–-*•.")
    if not stripped:
        return ()
    scan = _relation_delimited_scan(stripped)
    if scan.malformed:
        # Preserve one opaque full item.  A malformed tail must never degrade
        # to a shorter, apparently understood exclusion.
        return (stripped,)

    pieces: list[str] = []
    start = 0
    for delimiter in re.finditer(r"[,;\r\n]+", scan.masked):
        piece = stripped[start:delimiter.start()].strip()
        if piece:
            pieces.append(piece)
        start = delimiter.end()
    final = stripped[start:].strip()
    if final:
        pieces.append(final)
    if not pieces:
        return (stripped,)

    items: list[str] = []
    for piece in pieces:
        piece_scan = _relation_delimited_scan(piece)
        connectors = tuple(
            re.finditer(
                r"\b(?:и|или|либо)\b|/|(?<!\w)[&+](?!\w)",
                piece_scan.masked,
                re.I,
            )
        )
        if not connectors:
            items.append(piece)
            continue
        candidates: list[str] = []
        candidate_start = 0
        for connector in connectors:
            candidate = piece[candidate_start:connector.start()].strip()
            if candidate:
                candidates.append(candidate)
            candidate_start = connector.end()
        candidate = piece[candidate_start:].strip()
        if candidate:
            candidates.append(candidate)
        heads = tuple(_relation_exclusion_list_head(item) for item in candidates)
        recognized = tuple(
            bool(_relation_roster_surface_authorities(item))
            for item in candidates
        )
        has_symbolic_connector = any(
            connector.group(0).strip() in {"/", "&", "+"}
            for connector in connectors
        )
        repeated_open_head = bool(
            heads
            and all(heads)
            and len(set(heads)) == 1
        )
        all_list_like = all(
            known or bool(head)
            for known, head in zip(recognized, heads, strict=True)
        )
        if len(candidates) >= 2 and (
            all(recognized)
            or repeated_open_head
            or (has_symbolic_connector and all_list_like)
        ):
            # A connector is list syntax only when every member is a fully
            # recognized authority family.  Thus ``LSSD и LSCSD`` is a set,
            # while an open-vocabulary name such as ``Рога и Копыта`` stays atomic.
            items.extend(candidates)
        else:
            items.append(piece)
    return tuple(items)


def _relation_leading_roster_exclusion_parts(
    value: str,
    marker: re.Match[str],
    *,
    boundary_end: int,
) -> tuple[str, str, int] | None:
    """Split ``Кроме excluded, actor ...`` without hiding the actor."""

    if marker.start() >= boundary_end:
        return None
    hard_start, _hard_end = _hard_clause_bounds(
        value,
        marker.start(),
        marker.end(),
    )
    if value[hard_start:marker.start()].strip(
        " \t,;:()[]{}—–-*•."
    ):
        # ``Полиция, кроме A, B и C`` already has its positive roster before
        # the marker.  A later excluded member must never be reinterpreted as
        # the positive actor merely because it is followed by another comma.
        return None
    tail = value[marker.end():boundary_end]
    scan = _relation_delimited_scan(tail)
    if scan.malformed:
        return None
    for comma in re.finditer(r",", scan.masked):
        excluded = tail[:comma.start()].strip(" \t,;:()[]{}—–-*•.")
        positive = tail[comma.end():]
        positive_scan = _relation_delimited_scan(positive)
        modal = _RELATION_MODAL_TOKEN_RE.search(positive_scan.masked)
        if modal is not None:
            positive = positive[:modal.start()]
        positive = positive.strip(" \t,;:()[]{}—–-*•.")
        if not positive or not excluded:
            continue

        cleaned_positive = _relation_prefix_without_adjuncts(
            positive
        ).strip()
        actor_group = _relation_complete_actor_group(cleaned_positive)
        actor = (
            actor_group.key
            if actor_group is not None
            else _relation_complete_postposed_actor_key(cleaned_positive)
        )
        if (
            not actor
            or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX)
        ):
            continue
        excluded_items = _relation_top_level_exclusion_items(excluded)
        if not excluded_items or not all(
            _relation_roster_surface_authorities(item)
            for item in excluded_items
        ):
            continue
        return positive, excluded, marker.end() + comma.end()
    return None


def _relation_mask_actor_exclusions(
    value: str,
    *,
    action_start: int,
    action_end: int,
) -> str:
    """Hide excluded roster members from operative-actor parsing only."""

    scan = _relation_delimited_scan(value)
    masked = list(value)
    ground_exclusions = {
        exclusion.marker_start: exclusion
        for exclusion in _relation_ground_exclusion_spans(
            value,
            action_start,
            action_end,
        )
    }
    for marker in _relation_exclusion_matches(
        _RELATION_ROSTER_EXCLUSION_RE,
        scan.masked,
        semantic=value,
    ):
        ground_exclusion = ground_exclusions.get(marker.start())
        if ground_exclusion is not None:
            end = ground_exclusion.payload_end
        elif marker.start() < action_start:
            leading_roster = _relation_leading_roster_exclusion_parts(
                value,
                marker,
                boundary_end=action_start,
            )
            if leading_roster is not None:
                _positive, _excluded, end = leading_roster
            else:
                modal = _RELATION_MODAL_TOKEN_RE.search(
                    scan.masked,
                    marker.end(),
                    action_start,
                )
                end = modal.start() if modal is not None else action_start
        elif marker.start() >= action_end:
            boundary = re.search(r"[;.!?\r\n]", scan.masked[marker.end():])
            end = (
                marker.end() + boundary.start()
                if boundary is not None
                else len(value)
            )
        else:
            end = action_end
        if end > marker.start():
            masked[marker.start():end] = " " * (end - marker.start())
    return "".join(masked)


def _relation_mask_exclusions_for_predicate_scanning(value: str) -> str:
    """Hide exclusion payloads while retaining their governed predicate."""

    scan = _relation_delimited_scan(value)
    masked = list(value)
    ground_exclusions: dict[int, _RelationGroundExclusionSpan] = {}
    for action in _RELATION_ACTION_RE.finditer(scan.masked):
        for exclusion in _relation_ground_exclusion_spans(
            value,
            action.start("action"),
            action.end("action"),
        ):
            previous = ground_exclusions.get(exclusion.marker_start)
            if (
                previous is None
                or exclusion.payload_end < previous.payload_end
            ):
                ground_exclusions[exclusion.marker_start] = exclusion

    for marker in _relation_exclusion_matches(
        _RELATION_ROSTER_EXCLUSION_RE,
        scan.masked,
        semantic=value,
    ):
        ground_exclusion = ground_exclusions.get(marker.start())
        if ground_exclusion is not None:
            end = ground_exclusion.payload_end
            if end > marker.start():
                masked[marker.start():end] = " " * (end - marker.start())
            continue
        boundary = re.search(
            r"[.!?\r\n]",
            scan.masked[marker.end():],
        )
        hard_end = (
            marker.end() + boundary.start()
            if boundary is not None
            else len(value)
        )
        candidates = [
            (match.start(), pattern is _RELATION_MODAL_TOKEN_RE)
            for pattern in (_RELATION_MODAL_TOKEN_RE, _RELATION_ACTION_RE)
            for match in pattern.finditer(scan.masked, marker.end(), hard_end)
        ]
        if candidates:
            end, next_is_modal = min(candidates, key=lambda item: item[0])
            leading_roster = _relation_leading_roster_exclusion_parts(
                value,
                marker,
                boundary_end=end,
            )
            if leading_roster is not None:
                _positive, _excluded, end = leading_roster
            if (
                marker.group(0).casefold().replace("ё", "е")
                .startswith("но")
                and next_is_modal
                and not scan.masked[marker.end():end].strip()
            ):
                # This is a fresh negative normative clause (``но не обязан``),
                # not an excluded roster/ground member.  Preserve ``не`` so
                # the following modal keeps its real polarity.
                continue
        else:
            hard_start, _ = _hard_clause_bounds(
                scan.masked,
                marker.start(),
                marker.end(),
            )
            preceding = scan.masked[hard_start:marker.start()]
            if (
                _RELATION_ACTION_RE.search(preceding) is None
                and _RELATION_MODAL_TOKEN_RE.search(preceding) is None
            ):
                # A roster block may end with ``Полиция, кроме LSPD`` and own
                # its action in the heading above.  Leave that marker visible
                # to the dedicated block parser.  A post-action exclusion is
                # still hidden from predicate scanning below.
                continue
            end = hard_end
        if end > marker.start():
            masked[marker.start():end] = " " * (end - marker.start())
    return "".join(masked)


def _relation_roster_required_exclusion_arguments(
    positive: str,
    excluded: str,
) -> frozenset[_RelationArgument]:
    """Preserve an exclusion that narrows the included authority family.

    A disjoint exclusion is safely irrelevant to a more specific output:
    ``Правоохранители, кроме прокуратуры`` still proves ``Полиция``.  But an
    exclusion inside the included family (``Полиция, кроме LSPD``) is a real
    semantic restriction and a generated generic claim may not erase it.
    """

    if not positive or not excluded:
        return frozenset()
    positive_families = _relation_roster_surface_authorities(positive)
    arguments: set[_RelationArgument] = set()
    for item in _relation_top_level_exclusion_items(excluded):
        item_scan = _relation_delimited_scan(item)
        has_unknown_residual = (
            item_scan.malformed
            or re.search(
                r"\b(?:и|или|либо)\b|[/&+]",
                item_scan.masked,
                re.IGNORECASE,
            )
            is not None
        )
        excluded_families = _relation_roster_surface_authorities(item)
        shared_families = positive_families & excluded_families
        if not shared_families:
            if (
                positive_families
                and excluded_families
                and not has_unknown_residual
            ):
                # Both sides are understood and provably disjoint, e.g.
                # ``Правоохранители, кроме прокуратуры`` still proves Police.
                continue
            # An unknown grammatical subclass (department, branch, panel,
            # quoted name, future server-specific unit) may belong to the
            # included family.  Preserve the complete item opaquely.
            shared_families = positive_families or frozenset({"unknown"})

        canonical = unicodedata.normalize("NFKC", item).casefold()
        canonical = canonical.replace("ё", "е")
        canonical = re.sub(r"\s+", " ", canonical).strip()
        canonical = canonical.strip(" \t,;:()[]{}—–-*•.")
        digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        excluded_actor = _relation_actor_key(item)
        qualifiers = {f"family:{family}" for family in shared_families}
        if excluded_actor:
            qualifiers.add(f"actor:{excluded_actor}")
        arguments.add(
            _RelationArgument(
                role="roster_exclusion",
                value=f"sha256:{digest}",
                marker="except",
                qualifiers=frozenset(qualifiers),
            )
        )
    return frozenset(arguments)


def _regulated_block_roster_entries(
    value: str,
    *,
    action_start: int,
    action_end: int,
    semantic_value: str | None = None,
) -> tuple[tuple[str, str, frozenset[_RelationArgument]], ...]:
    """Read a two-line ``уполномоченные ... следующие лица`` roster."""

    semantic = semantic_value if semantic_value is not None else value
    if len(semantic) != len(value):
        raise ValueError("regulated roster surfaces must preserve offsets")
    line_start = value.rfind("\n", 0, action_start) + 1
    line_end = value.find("\n", action_end)
    if line_end < 0:
        line_end = len(value)
    heading = value[line_start:line_end]
    local_action_start = action_start - line_start
    if re.search(
        r"\bлиц\w*\s*,?\s*уполномоченн\w*\s*$",
        heading[:local_action_start],
        re.IGNORECASE,
    ) is None:
        return ()

    tail_start = line_end + 1
    tail = value[tail_start:]
    lines = tail.splitlines(keepends=True)
    list_start = None
    for index, raw_line in enumerate(lines[:4]):
        stripped = raw_line.strip()
        if not stripped:
            continue
        if re.search(
            r"\b(?:име\w*|явля\w*)\s+следующ\w*"
            r"[^:\n]{0,80}\bлиц\w*\s*:\s*$",
            stripped,
            re.IGNORECASE,
        ):
            list_start = index + 1
        break
    if list_start is None:
        return ()

    entries: list[tuple[str, str, frozenset[_RelationArgument]]] = []
    line_offset = sum(len(line) for line in lines[:list_start])
    for raw_line in lines[list_start:]:
        syntax_line = raw_line.rstrip("\r\n")
        semantic_line = semantic[
            tail_start + line_offset:
            tail_start + line_offset + len(syntax_line)
        ]
        line_offset += len(raw_line)
        left_trimmed = syntax_line.lstrip(" \t—–-*•")
        content_start = len(syntax_line) - len(left_trimmed)
        stripped = left_trimmed.rstrip(" \t—–-*•")
        if not stripped:
            continue
        if re.fullmatch(r"\d+(?:\.\d+)*\.?", stripped):
            break
        if re.match(
            r"^\d+(?:\.\d+)+\.?\s+",
            stripped,
        ):
            break
        _positive, _excluded, allowed_authorities, exclusion_start = (
            _relation_roster_exclusion_parts(
                stripped,
                semantic_line[
                    content_start:content_start + len(stripped)
                ],
            )
        )
        exclusion_arguments = _relation_roster_required_exclusion_arguments(
            _positive,
            _excluded,
        )
        matched = False
        for authority, pattern in _AUTHORITY_RELATIVE_PATTERNS:
            if authority not in allowed_authorities:
                continue
            actor_match = re.search(pattern, stripped, re.IGNORECASE)
            if actor_match is None:
                continue
            if (
                exclusion_start is not None
                and actor_match.start() >= exclusion_start
            ):
                continue
            semantic_start = content_start + actor_match.start()
            semantic_end = content_start + actor_match.end()
            actor = _relation_actor_key(
                semantic_line[semantic_start:semantic_end]
            )
            if actor:
                entries.append((authority, actor, exclusion_arguments))
                if authority == "other:management":
                    for alias in re.finditer(
                        r"\((?P<alias>[A-Z]{2,12})\)",
                        semantic_line,
                    ):
                        alias_prefix = semantic_line[
                            semantic_end:alias.start()
                        ]
                        if (
                            re.search(r"[,;]", alias_prefix) is not None
                            or re.search(
                                r"\b(?:кроме|исключая|без|"
                                r"за\s+исключени\w*)\b",
                                alias_prefix,
                                re.IGNORECASE,
                            )
                            is not None
                        ):
                            continue
                        entries.append(
                            (
                                authority,
                                _relation_actor_key(
                                    actor
                                    + " "
                                    + alias.group("alias")
                                ),
                                exclusion_arguments,
                            )
                        )
            matched = True
        if not matched:
            exact_actor = (
                _relation_complete_postposed_actor_key(stripped)
                if exclusion_start is None
                else None
            )
            if (
                exact_actor
                and not exact_actor.startswith(
                    _RELATION_UNRESOLVED_ACTOR_PREFIX
                )
                and (
                    exact_authority :=
                    _qualitative_authority_for_relation_actor(exact_actor)
                )
            ):
                entries.append(
                    (exact_authority, exact_actor, exclusion_arguments)
                )
                matched = True
        if (
            not matched
            and re.search(r":\s*$", stripped)
            and entries
        ):
            break
    return tuple(dict.fromkeys(entries))


def _regulated_authority_list_claims(
    value: str,
    *,
    action_name: str,
    action: re.Match[str],
    object_name: str,
) -> set[_QualitativeClaim]:
    """Project actors from an explicit ``список уполномоченных:`` block."""

    claims = {
        _QualitativeClaim(
            action="regulated_legal_action",
            object=f"{action_name}:{object_name}",
            modality="definite",
            authority=authority,
        )
        for authority, _, _ in _regulated_block_roster_entries(
            value,
            action_start=action.start("action"),
            action_end=action.end("action"),
        )
        if authority
    }
    line_start = value.rfind("\n", 0, action.start("action")) + 1
    line_end = value.find("\n", action.end("action"))
    if line_end < 0:
        line_end = len(value)
    heading = value[line_start:line_end]
    local_action_start = action.start("action") - line_start
    local_action_end = action.end("action") - line_start
    heading_prefix = heading[:local_action_start]
    heading_suffix = heading[local_action_end:]
    if (
        re.search(
            r"\b(?:список|перечень)\s+лиц\b"
            r"[^:\n]{0,120}\bуполномоченн\w*\s*$",
            heading_prefix,
            re.IGNORECASE,
        )
        is None
        or ":" not in heading_suffix
    ):
        return claims

    list_lines: list[str] = []
    standalone_marker = False
    for raw_line in value[line_end + 1:].splitlines():
        stripped = raw_line.strip()
        if not stripped or _BLOCK_BOUNDARY_RE.match(stripped):
            break
        if re.fullmatch(r"[-*•—–]", stripped):
            standalone_marker = True
            continue
        if re.match(
            r"^(?:[-*•—–]\s+|\d+(?:[.,]\d+)*\.?\s+)",
            stripped,
        ):
            list_lines.append(stripped)
            standalone_marker = False
            continue
        if standalone_marker:
            list_lines.append(stripped)
            standalone_marker = False
            continue
        break

    actors = set()
    for line in list_lines:
        _positive, _excluded, allowed, _marker = (
            _relation_roster_exclusion_parts(line)
        )
        actors.update(allowed)
    claims.update({
        _QualitativeClaim(
            action="regulated_legal_action",
            object=f"{action_name}:{object_name}",
            # A roster states an extant legal capacity.  Finite present-tense
            # search phrasing (``губернатор выдаёт ордер``) is therefore a
            # faithful generic paraphrase, unlike an explicit source ``может``.
            modality="definite",
            authority=authority,
        )
        for authority in actors
    })
    return claims


def _qualitative_authority_for_relation_actor(actor: str) -> str:
    folded = actor.casefold().replace("ё", "е")
    tokens = folded.split()
    if "министр" in folded and "юстиц" in folded:
        return "justice_minister"
    if (
        actor == "licensing_authority"
        or "лицензирующ" in folded
        or (
            "уполномоченн" in folded
            and any(token.startswith("лиц") for token in tokens)
        )
    ):
        return "licensing_authority"
    # Identity complements may themselves contain another institutional noun:
    # ``директор отдела ... при губернаторе`` or ``организация Центр при
    # суде``.  The first institutional family head owns the phrase; a later
    # noun is part of its identity, not a second operative authority.
    for token in tokens:
        if token.startswith("суд"):
            return "court"
        if token.startswith(("прокуратур", "прокурор")):
            return "prosecutor"
        if (
            token.startswith(("полиц", "правоохранител", "шериф"))
            or token in {"lspd", "lssd"}
        ):
            return "police"
        if token.startswith(("губернатор", "вице-губернатор")):
            return "governor"
        if token.startswith(("руководител", "директор", "начальник")):
            return "other:management"
        if token.startswith("организац"):
            return "other:organization"
    if (
        "los santos police department" in folded
        or "los santos county sheriff" in folded
    ):
        return "police"
    return ""


def _relation_actor_has_post_head_identity(actor: str) -> bool:
    """Return whether a known authority head owns trailing identity tokens."""

    tokens = actor.split()
    for index, token in enumerate(tokens[:-1]):
        tail = tokens[index + 1:]
        if token.startswith("организаци"):
            return bool(tail) and all(
                _relation_identity_name_token_supported(
                    identity_token,
                    # Quotes are intentionally absent from the canonical actor
                    # key.  Permit the same ambiguous final noun that the
                    # complete phrase parser already proved (for example
                    # quoted ``Бета`` or multiword ``Синий Щит``), while known
                    # predicates and unmistakable finite forms still fail.
                    allow_ambiguous_finite=(tail_index == len(tail) - 1),
                )
                for tail_index, identity_token in enumerate(tail)
            )
        if token.startswith(
            ("суд", "прокуратур", "прокурор", "полици", "правоохранител")
        ):
            return bool(tail) and (
                tail[0].startswith(
                    (
                        "округ",
                        "штат",
                        "город",
                        "район",
                        "графств",
                        "регион",
                        "провинци",
                        "муниципалитет",
                        "территори",
                    )
                )
                and _relation_complete_identity_supported(
                    " ".join(tail),
                    territorial=True,
                )
            )
    return False


def _extract_regulated_legal_action_claims(
    value: str,
) -> set[_QualitativeClaim]:
    """Fail-closed claims for assertive legal actions outside typed heads."""

    claims: set[_QualitativeClaim] = set()
    for action_name, action_pattern, object_patterns in (
        _REGULATED_LEGAL_ACTION_PATTERNS
    ):
        for action in re.finditer(action_pattern, value, re.IGNORECASE):
            projection = _predicate_relation(
                value,
                action.start("action"),
                action.end("action"),
            )
            if _regulated_action_is_context_only(
                projection,
                action.start("action"),
                action.end("action"),
            ):
                continue
            object_names = _regulated_action_objects(
                projection,
                action.start("action"),
                action.end("action"),
                object_patterns,
            )
            if not object_names:
                implicit_object = _regulated_implicit_subject_object(
                    value,
                    projection=projection,
                    action_start=action.start("action"),
                    action_end=action.end("action"),
                    object_patterns=object_patterns,
                )
                object_names = (
                    (implicit_object,)
                    if implicit_object
                    else ()
                )
            required_condition = False
            if not object_names:
                required_object = _regulated_required_condition_object(
                    value,
                    action_start=action.start("action"),
                    object_patterns=object_patterns,
                )
                object_names = (
                    (required_object,)
                    if required_object
                    else ()
                )
                required_condition = bool(required_object)
            if not object_names:
                continue
            respectively_pairs = _relation_respectively_pairs(
                value,
                action.start("action"),
                action.end("action"),
            )
            if respectively_pairs:
                modality = _claim_modality(
                    value,
                    action.start("action"),
                    action.end("action"),
                )
                polarity = (
                    "negative"
                    if _is_locally_negated(
                        value,
                        action.start("action"),
                        action.end("action"),
                    )
                    else "positive"
                )
                for actor, object_name, _object_start, _object_end in respectively_pairs:
                    if object_name not in object_names:
                        continue
                    authority = _qualitative_authority_for_relation_actor(
                        actor
                    )
                    if not authority:
                        continue
                    claims.add(
                        _QualitativeClaim(
                            action="regulated_legal_action",
                            object=f"{action_name}:{object_name}",
                            polarity=polarity,
                            modality=modality,
                            authority=authority,
                        )
                    )
                # Positional ``соответственно`` is a zip, never a Cartesian
                # product between every actor and every object.
                continue
            for object_name in object_names:
                claims.update(
                    _regulated_authority_list_claims(
                        value,
                        action_name=action_name,
                        action=action,
                        object_name=object_name,
                    )
                )
            authorities = _authorities_for_action(
                value,
                action.start("action"),
                action.end("action"),
            )
            if _relation_event(action.group("action")) == "nominal":
                nominal_actor = _bounded_nominal_operative_actor(projection)
                if (
                    nominal_actor
                    and not nominal_actor.startswith(
                        _RELATION_UNRESOLVED_ACTOR_PREFIX
                    )
                ):
                    nominal_authority = (
                        _qualitative_authority_for_relation_actor(
                            nominal_actor
                        )
                    )
                    if nominal_authority:
                        authorities = frozenset(
                            (*authorities, nominal_authority)
                        )
            modality = _claim_modality(
                value,
                action.start("action"),
                action.end("action"),
            )
            if required_condition:
                modality = "mandatory"
            # Participles such as ``выданный им пропуск`` are context for a
            # different predicate.  Without a local actor only an explicit
            # mandatory construction is assertive enough to fail closed.
            if not authorities and modality != "mandatory":
                continue
            for object_name in object_names:
                for authority in authorities or {""}:
                    claims.add(
                        _QualitativeClaim(
                            action="regulated_legal_action",
                            object=f"{action_name}:{object_name}",
                            polarity=(
                                "negative"
                                if _is_locally_negated(
                                    value,
                                    action.start("action"),
                                    action.end("action"),
                                )
                                else "positive"
                            ),
                            modality=modality,
                            authority=authority,
                        )
                    )
    return claims


_MANDATORY_AUTHORITY_MODAL_RE = (
    r"(?:обязан|обязана|обязано|обязаны|"
    r"должен|должна|должно|должны)"
)
_STRONG_MODAL_RE = (
    rf"(?P<negated>не\s+)?(?P<modal>"
    rf"{_MANDATORY_AUTHORITY_MODAL_RE}|надлежит)"
)
_INFINITIVE_ACTION_RE = re.compile(
    r"\b(?P<action>быть|дать|есть|идти|мочь|"
    r"[а-яё-]{3,}?(?:ться|чь|ть|ти))\b",
    re.IGNORECASE,
)


def _infinitive_actions_without_copula(
    matches: Iterable[re.Match[str]],
) -> list[re.Match[str]]:
    """Drop the analytic-passive copula before an occurrence is emitted.

    ``быть`` is an auxiliary, never the semantic action: in ``лицензия
    должна быть изъята`` the physical action is the participle that
    follows it.  The copula owns neither an actor nor a patient, so
    emitting its span as a relation occurrence makes the fail-closed
    occurrence-grammar gate reject the whole reading.  The strong-modal
    passive parsers keep reading the same copula from their own stream.
    """

    return [
        match
        for match in matches
        if match.group("action").casefold().replace("ё", "е") != "быть"
    ]


_COORDINATED_INFINITIVE_RE = re.compile(
    r"\b(?:и|или|либо)\s+"
    r"(?:(?:не|незамедлительно|немедленно|сразу|"
    r"самостоятельно|лично|временно|обязательно)\s+){0,3}"
    r"(?P<action>[а-яё-]{3,}?(?:ться|чь|ть|ти))\b",
    re.IGNORECASE,
)
_FINITE_MODAL_ACTION_RE = re.compile(
    r"\b(?P<action>[а-яё-]{3,}?(?:"
    r"ается|яется|уется|ится|"
    r"ают|яют|уют|ят|ут|"
    r"ает|яет|ует|ит|ет))\b",
    re.IGNORECASE,
)
_MANDATORY_PREDICATE_STOP_WORDS = frozenset(
    {
        "а",
        "без",
        "в",
        "во",
        "для",
        "до",
        "за",
        "и",
        "из",
        "или",
        "к",
        "на",
        "о",
        "об",
        "от",
        "перед",
        "по",
        "после",
        "при",
        "с",
        "со",
    }
)


def _canonical_mandatory_predicate(value: str) -> str:
    folded = value.casefold().replace("ё", "е")
    reflexive = folded.endswith(("ся", "сь"))
    predicate = _relation_predicate_key(folded)
    return predicate + (":reflexive" if reflexive else "")


def _canonical_argument_token(value: str) -> str:
    """Small deterministic Russian case normalizer for predicate arguments."""

    folded = value.casefold().replace("ё", "е")
    for suffix in (
        "иями",
        "ями",
        "ами",
        "ого",
        "ему",
        "ому",
        "ыми",
        "ими",
        "иях",
        "ах",
        "ях",
        "ов",
        "ев",
        "ей",
        "ая",
        "яя",
        "ое",
        "ее",
        "ые",
        "ие",
        "ый",
        "ий",
        "ой",
        "ом",
        "ем",
        "ам",
        "ям",
        "у",
        "ю",
        "а",
        "я",
        "ы",
        "и",
        "е",
    ):
        if folded.endswith(suffix) and len(folded) - len(suffix) >= 3:
            return folded[:-len(suffix)]
    return folded


def _canonical_relation_detail_token(value: str) -> str:
    """Normalize one bounded open-vocabulary relation detail.

    Conditions, post-action grounds and nominal ground claims must share the
    same small morphology contract.  Keeping separate normalizers made an
    honest ``правила хранения`` / ``нарушение правил хранения`` paraphrase
    compare as ``хранен`` versus ``хранени`` and encouraged unsafe subset
    fallbacks.  This helper deliberately normalizes only grammatical endings;
    every lexical qualifier and proper-name token remains present.
    """

    raw = value.casefold().replace("ё", "е").strip(".,")
    canonical = _canonical_argument_token(raw)
    if (
        canonical.endswith("ост")
        and re.search(r"ост(?:и|ью|ей|ям|ями|ях)$", raw)
    ):
        # Restore the lexical soft sign for productive ``-ость`` nouns
        # after case-ending removal.  Never strip ``ь`` generically: ``уголь``
        # and ``угол`` (likewise ``медь``/``мед``) are different grounds.
        canonical += "ь"
    if (
        canonical.endswith("и")
        and re.search(r"(?:ни|си)[еяию]?$", raw)
    ):
        canonical = canonical[:-1]
    if canonical.endswith("о") and re.search(r"(?:ен|ан|ян)о$", raw):
        canonical = canonical[:-1]
    if canonical.endswith("ство") and len(canonical) > 5:
        # Neuter abstract nouns regularly alternate ``-ство`` / ``-стве``:
        # ``убийство`` and ``об убийстве`` name the same ground.
        canonical = canonical[:-1]
    if canonical.endswith(("ых", "их")) and len(canonical) > 4:
        canonical = canonical[:-2]
    return canonical


_RELATION_GROUND_CONTRACT_GLUE = frozenset(
    {
        "и",
        "или",
        "либо",
    }
)


def _relation_detail_lexeme_key(
    value: str,
    match: re.Match[str],
    scan: _RelationDelimitedScan,
) -> str:
    raw = match.group(0)
    if re.fullmatch(r"[&/+#]+", raw):
        return "operator:" + raw
    exact = False
    for start, end in scan.spans:
        if not (start < match.start() and match.end() < end):
            continue
        opener = value[start:start + 1]
        exact = opener in {"«", "“", "„", "‹", "‘", '"', "'"} or (
            opener in {"(", "["}
            and _relation_parenthetical_payload_kind(value[start:end])
            == "identity"
        )
        if exact:
            break
    if exact:
        folded = unicodedata.normalize("NFKC", raw).casefold()
        folded = folded.replace("ё", "е")
        return "exact:" + folded
    folded = raw.casefold().replace("ё", "е")
    if folded in {"об", "обо"}:
        folded = "о"
    return _canonical_relation_detail_token(folded)


def _relation_exact_identity_contract_spans(
    value: str,
    scan: _RelationDelimitedScan,
) -> tuple[tuple[int, int, str, str], ...]:
    """Return bounded atomic contracts for exact delimited identities.

    Word-only identity keys lose punctuation and Boolean-looking words inside
    an official name: ``«Рога и Копыта»`` used to collapse to the
    same key as ``«Рога Копыта»``.  Preserve each balanced quoted name
    (and name-like parenthetical) as one normalized, length-bounded digest.
    Delimiter glyphs are presentation; delimiter *kind*, payload punctuation,
    connector words and the boundary between adjacent names are semantic.
    """

    candidates: list[tuple[int, int, str]] = []
    for start, end in scan.spans:
        opener = value[start:start + 1]
        if opener in {"«", "“", "„", "‹", "‘", '"', "'"}:
            kind = "quote"
        elif (
            opener in {"(", "["}
            and _relation_parenthetical_payload_kind(value[start:end])
            == "identity"
        ):
            kind = "parenthetical"
        else:
            continue
        candidates.append((start, end, kind))

    # A quoted/parenthetical identity may itself contain balanced delimiters.
    # The outer exact identity owns that payload; emitting nested atoms as
    # well would make harmless nesting alter the key.
    selected: list[tuple[int, int, str]] = []
    for start, end, kind in sorted(
        candidates,
        key=lambda item: (item[0], -(item[1] - item[0])),
    ):
        if any(
            outer_start <= start and end <= outer_end
            for outer_start, outer_end, _ in selected
        ):
            continue
        selected.append((start, end, kind))

    contracts: list[tuple[int, int, str, str]] = []
    for start, end, kind in sorted(selected):
        payload = unicodedata.normalize("NFKC", value[start + 1:end - 1])
        payload = payload.casefold().replace("ё", "е")
        payload = " ".join(payload.split())
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        contracts.append(
            (
                start,
                end,
                kind,
                f"__exact_{kind}__:{len(payload)}:{digest}",
            )
        )
    return tuple(contracts)


def _relation_position_in_exact_identity(
    position: int,
    spans: Iterable[tuple[int, int, str, str]],
) -> bool:
    return any(start < position < end for start, end, _, _ in spans)


def _canonical_relation_ground_contract(value: str) -> str:
    """Keep the ordered, multiplicity-preserving identity of one ground.

    A token set cannot distinguish ``A attacked B`` from ``B attacked A`` and
    silently loses a repeated participant.  This bounded legal surface keeps
    every lexical token in source order; Boolean logic is stored separately by
    the condition/exclusion parsers.
    """

    tokens: list[tuple[int, str, str]] = []
    scan = _relation_delimited_scan(value)
    exact_spans = _relation_exact_identity_contract_spans(value, scan)
    tokens.extend(
        (start, "exact", contract)
        for start, _end, _kind, contract in exact_spans
    )
    for match in _RELATION_DETAIL_LEXEME_RE.finditer(value):
        if _relation_position_in_exact_identity(match.start(), exact_spans):
            continue
        raw = match.group(0).casefold().replace("ё", "е")
        if raw in _RELATION_GROUND_CONTRACT_GLUE:
            continue
        if raw == "за" and not any(
            position < match.start()
            for position, _kind, _token in tokens
        ):
            # Leading ``за`` is the output-side ground marker.  The same
            # preposition inside the bounded ground remains role-bearing.
            continue
        canonical = _relation_detail_lexeme_key(value, match, scan)
        if canonical:
            tokens.append((match.start(), "token", canonical))
    return " ".join(
        token for _position, _kind, token in sorted(tokens)
    )


_RELATION_GROUND_FORMULA_AND = " ~~and~~ "


def _canonical_ground_formula_atom(value: str) -> str:
    """Canonicalize one indivisible ground while preserving role order."""

    canonical = _canonical_relation_ground_contract(value)
    tokens = canonical.split()
    while tokens and tokens[0] in {
        "факт",
        "налич",
        "наличи",
        "соверш",
        "совершен",
        "совершени",
        "выявлен",
        "выявлени",
        "установлен",
        "установлени",
        "доказан",
        "доказанн",
        "зафиксирован",
    }:
        tokens.pop(0)
    if len(tokens) >= 2 and tokens[0] == "не" and tokens[1].startswith(
        ("соблюд", "выполн", "исполн")
    ):
        tokens[:2] = ["несоблюден"]
    return " ".join(tokens)


def _encode_ground_formula_branch(atoms: Iterable[str]) -> str:
    normalized = tuple(atom for atom in atoms if atom)
    return _RELATION_GROUND_FORMULA_AND.join(sorted(normalized))


def _decode_ground_formula_branch(value: str) -> tuple[str, ...]:
    return tuple(
        atom.strip()
        for atom in value.split(_RELATION_GROUND_FORMULA_AND)
        if atom.strip()
    )


