def _mandatory_boolean_argument_surface(value: str) -> str | None:
    """Canonicalize one complete homogeneous Boolean NP, if proved.

    A legal object list is commutative (``archive and document`` names the
    same two patients in either order), but ordinary predicate arguments are
    not.  Keep this exception deliberately narrow: no delimiters, punctuation,
    subordinate/modal/action material, mixed AND/OR, empty atoms or atoms that
    begin/end in a function word.  Every atom otherwise remains an exact
    normalized surface and sorting retains duplicate multiplicity.
    """

    if not value or len(value) > 240:
        return None
    scan = _relation_delimited_scan(value)
    if (
        scan.malformed
        or scan.spans
        or re.search(r"[;:.!?\r\n()[\]{}\"'«»]", scan.masked) is not None
        or _GENERIC_MODAL_SUBORDINATE_RE.search(scan.masked) is not None
        or _GENERIC_MODAL_RE.search(scan.masked) is not None
        or _INFINITIVE_ACTION_RE.search(scan.masked) is not None
    ):
        return None
    correlative = re.fullmatch(
        r"как\s+(?P<first>[^,;.!?\r\n]{1,100}),\s*"
        r"так\s+и\s+(?P<second>[^,;.!?\r\n]{1,100})",
        value,
        re.IGNORECASE,
    )
    connectors = tuple(
        _RELATION_BOUNDED_PATIENT_CONNECTOR_RE.finditer(scan.masked)
    )
    if not connectors:
        return None
    if correlative is not None:
        atoms = (correlative.group("first"), correlative.group("second"))
        kinds = {"and"}
    else:
        bare_commas = tuple(
            connector
            for connector in connectors
            if not connector.group(0).strip(" \t,")
        )
        if (
            bare_commas
            and len(bare_commas) == len(connectors)
            and len(bare_commas) < 2
        ):
            return None
        kinds = {
            (
                "and"
                if _relation_patient_connector_kind(connector.group(0)) == "и"
                else "or"
                if _relation_patient_connector_kind(connector.group(0)) == "или"
                else ""
            )
            for connector in connectors
        }
        boundaries = (0,) + tuple(
            position
            for connector in connectors
            for position in (connector.start(), connector.end())
        ) + (len(value),)
        atoms = tuple(
            value[boundaries[index]:boundaries[index + 1]].strip()
            for index in range(0, len(boundaries) - 1, 2)
        )
    if "" in kinds:
        return None
    if len(kinds) != 1:
        return None
    function_words = {
        "а",
        "без",
        "в",
        "во",
        "для",
        "до",
        "за",
        "из",
        "к",
        "ко",
        "на",
        "над",
        "между",
        "о",
        "об",
        "от",
        "перед",
        "под",
        "по",
        "при",
        "с",
        "со",
        "у",
        "через",
    }
    if correlative is None and len(atoms) != len(connectors) + 1:
        return None
    for atom in atoms:
        words = tuple(_RELATION_WORD_RE.finditer(atom))
        if (
            not words
            or len(words) > 10
            or words[0].group(0).casefold() in function_words
            or words[-1].group(0).casefold() in function_words
        ):
            return None
        covered = list(atom)
        for word in words:
            covered[word.start():word.end()] = " " * (
                word.end() - word.start()
            )
        if "".join(covered).strip():
            return None
        head = words[-1]
        leading = atom[:head.start()].strip()
        proved_patient, _contract = (
            _relation_open_patient_morphology_contract(
                head.group(0),
                leading=leading,
                role="accusative",
            )
        )
        if not proved_patient:
            return None
    return (
        "modal_boolean:v1:"
        + next(iter(kinds))
        + ":"
        + "\x1d".join(sorted(atoms))
    )


def _mandatory_argument_qualifiers(
    value: str,
    *,
    leading_value: str = "",
) -> frozenset[str]:
    """Serialize one modal action's bounded argument without morphology loss.

    The former token set erased word order, multiplicity and Russian case, and
    an empty generated set was therefore a subset of every source argument.
    Keep the complete local surface as one opaque contract instead.  NFKC,
    case-folding and whitespace folding are presentation-only; every lexical
    token, ending, connector and repeated occurrence remains inside the digest.

    ``value`` and ``leading_value`` are already bounded by a hard clause or a
    proved action bridge.  A single non-empty role is serialized identically
    whether Russian word order put it before or after the predicate (the safe
    ``Архив суд должен уничтожить`` case).  If both sides contain material, the
    record separator preserves their physical order instead of flattening them.
    """

    def normalized_surface(surface: str) -> str:
        normalized = unicodedata.normalize("NFKC", surface).casefold()
        normalized = normalized.replace("ё", "е")
        return " ".join(
            normalized.strip(" \t\r\n,;:.\u2014\u2013-").split()
        )

    surfaces = tuple(
        surface
        for surface in (
            normalized_surface(leading_value),
            normalized_surface(value),
        )
        if surface
    )
    boolean_surface = (
        _mandatory_boolean_argument_surface(surfaces[0])
        if len(surfaces) == 1
        else None
    )
    surface = boolean_surface or "\x1f".join(surfaces)
    if not re.search(r"[а-яa-z0-9№]", surface, re.IGNORECASE):
        return frozenset()
    token_count = len(
        re.findall(r"[а-яёa-z0-9№][а-яёa-z0-9№'\u2019.-]*", surface)
    )
    digest = hashlib.sha256(surface.encode("utf-8")).hexdigest()
    return frozenset(
        {
            "mandatory_arguments:v2:"
            f"{len(surfaces)}:{token_count}:{len(surface)}:{digest}"
        }
    )


def _mandatory_predicate_arguments(
    value: str,
    action_end: int,
) -> frozenset[str]:
    _, hard_end = _hard_clause_bounds(value, action_end, action_end)
    tail = value[action_end:hard_end]
    return _mandatory_argument_qualifiers(tail)


# One epistemic frame - a hedge, a rumor attribution, a closing ``, возможно``
# or a terminal ``?`` - is neither a reason to drop the check nor part of the
# clause text.  It is carried as its own digest atom, and the support contract
# reads those atoms directionally: an output may state MORE of them than its
# source did (weakening a categorical source is entailed), never fewer
# (turning a hedged source into a categorical claim is not).
_RELATION_EPISTEMIC_FRAME_KIND = "relation_epistemic_frame"
_RELATION_EPISTEMIC_FRAME_PREFIX = _RELATION_EPISTEMIC_FRAME_KIND + ":"
_RELATION_DISCOURSE_OPENING_KIND = "relation_discourse_opening"
_RELATION_DISCOURSE_OPENING_PREFIX = (
    _RELATION_DISCOURSE_OPENING_KIND + ":"
)
_RELATION_TERMINAL_QUESTION_RE = re.compile(r"[ \t\u00a0]*(?P<mark>\?)")
_RELATION_EPISTEMIC_MARKER_STRIP = " \t\u00a0,;:.()[]{}«»\u201c\u201d\"'"


def _relation_epistemic_marker_surface(value: str) -> str:
    """Normalize one frame surface so position cannot change its identity.

    ``Возможно,`` at the head and ``, возможно`` at the tail are the same
    epistemic operator, so both fold to ``возможно``.  The wording itself is
    kept: ``едва ли`` weakens a claim in the opposite direction from
    ``возможно`` and must not be interchangeable with it.
    """

    folded = unicodedata.normalize("NFKC", value).casefold().replace("ё", "е")
    return " ".join(folded.strip(_RELATION_EPISTEMIC_MARKER_STRIP).split())


def _strong_modal_digest_qualifier(kind: str, value: str) -> str:
    normalized = unicodedata.normalize("NFKC", value).casefold()
    normalized = " ".join(normalized.replace("ё", "е").split())
    digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
    return f"{kind}:v1:{len(normalized)}:{digest}"


@dataclass(frozen=True)
class _StrongModalWrapperSyntax:
    """One same-length delimiter-masked surface for action-local scope.

    ``surface`` has exactly the length of the value it was built from, so every
    offset taken from the raw text keeps its meaning after masking.  Complete
    balanced wrappers - quotes, guillemets, parentheses and brackets alike -
    become blanks: a marker written inside a name cannot own an action outside
    it, and the wrapper itself stops acting as a clause fence, so the action
    keeps the same hard clause it would have had without the name.

    A malformed delimiter proves nothing about scope.  ``surface`` then stays
    the raw value and ``spans`` is empty, which switches every safe
    query/epistemic/modal/subordinate fence off and leaves the audit
    fail-closed on the exact bytes.
    """

    surface: str
    malformed: bool
    spans: tuple[tuple[int, int], ...]

    def encloses(self, start: int, end: int) -> bool:
        """Return true when a complete balanced wrapper contains the span."""

        return any(
            span_start <= start and end <= span_end
            for span_start, span_end in self.spans
        )


def _strong_modal_wrapper_syntax(value: str) -> _StrongModalWrapperSyntax:
    """Return the single delimiter contract shared by ownership and digest."""

    scan = _relation_delimited_scan(value)
    if scan.malformed:
        return _StrongModalWrapperSyntax(
            surface=value,
            malformed=True,
            spans=(),
        )
    return _StrongModalWrapperSyntax(
        surface=scan.masked,
        malformed=False,
        spans=scan.spans,
    )


def _strong_modal_wrapper_clause_bounds(
    value: str,
    start: int,
    end: int,
) -> tuple[int, int]:
    """Bound the hard clause through the shared delimiter mask.

    Reading the bounds off the masked surface is what keeps a wrapper from
    silently shortening the occurrence: ``Организация (Может) пишет арест``
    must stay one clause about ``Организация``, not a bare ``пишет арест``
    that every sibling occurrence would also hash to.  The mask has the same
    length as the value, so the returned offsets still index the raw text.
    """

    return _hard_clause_bounds(
        _strong_modal_wrapper_syntax(value).surface,
        start,
        end,
    )


_STRONG_MODAL_WRAPPER_MARKER_PREFIX = "finite_clause_marker_name:v1:"
_STRONG_MODAL_WRAPPER_PAYLOAD_TRIM = " \t\r\n.,;:!?—–-"


def _strong_modal_wrapper_marker_name(payload: str) -> str | None:
    """Return the canonical name when a wrapper holds a scope marker alone.

    ``«Чтобы»`` and ``(если)`` are the one payload shape this class is about:
    a token that the raw scanners mistake for a branch of the sentence while
    it is in fact the whole name of a party.  Any other payload - ``«Архив»``,
    ``(по решению суда)`` - stays ordinary clause content, so the existing
    ``cannot change or drop`` contract keeps owning it byte for byte.
    """

    inner = payload[1:-1] if len(payload) >= 2 else ""
    inner = inner.strip(_STRONG_MODAL_WRAPPER_PAYLOAD_TRIM)
    if not inner:
        return None
    if (
        _GENERIC_MODAL_SUBORDINATE_RE.fullmatch(inner) is None
        and _GENERIC_MODAL_RE.fullmatch(inner) is None
    ):
        return None
    return " ".join(inner.casefold().replace("ё", "е").split())


def _strong_modal_marker_named_clause(
    value: str,
    hard_start: int,
    hard_end: int,
) -> tuple[str, frozenset[str]]:
    """Split a clause into scope-bearing text and marker-named identities.

    The same defect has two sides.  Reading ``«Чтобы»`` as a branch lets a
    recombined output launder itself; hashing it as ordinary clause text
    makes the source destroy its own assertion, because the faithful output
    that keeps the fact and drops the name no longer matches.  The clause is
    therefore hashed without such names, and each name is emitted separately
    so the support check can require the output's names to be a subset of the
    source's: dropping a marker name the source stated is allowed, inventing
    one that the source never wrote is not.
    """

    syntax = _strong_modal_wrapper_syntax(value)
    if syntax.malformed:
        return value[hard_start:hard_end], frozenset()
    surface = list(value)
    names: set[str] = set()
    for span_start, span_end in syntax.spans:
        if span_start < hard_start or hard_end < span_end:
            continue
        name = _strong_modal_wrapper_marker_name(value[span_start:span_end])
        if name is None:
            continue
        names.add(
            _STRONG_MODAL_WRAPPER_MARKER_PREFIX
            + hashlib.sha256(name.encode("utf-8")).hexdigest()
        )
        surface[span_start:span_end] = " " * (span_end - span_start)
    return "".join(surface[hard_start:hard_end]), frozenset(names)


def _strong_modal_mask_envelope_label(value: str) -> str:
    """Mask one transport label while preserving every semantic offset."""

    label = _STRONG_MODAL_ENVELOPE_LABEL_RE.match(value)
    if label is None:
        return value
    return " " * label.end() + value[label.end():]


_STRONG_MODAL_TENSE_PREFIX = "modal_tense:"
_STRONG_MODAL_UNRESOLVED_PREFIXES = (
    "unresolved_finite_clause:",
    "unresolved_modal_clause:",
    "modal_unresolved_actor_grammar:",
)


def _strong_modal_tense_qualifier(
    modal_surface: str,
    pre_action_surface: str = "",
) -> str:
    folded = " ".join(modal_surface.casefold().replace("ё", "е").split())
    if folded in {"мог", "могла", "могло", "могли", "имел право", "имела право", "имело право", "имели право"}:
        return "modal_tense:past"
    if folded in {"сможет", "смогут"}:
        return "modal_tense:future"
    auxiliary = _GENERIC_MODAL_TENSE_AUX_RE.match(pre_action_surface)
    if auxiliary is not None:
        aux = auxiliary.group("aux").casefold().replace("ё", "е")
        return (
            "modal_tense:future"
            if aux in {"будет", "будут"}
            else "modal_tense:past"
        )
    if _GENERIC_MODAL_MAY_RE.fullmatch(modal_surface) is not None:
        return "modal_tense:present"
    return "modal_tense:atemporal"


def _strong_modal_without_tense_auxiliary(value: str) -> str:
    auxiliary = _GENERIC_MODAL_TENSE_AUX_RE.match(value)
    return value[auxiliary.end():] if auxiliary is not None else value


def _strong_modal_tense_auxiliary_qualifiers(
    value: str,
    *,
    modal_surface: str,
) -> frozenset[str]:
    auxiliary = _GENERIC_MODAL_TENSE_AUX_RE.match(value)
    if auxiliary is None:
        return frozenset()
    folded = auxiliary.group("aux").casefold().replace("ё", "е")
    feature = (
        "masculine"
        if folded == "был"
        else "feminine"
        if folded == "была"
        else "neuter"
        if folded == "было"
        else "plural"
        if folded in {"были", "будут"}
        else "singular"
    )
    modal_feature = _strong_modal_observed_modal_feature(modal_surface)
    future = folded in {"будет", "будут"}
    lexical_tense = _strong_modal_tense_qualifier(modal_surface)
    double_tense = lexical_tense in {
        "modal_tense:past",
        "modal_tense:future",
    }
    resolved = modal_feature in {
        "masculine",
        "feminine",
        "neuter",
        "plural",
        "singular",
        "invariant",
    }
    agrees = bool(
        resolved
        and (
            modal_feature == "plural" and feature == "plural"
            or modal_feature in {"masculine", "feminine", "neuter"}
            and (
                feature == "singular"
                if future
                else feature == modal_feature
            )
            or modal_feature == "invariant"
            and (
                feature == "singular" if future else feature == "neuter"
            )
        )
    )
    if agrees and not double_tense:
        # Tense is already encoded by ``modal_tense:*``.  A proved auxiliary
        # ending is only voice-specific agreement (``должен был`` / ``должна
        # была``), so it must not block a faithful active/passive paraphrase.
        return frozenset()
    state = "invalid" if resolved or double_tense else "unresolved"
    qualifiers = {
        f"modal_tense_aux_grammar:{state}",
        "modal_observed_tense_aux:" + feature,
        "modal_observed_governor:" + modal_feature,
        _strong_modal_digest_qualifier(
            "modal_tense_aux_grammar_" + state,
            "\x1f".join((modal_surface, auxiliary.group("aux"))),
        ),
    }
    if double_tense:
        # ``мог был`` / ``сможет будет`` stack a copular auxiliary on a
        # modal that already carries tense lexically.  Agreement cannot make
        # that construction grammatical, so retain the malformed structure
        # as exact evidence instead of laundering it into the clean modal.
        qualifiers.add("modal_tense_aux_structure:double-tense")
    return frozenset(qualifiers)


def _strong_modal_context_contract(
    value: str,
    *,
    include_broad_leading_condition: bool = False,
) -> tuple[str, frozenset[str]]:
    """Mask and serialize only context physically owned by one action.

    The old helper scanned the whole hard clause for every coordinated
    infinitive.  Consequently the first condition (and the union of every
    purpose/ground) was copied to all actions, so local facets could be
    swapped or dropped.  Callers now pass either the shared pre-modal prefix
    or one action's bounded incoming/argument slice.  Multiplicity is retained
    inside one sorted formula digest; no facet is borrowed across actions.
    """

    matches: list[tuple[int, int, str, str]] = []
    broad_condition_spans: list[tuple[int, int]] = []
    if include_broad_leading_condition:
        _subject, actor_surface, leading = (
            _strong_modal_premodal_actor_suffix(value)
        )
        leading_folded = leading.lstrip().casefold()
        if _subject and re.match(
            r"^(?:при|если|в\s+случае)\b",
            leading_folded,
            re.IGNORECASE,
        ):
            start = value.find(leading)
            if start >= 0:
                broad_condition_spans.append((start, start + len(leading)))
        _subject, actor_surface, trailing = (
            _strong_modal_postmodal_actor_prefix(value)
        )
        trailing_folded = trailing.lstrip().casefold()
        if _subject and re.match(
            r"^(?:при|если|в\s+случае)\b",
            trailing_folded,
            re.IGNORECASE,
        ):
            actor_start = value.find(actor_surface)
            start = value.find(trailing, actor_start + len(actor_surface))
            if start >= 0:
                broad_condition_spans.append((start, start + len(trailing)))
        for start, end in broad_condition_spans:
            matches.append(
                (start, end, "modal_condition", value[start:end])
            )
    for event in _GENERIC_MODAL_SIMPLE_EVENT_CONDITION_RE.finditer(value):
        matches.append(
            (event.start(), event.end(), "modal_condition", event.group(0))
        )
    for purpose in _GENERIC_MODAL_PURPOSE_RE.finditer(value):
        matches.append(
            (purpose.start(), purpose.end(), "modal_purpose", purpose.group(0))
        )
    for purpose in _GENERIC_MODAL_NOMINAL_PURPOSE_RE.finditer(value):
        matches.append(
            (purpose.start(), purpose.end(), "modal_purpose", purpose.group(0))
        )
    for condition in _GENERIC_MODAL_OPEN_CONDITION_RE.finditer(value):
        if any(
            start < condition.end() and condition.start() < end
            for start, end in broad_condition_spans
        ):
            continue
        matches.append(
            (
                condition.start(),
                condition.end(),
                "modal_condition",
                condition.group(0).strip(" \t,;:"),
            )
        )
    for ground in _GENERIC_MODAL_GROUND_RE.finditer(value):
        matches.append(
            (
                ground.start(),
                ground.end(),
                "modal_ground",
                ground.group(0).strip(" \t,;:"),
            )
        )

    grouped: dict[str, list[str]] = {}
    for _start, _end, kind, surface in matches:
        normalized = unicodedata.normalize("NFKC", surface).casefold()
        normalized = " ".join(normalized.replace("ё", "е").split())
        if normalized:
            grouped.setdefault(kind, []).append(normalized)

    qualifiers = frozenset(
        _strong_modal_digest_qualifier(
            kind,
            "\x1f".join(sorted(surfaces)),
        )
        for kind, surfaces in grouped.items()
    )
    masked = list(value)
    for start, end, _kind, _surface in matches:
        masked[start:end] = " " * (end - start)
    return "".join(masked), qualifiers


def _strong_modal_condition_qualifiers(
    value: str,
    *,
    include_broad_leading_condition: bool = False,
) -> frozenset[str]:
    return _strong_modal_context_contract(
        value,
        include_broad_leading_condition=include_broad_leading_condition,
    )[1]


def _strong_modal_without_owned_context(value: str) -> str:
    return _strong_modal_context_contract(value)[0]


def _strong_modal_personal_roles(
    prefix: str,
    modal_surface: str,
) -> tuple[str, str, str]:
    """Return one complete actor and an optional object-first patient.

    Known actor grammar is reused from the shared relation parser.  Trying
    successively shorter suffixes distinguishes ``Архив районный суд`` from
    the complete actor ``районный суд`` without reducing that actor to its last
    word.  Unknown but otherwise bounded SVO subjects retain the existing
    complete modal-actor fallback.  An unresolved known actor fails closed by
    returning no claim rather than silently borrowing a shorter identity.
    """

    prefix = re.sub(r"\bне\s*$", "", prefix, flags=re.IGNORECASE)
    cleaned = _strong_modal_without_owned_context(
        _relation_prefix_without_adjuncts(prefix)
    ).strip(
        " \t\r\n,;:.\u2014\u2013-"
    )
    if not cleaned:
        return "", "", ""
    words = tuple(_RELATION_WORD_RE.finditer(cleaned))
    for word in words:
        suffix = cleaned[word.start():].strip()
        actor = _relation_complete_postposed_actor_key(suffix)
        if not actor:
            continue
        if actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
            continue
        leading = cleaned[:word.start()].strip(
            " \t\r\n,;:.\u2014\u2013-"
        )
        if leading and re.match(
            r"^(?:при|если|когда|пока|в\s+случа)\b",
            leading,
            re.IGNORECASE,
        ):
            # The exact condition is retained independently below.  It is not
            # a pre-modal patient of this personal construction.
            leading = ""
        return "subject:" + actor, leading, suffix

    actor = _relation_modal_actor(prefix, modal_surface)
    if not actor or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
        return "", "", ""
    return "subject:" + actor, "", cleaned


def _strong_modal_impersonal_patient(prefix: str) -> str:
    prefix = re.sub(r"\bне\s*$", "", prefix, flags=re.IGNORECASE)
    cleaned = _strong_modal_without_owned_context(
        _relation_prefix_without_adjuncts(prefix)
    ).strip(
        " \t\r\n,;:.\u2014\u2013-"
    )
    return cleaned


def _strong_modal_impersonal_roles(
    prefix: str,
) -> tuple[str, str, str, frozenset[str]]:
    """Promote one morphologically proved dative experiencer to actor."""

    patient = _strong_modal_impersonal_patient(prefix)
    words = tuple(_RELATION_WORD_RE.finditer(patient))
    selected: tuple[str, str, str, frozenset[str]] | None = None
    for word in words:
        actor_surface = patient[word.start():].strip()
        features, _bare_bureau, known = _relation_known_actor_member_shape(
            actor_surface,
            role="dative",
        )
        if not known or not features:
            continue
        actor = _relation_actor_key(actor_surface, preserve_complete=True)
        if not actor or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
            continue
        leading = patient[:word.start()].strip()
        visible = tuple(
            sorted(
                feature
                for feature in features
                if feature in {"masculine", "feminine", "neuter", "plural"}
            )
        )
        if not visible:
            continue
        number = "plural" if "plural" in visible else "singular"
        governor = (
            "plural"
            if number == "plural"
            else next(
                (
                    feature
                    for feature in ("masculine", "feminine", "neuter")
                    if feature in visible
                ),
                "singular",
            )
        )
        qualifiers = frozenset(
            {
                "modal_actor_number:" + number,
            }
        )
        selected = (
            "subject:" + actor,
            leading,
            actor_surface,
            qualifiers,
        )
    return selected or ("", patient, "", frozenset())


def _strong_modal_bounded_pre_action_patient(value: str) -> str | None:
    """Return a simple exact O-before-V patient, or ``None`` if unproved."""

    patient = value.strip(" \t\r\n,;:.\u2014\u2013-")
    if not patient or len(patient) > 180:
        return None
    scan = _relation_delimited_scan(patient)
    if (
        scan.malformed
        or re.search(r"[;.!?\r\n]", scan.masked) is not None
        or _GENERIC_MODAL_SUBORDINATE_RE.search(scan.masked) is not None
        or _GENERIC_MODAL_RE.search(scan.masked) is not None
        or _INFINITIVE_ACTION_RE.search(scan.masked) is not None
        or re.match(
            r"^(?:при|если|когда|пока|в\s+случа|для|чтобы)\b",
            scan.masked,
            re.IGNORECASE,
        )
        is not None
    ):
        return None
    return patient


def _strong_modal_actor_qualifiers(
    actor_surface: str,
    *,
    governor: str = "",
    role: str,
) -> frozenset[str]:
    """Preserve actor cardinality and flag proved agreement failures."""

    def governor_feature(value: str) -> str:
        folded = " ".join(value.casefold().replace("ё", "е").split())
        if folded in {"обязан", "должен", "мог", "имел право"}:
            return "masculine"
        if folded in {"обязана", "должна", "могла", "имела право"}:
            return "feminine"
        if folded in {"обязано", "должно", "могло", "имело право"}:
            return "neuter"
        if folded in {
            "обязаны",
            "должны",
            "могут",
            "могли",
            "смогут",
            "имеют право",
            "имели право",
        }:
            return "plural"
        if folded in {"может", "сможет", "имеет право"}:
            return "singular"
        return ""

    def transparent_features(value: str) -> frozenset[str]:
        words = tuple(_RELATION_WORD_RE.finditer(value))
        if not words:
            return frozenset()
        head = words[-1].group(0).casefold().replace("ё", "е")
        if head.endswith(("ция", "сия", "гия")):
            return frozenset({"feminine"})
        if head.endswith("ство"):
            return frozenset({"neuter"})
        return frozenset()

    surface = actor_surface.strip(" \t\r\n,;:.\u2014\u2013-")
    if not surface:
        return frozenset()
    group = (
        _relation_actor_group_with_joint_focus(surface)
        or _relation_complete_actor_group(surface)
    )
    qualifiers: set[str] = set()
    observed_governor = _strong_modal_observed_modal_feature(governor)
    if group is not None:
        qualifiers.add("modal_actor_number:plural")
        if (
            role == "nominative"
            and governor_feature(governor)
            in {"masculine", "feminine", "neuter", "singular"}
        ):
            qualifiers.add("modal_actor_grammar:invalid")
            qualifiers.add("modal_observed_actor:plural")
            qualifiers.add("modal_observed_governor:" + observed_governor)
        return frozenset(qualifiers)

    features, _bare_bureau, known = _relation_known_actor_member_shape(
        surface,
        role=role,
    )
    if known and not features:
        qualifiers.add("modal_actor_grammar:invalid")
        qualifiers.add("modal_observed_governor:" + observed_governor)
        qualifiers.add(
            _strong_modal_digest_qualifier(
                "modal_invalid_actor_grammar",
                surface,
            )
        )
        return frozenset(qualifiers)
    if not known:
        features = transparent_features(surface)
    observed = tuple(
        sorted(
            feature
            for feature in features
            if feature in {"masculine", "feminine", "neuter", "plural"}
        )
    )
    if role == "nominative" and not observed:
        qualifiers.add(
            _strong_modal_digest_qualifier(
                "modal_unresolved_actor_grammar",
                surface,
            )
        )
        qualifiers.add("modal_observed_governor:" + observed_governor)
    if features:
        if features == frozenset({"plural"}):
            qualifiers.add("modal_actor_number:plural")
        elif "plural" not in features:
            qualifiers.add("modal_actor_number:singular")
    invalid = False
    if role == "nominative" and features:
        expected = governor_feature(governor)
        if expected == "plural" and "plural" not in features:
            invalid = True
        if expected == "singular" and features == frozenset({"plural"}):
            invalid = True
        if expected in {"masculine", "feminine", "neuter"} and (
            expected not in features
            or "plural" in features and len(features) == 1
        ):
            invalid = True
    if invalid:
        qualifiers.add("modal_actor_grammar:invalid")
        qualifiers.add("modal_observed_governor:" + observed_governor)
        qualifiers.add(
            "modal_observed_actor:"
            + ("-or-".join(observed) if observed else "unresolved")
        )
    return frozenset(qualifiers)


def _strong_modal_patient_feature(value: str) -> str | None:
    patient = value.strip(" \t\r\n,;:.\u2014\u2013-")
    words = tuple(_RELATION_WORD_RE.finditer(patient))
    if not words:
        return None
    if re.search(r"\b(?:и|или|либо)\b", patient, re.IGNORECASE):
        return "plural"
    typed_head = _relation_bounded_patient_primary_head(patient)
    if typed_head is not None:
        head_start, _head_end, head_surface, family = typed_head
        features = _relation_patient_head_features(
            family,
            head_surface,
            role="nominative",
            leading=patient[:head_start],
        )
        if features:
            if features & {"plural", "plural_animate", "quantified_plural"}:
                return "plural"
            genders = {
                gender
                for gender in ("masculine", "feminine", "neuter")
                if gender in features
                or gender == "masculine" and "masculine_animate" in features
            }
            if len(genders) == 1:
                return next(iter(genders))
    head_match = next(
        (
            word
            for word in words
            if not word.group(0).casefold().replace("ё", "е").endswith(
                ("ый", "ий", "ой", "ая", "яя", "ое", "ее", "ые", "ие")
            )
        ),
        words[-1],
    )
    head = head_match.group(0).casefold().replace("ё", "е")
    if head.endswith(("ы", "и")) and not head.endswith(
        ("ий", "ый", "ой")
    ):
        return "plural"
    if head.endswith(("ия", "ая", "яя", "а", "я")):
        return "feminine"
    if head.endswith(("ство", "о", "е")):
        return "neuter"
    if re.fullmatch(r"[а-я-]+", head, re.IGNORECASE):
        return "masculine"
    return None


def _strong_modal_observed_modal_feature(value: str) -> str:
    folded = " ".join(value.casefold().replace("ё", "е").split())
    if folded in {"обязан", "должен", "мог", "имел право"}:
        return "masculine"
    if folded in {"обязана", "должна", "могла", "имела право"}:
        return "feminine"
    if folded in {"обязано", "должно", "могло", "имело право"}:
        return "neuter"
    if folded in {
        "обязаны",
        "должны",
        "могут",
        "могли",
        "смогут",
        "имеют право",
        "имели право",
    }:
        return "plural"
    if folded in {"может", "сможет", "имеет право"}:
        return "singular"
    return "invariant"


def _strong_modal_participle_feature(value: str) -> str:
    folded = value.casefold().replace("ё", "е")
    if folded.endswith("ы"):
        return "plural"
    if folded.endswith("а"):
        return "feminine"
    if folded.endswith("о"):
        return "neuter"
    return "masculine"


def _strong_modal_passive_agreement_qualifiers(
    patient_surface: str,
    modal_surface: str,
    participle_surface: str,
    *,
    personal: bool,
) -> frozenset[str]:
    patient_feature = _strong_modal_patient_feature(patient_surface)
    modal_feature = _strong_modal_observed_modal_feature(modal_surface)
    participle_feature = _strong_modal_participle_feature(participle_surface)
    patient_agrees = _strong_modal_passive_patient_agrees(
        patient_surface,
        participle_surface,
    )
    modal_agrees = (
        _strong_modal_passive_modal_agrees(patient_surface, modal_surface)
        if personal
        else True
    )
    if (
        patient_feature is None
        or patient_agrees is None
        or personal
        and modal_agrees is None
    ):
        return frozenset(
            {
                "modal_passive_grammar:unresolved",
                _strong_modal_digest_qualifier(
                    "modal_unresolved_passive_grammar",
                    "\x1f".join(
                        (patient_surface, modal_surface, participle_surface)
                    ),
                ),
            }
        )
    if patient_agrees and modal_agrees:
        # Once agreement is proved, gender/number endings are merely the
        # grammatical realization of the same actor/patient relation.  Do not
        # make valid active/passive or modal-synonym paraphrases compare raw
        # surface features.
        return frozenset()
    qualifiers = {
        "modal_observed_governor:" + modal_feature,
        "modal_observed_participle:" + participle_feature,
        "modal_observed_patient:" + patient_feature,
        _strong_modal_digest_qualifier(
            "modal_invalid_passive_grammar",
            "\x1f".join((patient_surface, modal_surface, participle_surface)),
        ),
    }
    if not patient_agrees:
        qualifiers.add("modal_patient_grammar:invalid")
    if personal and not modal_agrees:
        qualifiers.add("modal_patient_modal_grammar:invalid")
    return frozenset(qualifiers)


def _strong_modal_passive_modal_agrees(
    patient_surface: str,
    modal_surface: str,
) -> bool | None:
    patient_feature = _strong_modal_patient_feature(patient_surface)
    if patient_feature is None:
        return None
    folded = " ".join(modal_surface.casefold().replace("ё", "е").split())
    modal_feature = (
        "masculine"
        if folded in {"обязан", "должен", "мог", "имел право"}
        else "feminine"
        if folded in {"обязана", "должна", "могла", "имела право"}
        else "neuter"
        if folded in {"обязано", "должно", "могло", "имело право"}
        else "plural"
        if folded
        in {
            "обязаны",
            "должны",
            "могут",
            "могли",
            "смогут",
            "имеют право",
            "имели право",
        }
        else "singular"
        if folded in {"может", "сможет", "имеет право"}
        else ""
    )
    if not modal_feature:
        return None
    if modal_feature == "singular":
        return patient_feature != "plural"
    return patient_feature == modal_feature


def _strong_modal_passive_patient_agrees(
    patient_surface: str,
    participle_surface: str,
) -> bool | None:
    """Check only transparent short-participle agreement; else stay neutral."""

    patient_feature = _strong_modal_patient_feature(patient_surface)
    if patient_feature is None:
        return None

    participle = participle_surface.casefold().replace("ё", "е")
    participle_feature = (
        "plural"
        if participle.endswith("ы")
        else "feminine"
        if participle.endswith("а")
        else "neuter"
        if participle.endswith("о")
        else "masculine"
    )
    return patient_feature == participle_feature


def _canonical_strong_modal_passive_predicate(value: str) -> str:
    folded = value.casefold().replace("ё", "е")
    for suffix in ("ированы", "ирована", "ировано", "ирован"):
        if folded.endswith(suffix) and len(folded) - len(suffix) >= 3:
            return _relation_predicate_key(folded[:-len(suffix)])
    for suffix in ("ованы", "ована", "овано", "ован"):
        if folded.endswith(suffix) and len(folded) - len(suffix) >= 3:
            return _relation_predicate_key(folded[:-len(suffix)])
    for suffix in ("еваны", "евана", "евано", "еван"):
        if folded.endswith(suffix) and len(folded) - len(suffix) >= 3:
            return _relation_predicate_key(folded[:-len(suffix)])
    for number_suffix in ("а", "о", "ы"):
        if folded.endswith(number_suffix):
            folded = folded[:-1]
            break
    for suffix in ("ен", "ан", "ян", "т"):
        if folded.endswith(suffix) and len(folded) - len(suffix) >= 3:
            return _relation_predicate_key(folded[:-len(suffix)])
    return ""


def _strong_modal_predicate_is_relation_owned(
    surface: str,
    predicate: str,
) -> bool:
    if surface.casefold().replace("ё", "е").endswith(("ся", "сь")):
        # The mature RelationTruth key currently erases reflexivity.  Keep the
        # generic exact claim until that parser has a first-class voice/form
        # contract; lexeme membership alone cannot prove ``sign`` = ``sign up``.
        return False
    return bool(
        _RELATION_ACTION_RE.fullmatch(surface) is not None
        or predicate in _STRICT_OPEN_FINITE_PREDICATES
    )


def _strong_modal_postposed_actor(value: str) -> tuple[str, str]:
    surface = value.strip(" \t\r\n,;:.\u2014\u2013-")
    if not surface or len(surface) > 180:
        return "", ""
    actor = _relation_complete_postposed_actor_key(surface)
    if actor and not actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
        return "subject:" + actor, surface
    scan = _relation_delimited_scan(surface)
    words = tuple(_RELATION_WORD_RE.finditer(scan.masked))
    if (
        scan.malformed
        or not words
        or len(words) > 8
        or re.search(r"[;.!?\r\n]", scan.masked) is not None
        or _GENERIC_MODAL_RE.search(scan.masked) is not None
        or _INFINITIVE_ACTION_RE.search(scan.masked) is not None
    ):
        return "", ""
    actor = _relation_actor_key(surface, preserve_complete=True)
    return (("subject:" + actor, surface) if actor else ("", ""))


def _strong_modal_postmodal_actor_prefix(
    value: str,
) -> tuple[str, str, str]:
    """Split ``must COURT [local material] ACTION`` without guessing actors."""

    surface = value.strip(" \t\r\n,;:.\u2014\u2013-")
    if not surface or len(surface) > 240:
        return "", "", value
    words = tuple(_RELATION_WORD_RE.finditer(surface))
    selected: tuple[str, str, str] | None = None
    for word in words:
        actor_surface = surface[:word.end()].strip()
        group = (
            _relation_actor_group_with_joint_focus(actor_surface)
            or _relation_complete_actor_group(actor_surface)
        )
        actor = (
            group.key
            if group is not None
            else _relation_complete_postposed_actor_key(actor_surface)
        )
        if not actor or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
            continue
        remainder = surface[word.end():].strip()
        selected = "subject:" + actor, actor_surface, remainder
    return selected or ("", "", value)


def _strong_modal_premodal_actor_suffix(
    value: str,
) -> tuple[str, str, str]:
    """Split ``ACTION [patient] COURT must`` at one proved actor suffix."""

    surface = value.strip(" \t\r\n,;:.\u2014\u2013-")
    if not surface or len(surface) > 240:
        return "", "", value
    words = tuple(_RELATION_WORD_RE.finditer(surface))
    for word in words:
        actor_surface = surface[word.start():].strip()
        group = (
            _relation_actor_group_with_joint_focus(actor_surface)
            or _relation_complete_actor_group(actor_surface)
        )
        actor = (
            group.key
            if group is not None
            else _relation_complete_postposed_actor_key(actor_surface)
        )
        if not actor or actor.startswith(_RELATION_UNRESOLVED_ACTOR_PREFIX):
            continue
        leading = surface[:word.start()].strip()
        return "subject:" + actor, actor_surface, leading
    return "", "", value


def _strong_modal_claim(
    value: str,
    *,
    action_start: int,
    action_end: int,
    subject: str,
    polarity: str,
    modality: str,
    predicate: str | None = None,
    arguments: frozenset[str] | None = None,
    qualifiers: frozenset[str] = frozenset(),
) -> _QualitativeClaim:
    return _QualitativeClaim(
        action="strong_modal_action",
        object=(
            predicate
            if predicate is not None
            else _canonical_mandatory_predicate(
                value[action_start:action_end]
            )
        ),
        polarity=polarity,
        modality=modality,
        authority=subject,
        qualifiers=(
            _mandatory_predicate_arguments(value, action_end)
            if arguments is None
            else arguments
        )
        | qualifiers,
    )


def _strong_modal_mature_action_is_coherent(
    value: str,
    *,
    action_start: int,
    action_end: int,
    modal_surface: str,
    analytic_passive: bool = False,
) -> bool:
    """Return true only when mature RelationTruth owns the physical action."""

    surface = value[action_start:action_end]
    predicate = _canonical_mandatory_predicate(surface)
    if not _strong_modal_predicate_is_relation_owned(
        surface,
        predicate.removesuffix(":reflexive"),
    ):
        return False
    modality = (
        "may"
        if _GENERIC_MODAL_MAY_RE.fullmatch(modal_surface) is not None
        else "mandatory"
    )
    truths = _build_relation_truth_variants(
        value,
        action_start=action_start,
        action_end=action_end,
        modality=modality,
    )
    return any(
        truth.assertive
        and truth.grammatical
        and truth.patient_grammatical
        and truth.actor_grammatical
        and truth.action_span == (action_start, action_end)
        and truth.modality == modality
        and (
            _GENERIC_MODAL_PERSONAL_RE.fullmatch(modal_surface) is None
            or bool(truth.operative_actor)
            # A personal modal agreeing with the passive subject licenses
            # an agentless analytic passive: the flag comes from the
            # passive parser, and the patient must still be proved.
            or (analytic_passive and bool(truth.direct_object))
        )
        and (
            truth.predicate not in _STRICT_GENERIC_PATIENT_PREDICATES
            or bool(truth.direct_object)
        )
        for truth in truths
    )


def _strong_modal_unresolved_claim(
    value: str,
    *,
    hard_start: int,
    hard_end: int,
    modal_surface: str,
    modality: str,
    polarity: str,
) -> _QualitativeClaim:
    clause = value[hard_start:hard_end].strip()
    return _QualitativeClaim(
        action="strong_modal_action",
        object="unresolved_modal_clause",
        polarity=polarity,
        modality=modality,
        qualifiers=frozenset(
            {
                _strong_modal_digest_qualifier(
                    "unresolved_modal_clause",
                    clause,
                ),
                _strong_modal_tense_qualifier(modal_surface),
            }
        ),
    )


def _strong_modal_family_claim(
    *,
    predicate: str,
    polarity: str,
    modality: str,
    tense: str,
    scope: frozenset[str] = frozenset(),
) -> _QualitativeClaim:
    return _QualitativeClaim(
        action="strong_modal_family",
        object=predicate,
        polarity=polarity,
        modality=modality,
        qualifiers=frozenset({tense}) | scope,
    )


_MODAL_COMPLETE_OCCURRENCE_PREFIX = "modal_complete_occurrence:v2:"
_MODAL_OCCURRENCE_ATOM_SEP = "\x1c"


def _strong_modal_occurrence_atoms(
    qualifiers: frozenset[str],
) -> tuple[tuple[frozenset[str], ...], frozenset[str]]:
    """Split modal qualifiers into occurrence atom sets and the rest."""

    occurrences: list[frozenset[str]] = []
    rest: set[str] = set()
    for qualifier in qualifiers:
        if qualifier.startswith(_MODAL_COMPLETE_OCCURRENCE_PREFIX):
            body = qualifier[len(_MODAL_COMPLETE_OCCURRENCE_PREFIX):]
            occurrences.append(
                frozenset(body.split(_MODAL_OCCURRENCE_ATOM_SEP))
                if body
                else frozenset()
            )
        else:
            rest.add(qualifier)
    return tuple(occurrences), frozenset(rest)


_MODAL_OCCURRENCE_TRUTHS: dict[str, "_RelationTruth"] = {}
# A bounded memo, never a cache with eviction: once the budget is spent, new
# atoms simply keep the byte-exact behaviour, so the validator can only become
# stricter and never depends on eviction order.
#
# It is also reset at every public entry point (``_reset_modal_occurrence_memo``).
# Without that reset the memo outlives the call in a long-lived process, and two
# things follow.  Memory: 200000 ``_RelationTruth`` objects — 24 fields with five
# frozensets each — are held forever by the bot.  Worse, the verdict stops being a
# function of its inputs: while budget remains an atom gets the semantic fallback,
# and once it is spent the same atom falls back to byte equality, so one text can
# be accepted in the morning and rejected in the evening.  Tests never see it
# because each run starts with an empty dict.
_MODAL_OCCURRENCE_TRUTH_BUDGET = 200000


# ``unresolved_finite_clause`` says only "this clause did not become a
# coherent occurrence"; it does not say why, and the two reasons are not
# interchangeable.  A hedge or a local non-assertion means the source withheld
# the assertion - nothing may ever prove it.  A grammar/span gap means the
# projector could not parse a clause the source did assert; the role-aware
# relation layer may still be able to.  The digest alone cannot tell them
# apart, so the parser-gap atoms are named here as they are produced.
#
# Same lifetime discipline as the occurrence memo: filled while the claims of
# one text are projected, cleared at every public entry point, so the verdict
# stays a function of its inputs.
_UNRESOLVED_CLAUSE_PARSER_GAP_ATOMS: set[str] = set()


def _reset_modal_occurrence_memo() -> None:
    """Scope the occurrence memo to one public validation call."""
    _reset_relation_wave9_reentrancy_guards()
    _MODAL_OCCURRENCE_TRUTHS.clear()
    _UNRESOLVED_CLAUSE_PARSER_GAP_ATOMS.clear()


def _strong_modal_saturating_match(left, right, edge):
    """Prove every left item can take a private right item.

    Greedy matching over a frozenset makes the verdict depend on hash
    iteration order as soon as one item fits several partners.  A maximum
    bipartite matching answers the same question, and its answer is a property
    of the graph rather than of the order the pairs were visited in.
    """

    left = tuple(left)
    right = tuple(right)
    if len(left) > len(right):
        return False
    matched: dict[int, int] = {}
    for index in range(len(left)):
        if not _strong_modal_matching_augment(
            index,
            left,
            right,
            edge,
            matched,
            set(),
        ):
            return False
    return True


def _strong_modal_matching_augment(index, left, right, edge, matched, seen):
    for candidate in range(len(right)):
        if candidate in seen or not edge(left[index], right[candidate]):
            continue
        seen.add(candidate)
        if candidate not in matched or _strong_modal_matching_augment(
            matched[candidate],
            left,
            right,
            edge,
            matched,
            seen,
        ):
            matched[candidate] = index
            return True
    return False


def _strong_modal_occurrence_atom_entailed(
    output_atom: str,
    source_atom: str,
) -> bool:
    """Accept one occurrence atom as a reading of another.

    Byte equality stays the fast path.  When two digests differ, the
    ``_RelationTruth`` values behind them are compared through
    ``_relation_truth_supported`` - the same typed contract the rest of this
    file uses for relation evidence, where the patient surface, the condition,
    the grounds, the permission DNF, the recipients and the references are each
    checked at their own relation instead of being demanded byte-exact inside
    one opaque digest.  An atom whose truth is not recorded stays fail-closed
    on byte equality.
    """

    if output_atom == source_atom:
        return True
    output_truth = _MODAL_OCCURRENCE_TRUTHS.get(output_atom)
    source_truth = _MODAL_OCCURRENCE_TRUTHS.get(source_atom)
    if output_truth is None or source_truth is None:
        return False
    if (
        output_truth.operative_actor != source_truth.operative_actor
        or output_truth.direct_object != source_truth.direct_object
    ):
        # The occurrence identity still owns actor and patient outright: an
        # output that dropped or replaced either of them is a different
        # occurrence, never a wording variant of this one.
        return False
    return _relation_truth_supported(output_truth, (source_truth,))


def _strong_modal_occurrence_group_supported(
    output_atoms: frozenset[str],
    source_atoms: frozenset[str],
    *,
    allow_inclusion: bool,
) -> bool:
    if output_atoms == source_atoms:
        return True
    if not output_atoms or not source_atoms:
        return False
    if not allow_inclusion and len(output_atoms) != len(source_atoms):
        return False
    return _strong_modal_saturating_match(
        sorted(output_atoms),
        sorted(source_atoms),
        _strong_modal_occurrence_atom_entailed,
    )


def _strong_modal_occurrence_supported(
    output_qualifiers: frozenset[str],
    candidate_qualifiers: frozenset[str],
    *,
    allow_inclusion: bool = True,
) -> bool:
    """Prove the output occurrence is one reading the source enumerates.

    A clause with coordinated actors proves every coherent reading it lists,
    so an output restating exactly one of them is entailed.  Inclusion is the
    only relaxation: the atoms themselves stay byte-exact, an empty output
    occurrence never matches a non-empty source one, and every non-occurrence
    qualifier still has to be equal.

    The single directional exception is the marker name a wrapper spelled out
    (``Организация «Чтобы» пишет арест``).  The output may state fewer of them
    than the source did - that is the source repeating its own fact without
    the party's name - but it may never state one the source never wrote, so
    an invented ``«Чтобы»`` is still a different occurrence.
    """

    output_occurrences, output_rest = _strong_modal_occurrence_atoms(
        output_qualifiers
    )
    source_occurrences, source_rest = _strong_modal_occurrence_atoms(
        candidate_qualifiers
    )
    output_marker_names = frozenset(
        qualifier
        for qualifier in output_rest
        if qualifier.startswith(_STRONG_MODAL_DROPPABLE_ATOM_PREFIXES)
    )
    source_marker_names = frozenset(
        qualifier
        for qualifier in source_rest
        if qualifier.startswith(_STRONG_MODAL_DROPPABLE_ATOM_PREFIXES)
    )
    if not output_marker_names <= source_marker_names:
        return False
    output_frames = frozenset(
        qualifier
        for qualifier in output_rest
        if qualifier.startswith(_RELATION_EPISTEMIC_FRAME_PREFIX)
    )
    source_frames = frozenset(
        qualifier
        for qualifier in source_rest
        if qualifier.startswith(_RELATION_EPISTEMIC_FRAME_PREFIX)
    )
    if not source_frames <= output_frames:
        # The one directional atom that runs the other way from a marker
        # name.  Weakening a categorical source ("возможно, суд аннулирует
        # лицензию") is entailed by the source and stays allowed; dropping a
        # hedge the source did write turns "едва ли аннулирует" into
        # "аннулирует" and is exactly the assertion the source refused to
        # make.
        return False
    if (output_rest - output_marker_names - output_frames) != (
        source_rest - source_marker_names - source_frames
    ):
        return False
    if len(output_occurrences) != len(source_occurrences):
        return False
    return _strong_modal_saturating_match(
        output_occurrences,
        source_occurrences,
        lambda output_atoms, source_atoms: (
            _strong_modal_occurrence_group_supported(
                output_atoms,
                source_atoms,
                allow_inclusion=allow_inclusion,
            )
        ),
    )


def _strong_modal_truth_occurrence_qualifier(
    truth: _RelationTruth,
) -> str:
    """Bind modality to one voice-neutral semantic occurrence.

    Only already grammatical RelationTruth variants reach this helper.  Their
    nominative/accusative endings and active/passive event labels are syntax,
    while actor, patient identity, tense family and semantic facets are the
    legal assertion.  Invalid/unresolved grammar never reaches this canonical
    path and remains fail-closed in the generic modal claim.
    """

    event_family = (
        "modal_governed"
        if truth.modality in {"may", "mandatory"}
        else "past"
        if truth.event in {"past", "past_passive"}
        else "present"
        if truth.event in {"present", "present_passive"}
        else truth.event
    )

    payload = "\x1f".join(
        (
            "family=" + truth.action_family,
            "actor=" + truth.operative_actor,
            "patient=" + truth.direct_object,
            "patient_surface=" + truth.patient_surface_contract,
            "container=" + truth.container_object,
            "purpose=" + truth.purpose_object,
            "condition=" + truth.condition,
            "decision=" + truth.decision_authority,
            "event=" + event_family,
            "coordination=" + truth.coordination,
            "polarity=" + truth.polarity,
            "recipients=" + "\x1e".join(sorted(truth.recipient_actors)),
            "grounds=" + "\x1e".join(sorted(truth.grounds)),
            "references=" + "\x1e".join(sorted(truth.references)),
            "arguments="
            + "\x1e".join(
                sorted(
                    f"{argument.role}:{argument.marker}:{argument.value}:"
                    f"{argument.polarity}:"
                    f"{','.join(sorted(argument.qualifiers))}"
                    for argument in truth.arguments
                )
            ),
            "modifiers=" + "\x1e".join(sorted(truth.action_modifiers)),
            # The four facets the fallback reads but the sixteen-facet
            # payload never carried.  Without them one digest stands for
            # a ``mandatory`` and a ``may`` reading at once (measured: 91
            # of 1240 digests carried more than one truth identity), and
            # the fallback would compare the wrong pair.  They are also
            # exactly the distinctions an occurrence identity must own.
            "predicate=" + truth.predicate,
            "modality=" + truth.modality,
            "voice=" + truth.event,
            "patient_grammar=" + truth.patient_grammar_contract,
        )
    )
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    qualifier = f"modal_occurrence:v2:{len(payload)}:{digest}"
    if (
        qualifier not in _MODAL_OCCURRENCE_TRUTHS
        and len(_MODAL_OCCURRENCE_TRUTHS) < _MODAL_OCCURRENCE_TRUTH_BUDGET
    ):
        _MODAL_OCCURRENCE_TRUTHS[qualifier] = truth
    return qualifier


def _strong_modal_complete_occurrence_qualifier(
    value: str,
    *,
    action_start: int,
    action_end: int,
    modality: str,
) -> str:
    variants = tuple(
        truth
        for truth in _build_relation_truth_variants(
            value,
            action_start=action_start,
            action_end=action_end,
            modality=modality,
        )
        if truth.assertive
        and truth.grammatical
        and truth.patient_grammatical
        and truth.actor_grammatical
        and truth.action_span == (action_start, action_end)
    )
    atoms = tuple(
        sorted(
            {
                _strong_modal_truth_occurrence_qualifier(truth)
                for truth in variants
            }
        )
    )
    # Keep every coherent reading addressable instead of collapsing the set
    # into one opaque digest.  Each atom stays byte-exact, so nothing inside a
    # reading may be dropped; only the *choice* of one enumerated reading is
    # what `_strong_modal_occurrence_supported` may accept by inclusion.
    return _MODAL_COMPLETE_OCCURRENCE_PREFIX + _MODAL_OCCURRENCE_ATOM_SEP.join(
        atoms
    )


def _strong_modal_active_patient_span(
    value: str,
    *,
    action_start: int,
    action_end: int,
    action_surface: str,
) -> tuple[int, int] | None:
    """Prove one post-predicate active patient with observable case evidence."""

    hard_start, hard_end = _hard_clause_bounds(
        value,
        action_start,
        action_end,
    )
    if "?" in value[hard_start:hard_end]:
        return None
    projection = _predicate_relation(
        value,
        action_start,
        action_end,
    )
    direct_object = _relation_generic_direct_object(
        projection,
        action_end,
    )
    if not direct_object.startswith("other:"):
        return None
    event = _relation_event(action_surface)
    if event != "present":
        return None
    object_span = _relation_open_patient_head_span(
        projection,
        action_start,
        action_end,
        direct_object,
        event=event,
    )
    local_action_end = action_end - projection.start
    if object_span is None or object_span[0] < local_action_end:
        return None
    grammatical, grammar_contract = _relation_patient_grammatical_shape(
        projection,
        action_start,
        action_end,
        direct_object=direct_object,
        event=event,
    )
    if not grammatical or grammar_contract.startswith("unresolved:"):
        return None
    # ``документа`` after a noun can masquerade as animate accusative while
    # really being a genitive owner (``макет документа``).  This supplemental
    # path intentionally fails closed for that ambiguity; mature predicates
    # continue to use the full relation grammar and keep their existing recall.
    object_surface = projection.text[object_span[0]:object_span[1]]
    leading = _relation_adjacent_leading_modifier_surface(
        projection.text,
        object_span[0],
    )
    explicit_accusative_modifier = bool(
        re.search(
            r"\b(?:[а-яё-]{3,}(?:ый|ий|ой|ую|юю|ое|ее|ые|ие)|"
            r"этот|эту|это|эти|тот|ту|то|те|весь|всю|все|"
            r"каждый|каждую|каждое|каждые)\b",
            leading,
            re.IGNORECASE,
        )
        is not None
    )
    folded_object_surface = object_surface.casefold().replace("ё", "е")
    observable_genitive_plural = bool(
        re.search(
            r"(?:ов|ев|ей|ий|аний|ений|ств)$",
            folded_object_surface,
        )
        is not None
    )
    bare_consonant_patient = bool(
        not leading.strip()
        and len(folded_object_surface) >= 5
        and not observable_genitive_plural
        and re.search(
            r"[бвгджзйклмнпрстфхцчшщь]$",
            folded_object_surface,
        )
        is not None
    )
    independent_neuter_patient = bool(
        not leading.strip()
        and re.search(
            r"(?:о|ание|ение|ство)$",
            folded_object_surface,
        )
        is not None
    )
    typed_direct_object, _container_object, _purpose_object = (
        _relation_object_roles(
            projection,
            action_start,
            action_end,
            event=event,
        )
    )
    typed_accusative = False
    if typed_direct_object and not typed_direct_object.startswith("other:"):
        typed_accusative, typed_contract = (
            _relation_patient_grammatical_shape(
                projection,
                action_start,
                action_end,
                direct_object=typed_direct_object,
                event=event,
            )
        )
        typed_accusative = bool(
            typed_accusative
            and not typed_contract.startswith("unresolved:")
        )
    if not (
        bare_consonant_patient
        or independent_neuter_patient
        or explicit_accusative_modifier
        or typed_accusative
    ):
        return None
    return (
        projection.start + object_span[0],
        projection.start + object_span[1],
    )


def _strong_modal_productive_et_active_patient_span(
    value: str,
    action: re.Match[str],
) -> tuple[int, int] | None:
    """Prove the post-predicate patient of one supplemental candidate."""

    return _strong_modal_active_patient_span(
        value,
        action_start=action.start("action"),
        action_end=action.end("action"),
        action_surface=action.group("action"),
    )


def _strong_modal_productive_et_candidate_positive_proof(
    value: str,
    action: re.Match[str],
) -> tuple[int, int] | None:
    """Prove a missing ``-ет/-ёт`` action from positive syntax evidence.

    A lexical blacklist cannot make the productive suffix safe: an unseen
    noun such as ``макет`` or ``буклет`` would immediately bypass it.  Admit
    this narrow recall path only when the bounded clause independently proves
    a nominative subject *and* a post-predicate active patient whose
    accusative morphology is not genitive-ambiguous.  The finite claim remains
    exact unless the mature relation grammar can prove more.
    """

    surface = action.group("action")
    hard_start, _hard_end = _hard_clause_bounds(
        value,
        action.start("action"),
        action.end("action"),
    )
    prefix = value[hard_start:action.start("action")]
    subject = _relation_bounded_subject_proof_before_predicate(
        prefix,
        surface,
        require_owned_prefix=True,
    )
    if subject is None:
        return None
    return _strong_modal_productive_et_active_patient_span(value, action)


def _strong_modal_semantic_finite_candidate_is_eligible(
    action: re.Match[str],
    *,
    irregular: bool,
) -> bool:
    """Apply one eligibility contract to emitted and competing predicates."""

    surface = action.group(0)
    if (
        _STRONG_MODAL_GENITIVE_GOVERNED_HOMOGRAPH_RE.fullmatch(surface)
        is not None
        and _STRONG_MODAL_GENITIVE_GOVERNING_HEAD_RE.search(
            action.string[:action.start()]
        )
        is not None
    ):
        return False
    return bool(
        _relation_bounded_predicate_is_finite(
            action,
            irregular=irregular,
        )
        and _INFINITIVE_ACTION_RE.fullmatch(surface) is None
        and _GENERIC_MODAL_RE.fullmatch(surface) is None
        and _RELATION_MODAL_TOKEN_RE.fullmatch(surface) is None
        and _GENERIC_MODAL_TENSE_AUX_RE.fullmatch(surface) is None
        and _RELATION_SEPARATOR_PASSIVE_AUXILIARY_RE.fullmatch(surface)
        is None
        and _RELATION_SEPARATOR_PAST_PASSIVE_GOVERNOR_RE.fullmatch(surface)
        is None
        and _STRONG_MODAL_NON_ACTION_FINITE_RE.fullmatch(surface) is None
    )


def _strong_modal_tight_coordination_bridge(
    between: str,
) -> tuple[str, str] | None:
    """Return one tight AND/OR bridge and its owned left-role prefix."""

    scan = _relation_delimited_scan(between)
    if scan.malformed or re.search(r"[;.!?\r\n]", scan.masked) is not None:
        return None
    bridge = _relation_action_bridge_span(scan.masked)
    if bridge is None or bridge[0] not in {"conjunctive", "alternative"}:
        return None
    connector = " ".join(
        scan.masked[bridge[1]:bridge[2]].casefold().split()
    )
    if (
        re.fullmatch(r"(?:и|или|либо|и\s*/\s*или|а\s+также)", connector)
        is None
        or scan.masked[bridge[2]:].strip(" \t")
    ):
        return None
    left_prefix = between[:bridge[1]]
    commas = tuple(re.finditer(",", left_prefix))
    if not commas:
        return bridge[0], left_prefix
    if (
        len(commas) != 1
        or connector not in {"и", "а также"}
        or left_prefix[commas[0].end():].strip(" \t")
    ):
        return None
    # One presentation comma may precede a same-subject connector.  Remove
    # only that punctuation from the returned left-role prefix; callers still
    # have to prove that the remaining prefix is empty or one anchor-owned
    # patient.  A new explicit subject after the connector therefore cannot be
    # inherited accidentally.
    return bridge[0], left_prefix[:commas[0].start()]


def _strong_modal_action_slot_bridge(
    between: str,
) -> tuple[str, tuple[int, int], tuple[int, int]] | None:
    """Split one typed action bridge into bounded left and right roles.

    Unlike tight coordination, this parser deliberately retains the complete
    connector taxonomy.  It does not infer a shared actor or patient: callers
    must type the material on both sides independently.  The returned spans
    are local to ``between`` and exclude presentation whitespace and, on the
    left, at most one comma immediately before the connector.
    """

    scan = _relation_delimited_scan(between)
    if (
        scan.malformed
        or scan.spans
        or re.search(r"[;:.!?\r\n]", scan.masked) is not None
    ):
        return None
    bridge = _relation_action_bridge_span(scan.masked)
    if bridge is None or bridge[0] not in {
        "conjunctive",
        "alternative",
        "sequence",
        "contrast",
        "continuation",
    }:
        return None
    kind, bridge_start, bridge_end = bridge
    left_surface = scan.masked[:bridge_start]
    commas = tuple(re.finditer(",", left_surface))
    if commas:
        comma = commas[-1]
        if (
            len(commas) != 1
            or left_surface[comma.end():].strip(" \t")
        ):
            return None
        left_limit = comma.start()
    else:
        left_limit = len(left_surface)
    right_surface = scan.masked[bridge_end:]
    if "," in right_surface:
        return None

    left_start = len(left_surface[:left_limit]) - len(
        left_surface[:left_limit].lstrip(" \t")
    )
    left_end = len(left_surface[:left_limit].rstrip(" \t"))
    right_start = bridge_end + (
        len(right_surface) - len(right_surface.lstrip(" \t"))
    )
    right_end = bridge_end + len(right_surface.rstrip(" \t"))
    return kind, (left_start, left_end), (right_start, right_end)


def _strong_modal_action_slot_modifiers_supported(value: str) -> bool:
    """Prove an empty or fully consumed bounded action-modifier role."""

    if not value.strip(" \t"):
        return True
    scan = _relation_delimited_scan(value)
    if (
        scan.malformed
        or scan.spans
        or re.search(r"[,;:.!?\r\n]", scan.masked) is not None
    ):
        return False
    masked = _relation_mask_equal_length(
        scan.masked,
        (
            _RELATION_NEUTRAL_PRE_PREDICATE_ADVERB_RE,
            _RELATION_ACTION_MODIFIER_RE,
            _RELATION_ACTION_UNKNOWN_ADVERB_RE,
        ),
    )
    return not masked.strip(" \t")


def _strong_modal_action_slot_single_modifier_supported(value: str) -> bool:
    """Prove exactly one known or productively-shaped modifier token."""

    scan = _relation_delimited_scan(value)
    if (
        scan.malformed
        or scan.spans
        or re.search(r"[,;:.!?\r\n]", scan.masked) is not None
    ):
        return False
    surface = scan.masked.strip(" \t")
    return bool(
        surface
        and any(
            pattern.fullmatch(surface) is not None
            for pattern in (
                _RELATION_NEUTRAL_PRE_PREDICATE_ADVERB_RE,
                _RELATION_ACTION_MODIFIER_RE,
                _RELATION_ACTION_UNKNOWN_ADVERB_RE,
            )
        )
    )


def _strong_modal_action_slot_adjacent_modifier_supported(
    value: str,
    *,
    trailing: bool,
) -> bool:
    """Prove one modifier physically adjacent to the action slot.

    The postposed patient proof types only the constituent standing next to the
    action and leaves the rest of the hard clause alone.  Modifier evidence is
    read the same way here, so a preposed chain is not weaker evidence than a
    postposed one merely because more material stands further from the action.
    Bounded modifiers span at most two words (``сразу же``, ``ещё раз``), so
    only the adjacent one- and two-word constituents are typed; nothing beyond
    them can reach the action through this proof.
    """

    words = tuple(
        re.finditer(r"[а-яёa-z][а-яёa-z-]*", value, re.IGNORECASE)
    )
    if not words:
        return False
    if trailing:
        slots = tuple(value[:word.end()] for word in words[:2])
    else:
        slots = tuple(
            value[word.start():] for word in reversed(words[-2:])
        )
    return any(
        _strong_modal_action_slot_single_modifier_supported(slot)
        for slot in slots
    )


def _strong_modal_action_slot_nonpatient_roles_supported(
    value: str,
) -> bool:
    """Consume only bounded modifiers and an exact local negation token."""

    without_negation = _relation_mask_equal_length(
        value,
        (_RELATION_SEPARATOR_NEGATION_RE,),
    )
    return _strong_modal_action_slot_modifiers_supported(
        without_negation
    )


def _strong_modal_action_slot_local_subject_supported(
    value: str,
    predicate: str,
) -> bool:
    """Prove one complete local subject, with only owned action modifiers."""

    proof = _strong_modal_action_slot_subject_proof(
        value,
        predicate,
    )
    if proof is None:
        return False
    return bool(
        _strong_modal_action_slot_nonpatient_roles_supported(
            value[:proof.actor_start]
        )
        and _strong_modal_action_slot_nonpatient_roles_supported(
            value[proof.actor_end:]
        )
    )


def _strong_modal_action_slot_subject_proof(
    value: str,
    predicate: str,
) -> _RelationBoundedSubjectProof | None:
    """Prove and protect one actor before classifying surrounding roles.

    Productive adverb morphology also matches valid actor heads such as
    ``бюро`` and ``лицо``.  Therefore this helper never masks unknown adverbs
    over the whole prefix.  It proves an actor span first, then consumes only
    the material physically outside that protected span as modifiers/local
    polarity or one bounded SOV patient.
    """

    def trailing_roles_supported(surface: str) -> bool:
        """Consume modifiers/negation plus at most one complete SOV patient."""

        if _strong_modal_action_slot_nonpatient_roles_supported(surface):
            return True
        words = tuple(
            re.finditer(r"[а-яёa-z][а-яёa-z-]*", surface, re.IGNORECASE)
        )
        if not words or len(words) > 16:
            return False
        for left_index, left in enumerate(words):
            for right in words[left_index:]:
                patient_start = left.start()
                patient_end = right.end()
                patient_surface = surface[patient_start:patient_end]
                if not _relation_bounded_patient_expression_is_supported(
                    patient_surface
                ):
                    continue
                if (
                    _strong_modal_action_slot_nonpatient_roles_supported(
                        surface[:patient_start]
                    )
                    and _strong_modal_action_slot_nonpatient_roles_supported(
                        surface[patient_end:]
                    )
                ):
                    return True
        return False

    def complete_layout(
        proof: _RelationBoundedSubjectProof,
    ) -> bool:
        leading = value[:proof.actor_start]
        trailing = value[proof.actor_end:].strip(" \t")
        return bool(
            _strong_modal_action_slot_nonpatient_roles_supported(leading)
            and trailing_roles_supported(trailing)
        )

    direct = _relation_bounded_subject_proof_before_predicate(
        value,
        predicate,
        require_owned_prefix=True,
    )
    if direct is not None and complete_layout(direct):
        return direct

    words = tuple(
        re.finditer(r"[а-яёa-z][а-яёa-z-]*", value, re.IGNORECASE)
    )
    if not words or len(words) > 16:
        return None
    actor_candidates: list[
        tuple[int, int, _RelationBoundedSubjectProof]
    ] = []
    for left_index, left in enumerate(words):
        for right in words[left_index:]:
            actor_start = left.start()
            actor_end = right.end()
            surface = value[actor_start:actor_end]
            local = _relation_bounded_subject_proof_before_predicate(
                surface,
                predicate,
                require_owned_prefix=True,
            )
            if (
                local is None
                or surface[:local.actor_start].strip(" \t")
                or surface[local.actor_end:].strip(" \t")
            ):
                continue
            protected = _RelationBoundedSubjectProof(
                actor_start=actor_start + local.actor_start,
                actor_end=actor_start + local.actor_end,
                prefix_end=len(value),
            )
            if complete_layout(protected):
                actor_candidates.append(
                    (actor_start, actor_end, protected)
                )
    if actor_candidates:
        # Prefer the widest independently proved actor identity, then the
        # earliest one.  Outside text has already passed the role audit.
        return max(
            actor_candidates,
            key=lambda item: (
                item[1] - item[0],
                -item[0],
            ),
        )[2]
    return None


def _strong_modal_action_slot_exact_patient_supported(
    value: str,
    *,
    action_span: tuple[int, int],
    action_surface: str,
    role_span: tuple[int, int],
) -> bool:
    """Prove that one bridge-side role is exactly the anchor's patient."""

    role_start, role_end = role_span
    if role_start >= role_end:
        return False
    patient = _strong_modal_active_patient_span(
        value,
        action_start=action_span[0],
        action_end=action_span[1],
        action_surface=action_surface,
    )
    if (
        patient is None
        or not (role_start <= patient[0] < patient[1] <= role_end)
    ):
        return False
    return _relation_bounded_patient_expression_is_supported(
        value[role_start:role_end].strip(" \t")
    )


# Frozen epistemic surfaces, deliberately adverbial: a productive
# ``возможн\w*`` also matches the noun ``возможности``, so ``Суд лишает
# возможности`` would be read as a hedge.  This inventory is a closed list
# and does not carry over to an unseen particle; that limitation is the
# price of keeping the fence itself exact.
_STRONG_MODAL_ACTION_LOCAL_HEDGE_MARKER = (
    r"возможно|вероятно|предположительно|наверное|наверняка|"
    r"якобы|вроде\s+бы|будто\s+бы|"
    r"видимо|по-видимому|похоже|каж(?:ется|утся)|гипотетически|"
    r"судя\s+по\s+всему|не\s+исключено"
)
_STRONG_MODAL_ACTION_LOCAL_HEDGE_TAIL_RE = re.compile(
    r"(?:,|\s)\s*(?:"
    + _STRONG_MODAL_ACTION_LOCAL_HEDGE_MARKER
    + r")\s*$",
    re.IGNORECASE,
)
_STRONG_MODAL_ACTION_LOCAL_LEADING_LI_RE = re.compile(
    r"^\s*ли\b",
    re.IGNORECASE,
)
_STRONG_MODAL_ACTION_LOCAL_TRAILING_LI_RE = re.compile(
    r"\bли\s*$",
    re.IGNORECASE,
)


def _strong_modal_action_local_role_is_consumed(
    surface: str,
    action_surface: str,
) -> bool:
    """Accept an empty role, one exact patient, or one complete subject.

    Every branch is an existing zero-residue prover, so anything the local
    grammar cannot account for leaves the role unconsumed and the caller
    fails closed instead of declaring a non-assertion.
    """

    if not surface.strip(" \t"):
        return True
    scan = _relation_delimited_scan(surface)
    if scan.malformed:
        return False
    return bool(
        _relation_bounded_patient_expression_is_supported(
            surface.strip(" \t")
        )
        or _strong_modal_action_slot_local_subject_supported(
            surface,
            action_surface,
        )
    )


def _strong_modal_action_local_query_particle(
    prefix: str,
    tail: str,
    action_surface: str,
) -> bool:
    """Prove one ``ли`` clitic that leaves no unconsumed local residue.

    The particle is only read where it can physically attach: immediately
    after the action, immediately before it, or closing the local tail.  In
    every position both remaining sides must be consumed completely, so a
    stray ``ли`` inside an unparsed remainder proves nothing.
    """

    leading = _STRONG_MODAL_ACTION_LOCAL_LEADING_LI_RE.match(tail)
    if leading is not None:
        return bool(
            _strong_modal_action_local_role_is_consumed(
                prefix,
                action_surface,
            )
            and _strong_modal_action_local_role_is_consumed(
                tail[leading.end():],
                action_surface,
            )
        )
    closing = _STRONG_MODAL_ACTION_LOCAL_TRAILING_LI_RE.search(tail)
    if closing is not None:
        return bool(
            _strong_modal_action_local_role_is_consumed(
                prefix,
                action_surface,
            )
            and _strong_modal_action_local_role_is_consumed(
                tail[:closing.start()],
                action_surface,
            )
        )
    preceding = _STRONG_MODAL_ACTION_LOCAL_TRAILING_LI_RE.search(prefix)
    if preceding is not None:
        return bool(
            _strong_modal_action_local_role_is_consumed(
                prefix[:preceding.start()],
                action_surface,
            )
            and _strong_modal_action_local_role_is_consumed(
                tail,
                action_surface,
            )
        )
    return False


def _strong_modal_action_local_postfix_hedge(
    tail: str,
    action_surface: str,
) -> bool:
    """Read a closing epistemic marker only over a consumed local tail."""

    hedge = _STRONG_MODAL_ACTION_LOCAL_HEDGE_TAIL_RE.search(tail)
    if hedge is None:
        return False
    return _strong_modal_action_local_role_is_consumed(
        tail[:hedge.start()],
        action_surface,
    )


def _strong_modal_action_local_nonassertion(
    value: str,
    *,
    action_start: int,
    action_end: int,
    action_surface: str,
) -> bool:
    """Prove one action-local non-assertion for a productive predicate.

    The mature ``_relation_is_assertive`` audits the clause prefix and one
    comma-delimited suffix; neither sees a ``ли`` clitic sitting between the
    action and its patient, nor a closing hedge written without a comma.
    This helper is the single fence for both, shared by candidate selection
    and the occurrence digest so a span can never be selected as resolved by
    one and hashed as categorical by the other.

    It reads only the delimiter-masked hard clause around the action, and
    only the coordination-bounded action-local slice of it.  A malformed
    delimiter, a marker hidden inside a quoted identity, or any unconsumed
    patient/residue leaves the verdict at ``False``: this fence may add a
    forced-unresolved digest, never remove one.
    """

    hard_start, hard_end = _hard_clause_bounds(
        value,
        action_start,
        action_end,
    )
    if not hard_start <= action_start < action_end <= hard_end:
        return False
    clause = value[hard_start:hard_end]
    if _relation_delimited_scan(clause).malformed:
        return False
    masked = _relation_quote_syntax_surface(clause)
    local_start = action_start - hard_start
    local_end = action_end - hard_start
    left, right = _relation_action_local_role_bounds(
        masked,
        local_start,
        local_end,
    )
    if not left <= local_start < local_end <= right:
        return False
    prefix = masked[left:local_start]
    tail = masked[local_end:right]
    return bool(
        _strong_modal_action_local_postfix_hedge(tail, action_surface)
        or _strong_modal_action_local_query_particle(
            prefix,
            tail,
            action_surface,
        )
    )


def _strong_modal_semantic_finite_candidates(
    value: str,
    *,
    start: int = 0,
    end: int | None = None,
) -> tuple[tuple[re.Match[str], bool, bool], ...]:
    """Return bounded finite actions, excluding modal/copy auxiliaries.

    The productive finite regex deliberately misses common irregular Russian
    verbs (``дал``, ``взял``, ``пришёл`` and related forms).  Conversely the
    combined relation stream also contains modal governors and ``быть`` forms,
    which describe modality/tense rather than another legal action.  Keep one
    shared filter so subordinate ownership and the standalone definite guard
    see exactly the same physical predicates.
    """

    right = len(value) if end is None else end
    raw_candidates: dict[
        tuple[int, int],
        tuple[re.Match[str], bool],
    ] = {
        action.span(): (action, irregular)
        for action, irregular in _relation_bounded_predicate_candidates(value)
    }
    supplemental_actions = tuple(
        action
        for action in _STRONG_MODAL_PRODUCTIVE_ET_FINITE_RE.finditer(value)
        if action.span("action") not in raw_candidates
    )
    force_unresolved_spans: set[tuple[int, int]] = set()
    base_supplemental: dict[
        tuple[int, int],
        tuple[re.Match[str], tuple[int, int]],
    ] = {}
    for action in supplemental_actions:
        span = action.span("action")
        patient_span = _strong_modal_productive_et_candidate_positive_proof(
            value,
            action,
        )
        if patient_span is not None:
            base_supplemental[span] = (action, patient_span)

    # One non-recursive promotion resolves the bounded SOV ambiguity in
    # ``Суд предмет пишет документ``.  The first suffix candidate initially
    # mistakes ``пишет`` for its patient; the later candidate has its own
    # proved patient, while the original subject independently agrees with it.
    # A raw ``-ет/-ёт`` token is never enough by itself, so legitimate patients
    # in ``пишет предмет/билет/макет`` remain ordinary nouns.
    promoted_supplemental: dict[
        tuple[int, int],
        tuple[re.Match[str], tuple[int, int]],
    ] = {}
    for earlier_span, (_earlier, selected_patient_span) in (
        base_supplemental.items()
    ):
        hard_start, _hard_end = _hard_clause_bounds(
            value,
            earlier_span[0],
            earlier_span[1],
        )
        subject_prefix = value[hard_start:earlier_span[0]]
        for later in supplemental_actions:
            later_span = later.span("action")
            if later_span != selected_patient_span:
                continue
            later_patient_span = (
                _strong_modal_productive_et_active_patient_span(value, later)
            )
            if (
                later_patient_span is None
                or _relation_bounded_subject_proof_before_predicate(
                    subject_prefix,
                    later.group("action"),
                    require_owned_prefix=True,
                )
                is None
            ):
                continue
            promoted_supplemental[later_span] = (
                later,
                later_patient_span,
            )

    proved_supplemental = {
        **base_supplemental,
        **promoted_supplemental,
    }
    eligible_anchors: dict[
        tuple[int, int],
        tuple[re.Match[str], bool],
    ] = {
        span: (candidate, irregular)
        for span, (candidate, irregular) in raw_candidates.items()
        if _strong_modal_semantic_finite_candidate_is_eligible(
            candidate,
            irregular=irregular,
        )
    }
    eligible_anchors.update(
        {
            span: (candidate, False)
            for span, (candidate, _patient_span) in (
                proved_supplemental.items()
            )
        }
    )
    independent_supplemental: dict[
        tuple[int, int],
        tuple[re.Match[str], tuple[int, int]],
    ] = {}
    for candidate in supplemental_actions:
        candidate_span = candidate.span("action")
        if candidate_span in proved_supplemental:
            continue
        candidate_patient = _strong_modal_active_patient_span(
            value,
            action_start=candidate_span[0],
            action_end=candidate_span[1],
            action_surface=candidate.group("action"),
        )
        if candidate_patient is None:
            continue
        hard_start, hard_end = _hard_clause_bounds(
            value,
            candidate_span[0],
            candidate_span[1],
        )
        commas = tuple(
            re.finditer(",", value[hard_start:candidate_span[0]])
        )
        for comma in reversed(commas):
            comma_start = hard_start + comma.start()
            local_surface = value[comma_start + 1:candidate_span[0]]
            intro = re.match(
                r"\s*(?:(?:а|но|и)\s+)?",
                local_surface,
                re.IGNORECASE,
            )
            if intro is None:
                continue
            local_subject_prefix = local_surface[intro.end():]
            if (
                not local_subject_prefix.strip(" \t")
                or re.search(
                    r"[,;.!?\r\n]",
                    local_subject_prefix,
                )
                is not None
                or _relation_bounded_subject_proof_before_predicate(
                    local_subject_prefix,
                    candidate.group("action"),
                    require_owned_prefix=True,
                )
                is None
                or not any(
                    anchor_span[1] <= comma_start
                    and _hard_clause_bounds(
                        value,
                        anchor_span[0],
                        anchor_span[1],
                    )
                    == (hard_start, hard_end)
                    for anchor_span in eligible_anchors
                )
            ):
                continue
            independent_supplemental[candidate_span] = (
                candidate,
                candidate_patient,
            )
            break
    proved_supplemental.update(independent_supplemental)

    coordinated_supplemental: dict[
        tuple[int, int],
        tuple[re.Match[str], tuple[int, int]],
    ] = {}
    for candidate in supplemental_actions:
        candidate_span = candidate.span("action")
        if (
            candidate_span in proved_supplemental
            or not _strong_modal_semantic_finite_candidate_is_eligible(
                candidate,
                irregular=False,
            )
        ):
            continue
        candidate_hard_start, candidate_hard_end = _hard_clause_bounds(
            value,
            candidate_span[0],
            candidate_span[1],
        )
        ordered_anchors = sorted(
            eligible_anchors.items(),
            key=lambda item: min(
                abs(item[0][0] - candidate_span[1]),
                abs(candidate_span[0] - item[0][1]),
            ),
        )
        for anchor_span, (anchor, _irregular) in ordered_anchors:
            if anchor_span == candidate_span:
                continue
            anchor_hard_start, anchor_hard_end = _hard_clause_bounds(
                value,
                anchor_span[0],
                anchor_span[1],
            )
            if (
                (anchor_hard_start, anchor_hard_end)
                != (candidate_hard_start, candidate_hard_end)
                or any(
                    other_span not in {candidate_span, anchor_span}
                    and min(candidate_span[1], anchor_span[1])
                    <= other_span[0]
                    < max(candidate_span[0], anchor_span[0])
                    for other_span in eligible_anchors
                )
            ):
                continue
            first_start = min(candidate_span[0], anchor_span[0])
            subject_prefix = value[candidate_hard_start:first_start]
            if (
                _relation_bounded_subject_proof_before_predicate(
                    subject_prefix,
                    candidate.group("action"),
                    require_owned_prefix=True,
                )
                is None
            ):
                continue
            if candidate_span[0] < anchor_span[0]:
                between = value[candidate_span[1]:anchor_span[0]]
                bridge = _strong_modal_tight_coordination_bridge(between)
                if bridge is None or bridge[1].strip(" \t"):
                    continue
                inherited_patient = _strong_modal_active_patient_span(
                    value,
                    action_start=anchor_span[0],
                    action_end=anchor_span[1],
                    action_surface=anchor.group(0),
                )
                if inherited_patient is None:
                    continue
                coordinated_supplemental[candidate_span] = (
                    candidate,
                    inherited_patient,
                )
                break

            between = value[anchor_span[1]:candidate_span[0]]
            bridge = _strong_modal_tight_coordination_bridge(between)
            if bridge is None:
                continue
            candidate_patient = _strong_modal_active_patient_span(
                value,
                action_start=candidate_span[0],
                action_end=candidate_span[1],
                action_surface=candidate.group("action"),
            )
            if candidate_patient is None:
                continue
            anchor_patient_prefix = bridge[1]
            if anchor_patient_prefix.strip(" \t"):
                anchor_patient = _strong_modal_active_patient_span(
                    value,
                    action_start=anchor_span[0],
                    action_end=anchor_span[1],
                    action_surface=anchor.group(0),
                )
                bridge_absolute_start = (
                    anchor_span[1] + len(anchor_patient_prefix)
                )
                if (
                    anchor_patient is None
                    or not (
                        anchor_span[1] <= anchor_patient[0]
                        and anchor_patient[1] <= bridge_absolute_start
                    )
                ):
                    continue
            coordinated_supplemental[candidate_span] = (
                candidate,
                candidate_patient,
            )
            break

    proved_supplemental.update(coordinated_supplemental)

    # Keep the mature patient-bearing and tight-coordination paths above
    # canonical.  Only their remaining productive ``-ет/-ёт`` ambiguities
    # enter this strict fallback.  Every accepted occurrence below is emitted
    # with a full hard-clause digest; none of these bridges lends an actor or a
    # patient to the supplemental predicate.
    strict_slot_supplemental: dict[
        tuple[int, int],
        tuple[re.Match[str], tuple[int, int]],
    ] = {}
    strict_anchors = dict(eligible_anchors)
    strict_anchors.update(
        {
            span: (candidate, False)
            for span, (candidate, _patient_span) in (
                proved_supplemental.items()
            )
        }
    )
    for candidate in supplemental_actions:
        candidate_span = candidate.span("action")
        if (
            candidate_span in proved_supplemental
            or not _strong_modal_semantic_finite_candidate_is_eligible(
                candidate,
                irregular=False,
            )
        ):
            continue
        hard_start, hard_end = _hard_clause_bounds(
            value,
            candidate_span[0],
            candidate_span[1],
        )
        structural_proof = False
        ordered_anchors = sorted(
            strict_anchors.items(),
            key=lambda item: min(
                abs(item[0][0] - candidate_span[1]),
                abs(candidate_span[0] - item[0][1]),
            ),
        )
        for anchor_span, (anchor, _irregular) in ordered_anchors:
            if (
                anchor_span == candidate_span
                or _hard_clause_bounds(
                    value,
                    anchor_span[0],
                    anchor_span[1],
                )
                != (hard_start, hard_end)
                or any(
                    other_span not in {candidate_span, anchor_span}
                    and min(candidate_span[0], anchor_span[0])
                    < other_span[0]
                    < max(candidate_span[0], anchor_span[0])
                    for other_span in strict_anchors
                )
            ):
                continue
            if candidate_span[0] < anchor_span[0]:
                gap_start = candidate_span[1]
                gap_end = anchor_span[0]
                first_span = candidate_span
                first_surface = candidate.group("action")
            else:
                gap_start = anchor_span[1]
                gap_end = candidate_span[0]
                first_span = anchor_span
                first_surface = anchor.group(0)
            bridge = _strong_modal_action_slot_bridge(
                value[gap_start:gap_end]
            )
            if bridge is None:
                continue
            _kind, left_local, right_local = bridge
            left_span = (
                gap_start + left_local[0],
                gap_start + left_local[1],
            )
            right_span = (
                gap_start + right_local[0],
                gap_start + right_local[1],
            )
            left_surface = value[left_span[0]:left_span[1]]
            right_surface = value[right_span[0]:right_span[1]]
            first_prefix = value[hard_start:first_span[0]]
            shared_subject = _strong_modal_action_slot_subject_proof(
                first_prefix,
                first_surface,
            )
            shared_sov_patient = bool(
                shared_subject is not None
                and _relation_bounded_patient_expression_is_supported(
                    first_prefix[shared_subject.actor_end:].strip(" \t")
                )
            )

            if candidate_span[0] < anchor_span[0]:
                candidate_subject = (
                    _strong_modal_action_slot_subject_proof(
                        value[hard_start:candidate_span[0]],
                        candidate.group("action"),
                    )
                )
                if candidate_subject is None:
                    continue
                left_supported = bool(
                    not left_surface.strip(" \t")
                    or _strong_modal_action_slot_exact_patient_supported(
                        value,
                        action_span=candidate_span,
                        action_surface=candidate.group("action"),
                        role_span=left_span,
                    )
                )
                if not left_supported:
                    continue
                local_anchor_subject = (
                    _strong_modal_action_slot_local_subject_supported(
                        right_surface,
                        anchor.group(0),
                    )
                )
                shared_anchor_subject = (
                    _strong_modal_action_slot_modifiers_supported(
                        right_surface
                    )
                )
                anchor_patient = _strong_modal_active_patient_span(
                    value,
                    action_start=anchor_span[0],
                    action_end=anchor_span[1],
                    action_surface=anchor.group(0),
                )
                if local_anchor_subject:
                    structural_proof = anchor_patient is not None
                elif shared_anchor_subject:
                    structural_proof = bool(
                        anchor_patient is not None or shared_sov_patient
                    )
                if structural_proof:
                    break
                continue

            exact_anchor_patient = (
                _strong_modal_action_slot_exact_patient_supported(
                    value,
                    action_span=anchor_span,
                    action_surface=anchor.group(0),
                    role_span=left_span,
                )
            )
            local_candidate_subject = (
                _strong_modal_action_slot_local_subject_supported(
                    right_surface,
                    candidate.group("action"),
                )
            )
            shared_candidate_subject = (
                _strong_modal_action_slot_modifiers_supported(
                    right_surface
                )
            )
            if local_candidate_subject:
                # A connector-local subject is independent.  Requiring the
                # exact left anchor patient prevents either physical actor or
                # either action's object from crossing the bridge.
                structural_proof = exact_anchor_patient
            elif shared_candidate_subject and shared_subject is not None:
                structural_proof = bool(
                    exact_anchor_patient or shared_sov_patient
                )
            if structural_proof:
                break

        if not structural_proof:
            subject_prefix = value[hard_start:candidate_span[0]]
            incomplete_tail = value[
                candidate_span[1]:hard_end
            ].strip(" \t,;:\u2014\u2013-")
            structural_proof = bool(
                _strong_modal_action_slot_subject_proof(
                    subject_prefix,
                    candidate.group("action"),
                )
                and _strong_modal_action_slot_modifiers_supported(
                    incomplete_tail
                )
            )
        if not structural_proof:
            # A separately shaped post-predicate patient is sufficient to
            # retain an orphan occurrence after its actor was dropped.  It is
            # still strict/unresolved and therefore cannot invent an actor.
            structural_proof = bool(
                _strong_modal_active_patient_span(
                    value,
                    action_start=candidate_span[0],
                    action_end=candidate_span[1],
                    action_surface=candidate.group("action"),
                )
            )
        if not structural_proof:
            # Exact local polarity is enough syntax evidence to retain an
            # otherwise actorless productive occurrence.  This is still a
            # forced full-clause claim; it never invents the missing actor.
            prefix_role = value[hard_start:candidate_span[0]]
            trailing_role = value[
                candidate_span[1]:hard_end
            ].strip(" \t,;:\u2014\u2013-")
            structural_proof = bool(
                _RELATION_SEPARATOR_NEGATION_RE.search(prefix_role)
                and _strong_modal_action_slot_nonpatient_roles_supported(
                    prefix_role
                )
                and _strong_modal_action_slot_modifiers_supported(
                    trailing_role
                )
            )
        if not structural_proof:
            # Object-first and actor-last orders need independent nominative
            # evidence after the action.  Strip only presentation punctuation
            # before proving the complete actor; quoted/parenthesized tails do
            # not become actors through this path.
            prefix_role = value[hard_start:candidate_span[0]]
            postposed_surface = value[
                candidate_span[1]:hard_end
            ].strip(" \t,;:\u2014\u2013-")
            structural_proof = bool(
                postposed_surface
                and _strong_modal_action_slot_nonpatient_roles_supported(
                    prefix_role
                )
                and _strong_modal_action_slot_local_subject_supported(
                    postposed_surface,
                    candidate.group("action"),
                )
            )
        if not structural_proof:
            # Only after both preposed and postposed actor proofs have failed,
            # one adjacent modifier is sufficient syntax for a strict raw
            # occurrence.  The postposed patient proof above types only the
            # constituent standing next to the action, which is why a preposed
            # chain used to be the single shape that lost its occurrence; the
            # same adjacency is read on both sides here, and the opposite side
            # is typed by the bounded-modifier helper the postposed actor proof
            # already applies to its own non-proving side.  The productive
            # ``-о/-ски`` branch stays conservative: noun-shaped collisions
            # may be false-blocked, but can never be emitted as an
            # unqualified fact.
            prefix_modifier = value[
                hard_start:candidate_span[0]
            ].strip(" \t")
            trailing_modifier = value[
                candidate_span[1]:hard_end
            ].strip(" \t,;:\u2014\u2013-")
            structural_proof = bool(
                (
                    _strong_modal_action_slot_adjacent_modifier_supported(
                        prefix_modifier,
                        trailing=False,
                    )
                    and _strong_modal_action_slot_modifiers_supported(
                        trailing_modifier
                    )
                )
                or (
                    _strong_modal_action_slot_adjacent_modifier_supported(
                        trailing_modifier,
                        trailing=True,
                    )
                    and _strong_modal_action_slot_modifiers_supported(
                        prefix_modifier
                    )
                )
            )
        if not structural_proof:
            # Preserve the existing comma-only independent-clause layout,
            # but retain its incomplete predicate as a strict occurrence.
            for comma in reversed(
                tuple(
                    re.finditer(",", value[hard_start:candidate_span[0]])
                )
            ):
                comma_start = hard_start + comma.start()
                local_surface = value[comma_start + 1:candidate_span[0]]
                if (
                    _relation_action_bridge_span(local_surface) is None
                    and _strong_modal_action_slot_local_subject_supported(
                        local_surface,
                        candidate.group("action"),
                    )
                    and any(
                        anchor_span[1] <= comma_start
                        and _hard_clause_bounds(
                            value,
                            anchor_span[0],
                            anchor_span[1],
                        )
                        == (hard_start, hard_end)
                        for anchor_span in strict_anchors
                    )
                ):
                    structural_proof = True
                    break
        if not structural_proof:
            continue
        strict_slot_supplemental[candidate_span] = (
            candidate,
            candidate_span,
        )

    proved_supplemental.update(strict_slot_supplemental)
    force_unresolved_spans.update(strict_slot_supplemental)
    competing_finite_spans = {
        span
        for span, (candidate, irregular) in raw_candidates.items()
        if _strong_modal_semantic_finite_candidate_is_eligible(
            candidate,
            irregular=irregular,
        )
    } | set(proved_supplemental)
    for span, (action, _patient_span) in proved_supplemental.items():
        _hard_start, hard_end = _hard_clause_bounds(
            value,
            span[0],
            span[1],
        )
        tail = value[span[1]:hard_end]
        connector = re.search(
            r"[,;]|\b(?:и|или|либо|а|но)\b",
            tail,
            re.IGNORECASE,
        )
        owned_tail_end = span[1] + (
            connector.start() if connector is not None else len(tail)
        )
        if any(
            other_span != span
            and span[1] <= other_span[0] < owned_tail_end
            for other_span in competing_finite_spans
        ):
            continue
        raw_candidates[span] = (action, False)

    candidates: list[tuple[re.Match[str], bool, bool]] = []
    for key in sorted(raw_candidates):
        action, irregular = raw_candidates[key]
        action_start, action_end = action.span()
        if action_start < start or action_end > right:
            continue
        if not _strong_modal_semantic_finite_candidate_is_eligible(
            action,
            irregular=irregular,
        ):
            continue
        candidates.append(
            (
                action,
                irregular,
                key in force_unresolved_spans
                or _strong_modal_action_local_nonassertion(
                    value,
                    action_start=action_start,
                    action_end=action_end,
                    action_surface=action.group(0),
                ),
            )
        )
    return tuple(candidates)


def _strong_modal_independent_clause_after_comma(
    value: str,
    *,
    comma_end: int,
    hard_end: int,
) -> tuple[str, bool] | None:
    """Prove a new explicit subject/predicate after one comma.

    The returned connector and modal flag let the caller distinguish the main
    clause after a leading subordinate from an ordinary coordinated predicate
    that remains inside that subordinate.  A bare conjunction without its own
    proved subject never opens a new factual branch.
    """

    suffix = value[comma_end:hard_end]
    connector_match = re.match(
        r"\s*(?:(?P<connector>а|но|и)\s+)?",
        suffix,
        re.IGNORECASE,
    )
    if connector_match is None:
        return None
    connector = (connector_match.group("connector") or "").casefold()
    body_start = comma_end + connector_match.end()
    predicate_candidates: list[tuple[int, int, str, bool]] = []
    modal = _GENERIC_MODAL_RE.search(value, body_start, hard_end)
    if modal is not None:
        predicate_candidates.append(
            (modal.start(), modal.end(), modal.group("modal"), True)
        )
    for finite, _irregular, _force_unresolved in (
        _strong_modal_semantic_finite_candidates(
        value,
        start=body_start,
        end=hard_end,
        )
    ):
        finite_start, finite_end = finite.span()
        predicate_candidates.append(
            (finite_start, finite_end, finite.group(0), False)
        )
    if not predicate_candidates:
        return None
    predicate_start, _predicate_end, predicate, is_modal = min(
        predicate_candidates,
        key=lambda item: item[0],
    )
    prefix = value[body_start:predicate_start]
    if _relation_bounded_subject_proof_before_predicate(
        prefix,
        predicate,
        require_owned_prefix=True,
    ) is None:
        return None
    return connector, is_modal


# One structural proof that a scope marker owns an action.
#
# The scan below reads "a marker stands somewhere to the left of this action"
# as "this marker governs this action".  A wrapper is only one way to abuse
# that reading.  ``Организация {Чтобы} пишет арест`` writes the marker inside
# a bracket the delimiter contract has never heard of; ``Организация {Чтобы
# пишет арест`` leaves that bracket unclosed; an output can invent the whole
# bracket over a source that never had one; and ``Организация Чтобы пишет
# арест`` needs no bracket at all.  Every one of them wins by the same route,
# so widening the inventory of bracket shapes only ever removes one at a time.
#
# Ownership is therefore proved rather than assumed, and the proof holds no
# inventory of wrappers.  It is read off the shared delimiter surface - where
# a *balanced* wrapper of the proven contract is already blank - and asks
# three structural questions:
#
#   * does the marker reach the action without crossing anything?  Only
#     clause-internal material - letters, digits, in-line whitespace, commas
#     and word-internal hyphens or apostrophes - may lie between them.  Any
#     other glyph is a boundary of some kind, whatever shape it takes, and an
#     unbalanced or unknown bracket leaves its glyphs on that path;
#   * does the marker head its own unit?  The same clause-internal test is
#     applied to the text from the clause start (or the nearest separator) to
#     the marker, so residue of a bracket the contract could not close keeps
#     the marker from heading anything;
#   * is the marker outside somebody else's predication?  When the action's
#     own subject is proved to stand to the LEFT of the marker, the marker was
#     inserted into a finished clause instead of opening a branch, and a
#     separator glued in front of it does not change that.
#
# Failing any of the three leaves ownership unproven, so the action stays an
# ordinary claim that has to be proved on its own evidence - fail-closed.
_STRONG_MODAL_OWNERSHIP_INLINE_SPACE = "[^\\S\\r\\n\\v\\f\\u2028\\u2029]"
_STRONG_MODAL_OWNERSHIP_PATH_RE = re.compile(
    "(?:[^\\W_]|"
    + _STRONG_MODAL_OWNERSHIP_INLINE_SPACE
    + "|,|(?<=[^\\W_])['\\-\\u2019\\u02bc](?=[^\\W_]))*",
)
_STRONG_MODAL_OWNERSHIP_HEAD_RE = re.compile(
    "(?:"
    + _STRONG_MODAL_OWNERSHIP_INLINE_SPACE
    + ")*(?:(?:и|а|но|или|либо)(?:"
    + _STRONG_MODAL_OWNERSHIP_INLINE_SPACE
    + ")+)?",
    re.IGNORECASE,
)
_STRONG_MODAL_OWNERSHIP_HEAD_ANCHORS = ",;:—–"


def _strong_modal_marker_scope_is_proved(
    surface: str,
    *,
    clause_start: int,
    marker_start: int,
    marker_end: int,
    action_start: int,
    action_surface: str,
) -> bool:
    """Return true only when the marker provably governs the action."""

    if not clause_start <= marker_start < marker_end <= action_start:
        return False
    if _STRONG_MODAL_OWNERSHIP_PATH_RE.fullmatch(
        surface[marker_end:action_start]
    ) is None:
        return False
    head = surface[clause_start:marker_start]
    anchor = max(
        (
            head.rfind(character)
            for character in _STRONG_MODAL_OWNERSHIP_HEAD_ANCHORS
        ),
        default=-1,
    )
    if _STRONG_MODAL_OWNERSHIP_HEAD_RE.fullmatch(head[anchor + 1:]) is None:
        return False
    return _relation_bounded_subject_proof_before_predicate(
        head,
        action_surface,
        require_owned_prefix=True,
    ) is None


def _strong_modal_subordinate_finite_spans(
    value: str,
) -> frozenset[tuple[int, int]]:
    """Own every finite predicate inside a purpose/condition branch.

    ``_relation_is_assertive`` is intentionally broad and does not by itself
    turn ``чтобы суд уничтожил`` or ``если суд уничтожил`` into a
    non-assertion.  Without a physical branch fence the first (or a later
    coordinated) subordinate verb becomes an invented standalone fact.  Bound
    the complete branch before projecting arbitrary definite claims, whether
    the subordinate appears before or after a modal/main clause.

    Markers are read off the shared delimiter mask instead of the raw text: a
    ``«Чтобы»`` written as the name of an organization is an identity, not a
    branch, and must not take the following predicate out of the audit.  A
    malformed wrapper proves no branch at all, so the fence switches off and
    every predicate stays a claim that has to be proved.

    Reading the mask only covers the delimiters that contract can prove.  All
    the remaining ways of putting a marker where it does not belong - a
    bracket shape outside the contract, an unclosed one, a marker the output
    invented, a separator glued in front of one, or no bracket at all - are
    refused by the single structural ownership proof above instead of by a
    wider inventory of glyphs.
    """

    syntax = _strong_modal_wrapper_syntax(value)
    if syntax.malformed:
        return frozenset()
    owned: set[tuple[int, int]] = set()
    for marker in _GENERIC_MODAL_SUBORDINATE_RE.finditer(syntax.surface):
        hard_start, hard_end = _hard_clause_bounds(
            value,
            marker.start(),
            marker.end(),
        )
        leading_surface = value[hard_start:marker.start()]
        leading_subordinate = re.fullmatch(
            r"[\s,:\u2014\u2013-]*(?:и\s+)?",
            leading_surface,
            re.IGNORECASE,
        ) is not None
        branch_end = hard_end
        for comma in _RELATION_SEPARATOR_COMMA_RE.finditer(
            value,
            marker.end(),
            hard_end,
        ):
            branch = _strong_modal_independent_clause_after_comma(
                value,
                comma_end=comma.end(),
                hard_end=hard_end,
            )
            if branch is None:
                continue
            connector, is_modal = branch
            if (
                leading_subordinate
                and not connector
                or connector == "но"
                or is_modal and connector in {"а", "но"}
            ):
                branch_end = comma.start()
                break
        for finite, _irregular, _force_unresolved in (
            _strong_modal_semantic_finite_candidates(
            value,
            start=marker.end(),
            end=branch_end,
            )
        ):
            if not _strong_modal_marker_scope_is_proved(
                syntax.surface,
                clause_start=hard_start,
                marker_start=marker.start(),
                marker_end=marker.end(),
                action_start=finite.start(),
                action_surface=finite.group(0),
            ):
                continue
            owned.add(finite.span())
    return frozenset(owned)


def _extract_strong_modal_family_claims(
    value: str,
) -> set[_QualitativeClaim]:
    """Keep explicit right/duty/fact modality exact for every predicate."""

    claims: set[_QualitativeClaim] = set()
    modal_owned_predicate_spans: set[tuple[int, int]] = set()
    subordinate_finite_spans = _strong_modal_subordinate_finite_spans(value)
    for modal in _GENERIC_MODAL_RE.finditer(value):
        modal_owned_predicate_spans.add((modal.start(), modal.end()))
        hard_start, hard_end = _hard_clause_bounds(
            value,
            modal.start(),
            modal.end(),
        )
        clause = value[hard_start:hard_end]
        if "?" in clause:
            continue
        modality = (
            "may"
            if _GENERIC_MODAL_MAY_RE.fullmatch(modal.group("modal")) is not None
            else "mandatory"
        )
        prefix = value[hard_start:modal.start()]
        modal_negated = re.search(
            r"\bне\s*$",
            prefix,
            re.IGNORECASE,
        ) is not None
        prohibited = (
            _GENERIC_MODAL_PROHIBITION_RE.fullmatch(modal.group("modal"))
            is not None
        )
        governed_end = _strong_modal_governed_end(
            value,
            modal_end=modal.end(),
            hard_end=hard_end,
        )
        governed = value[modal.end():governed_end]
        actions = list(_INFINITIVE_ACTION_RE.finditer(governed))
        selected: list[re.Match[str]] = []
        for action in actions:
            if not selected:
                selected.append(action)
                continue
            previous = selected[-1]
            between = governed[
                previous.end("action"):action.start("action")
            ]
            if (
                _GENERIC_MODAL_SUBORDINATE_RE.search(between) is not None
                or _relation_action_bridge_span(between) is None
            ):
                break
            selected.append(action)
        relative_actions = bool(selected)
        if not selected:
            preceding = tuple(
                _INFINITIVE_ACTION_RE.finditer(
                    value,
                    hard_start,
                    modal.start(),
                )
            )
            if preceding:
                selected.append(preceding[-1])

        pre_action_surface = (
            governed[:selected[0].start("action")]
            if selected and relative_actions
            else ""
        )
        tense = _strong_modal_tense_qualifier(
            modal.group("modal"),
            pre_action_surface,
        )
        tense_auxiliary_qualifiers = (
            _strong_modal_tense_auxiliary_qualifiers(
                pre_action_surface,
                modal_surface=modal.group("modal"),
            )
        )
        if (
            selected
            and selected[0].group("action").casefold().replace("ё", "е")
            == "быть"
        ):
            passive_governed = governed
            governed_actors = tuple(
                phrase
                for phrase in _relation_complete_passive_actor_phrases(
                    governed
                )
                if not phrase.key.startswith(
                    _RELATION_UNRESOLVED_ACTOR_PREFIX
                )
            )
            if len(governed_actors) == 1:
                actor = governed_actors[0]
                passive_governed = (
                    governed[:actor.start]
                    + " " * (actor.end - actor.start)
                    + governed[actor.end:]
                )
            passive = _GENERIC_MODAL_PASSIVE_RE.match(passive_governed)
            if passive is not None:
                predicate = _canonical_strong_modal_passive_predicate(
                    passive.group("participle")
                )
                action_start = modal.end() + passive.start("participle")
                action_end = modal.end() + passive.end("participle")
                modal_owned_predicate_spans.add((action_start, action_end))
                if (
                    predicate
                    and _strong_modal_predicate_is_relation_owned(
                        passive.group("participle"),
                        predicate,
                    )
                    and _strong_modal_mature_action_is_coherent(
                        value,
                        action_start=action_start,
                        action_end=action_end,
                        modal_surface=modal.group("modal"),
                        analytic_passive=True,
                    )
                ):
                    claims.add(
                        _strong_modal_family_claim(
                            predicate=predicate,
                            polarity=(
                                "negative"
                                if modal_negated
                                or prohibited
                                or passive.group("action_negated")
                                else "positive"
                            ),
                            modality=modality,
                            tense=tense,
                            scope=frozenset(
                                {
                                    qualifier
                                    for enabled, qualifier in (
                                        (
                                            modal_negated,
                                            "modal_scope:negated_modal",
                                        ),
                                        (
                                            bool(passive.group("action_negated")),
                                            "modal_scope:negated_action",
                                        ),
                                        (
                                            prohibited,
                                            "modal_scope:prohibited",
                                        ),
                                    )
                                    if enabled
                                }
                            )
                            | tense_auxiliary_qualifiers
                            | frozenset(
                                {
                                    _strong_modal_complete_occurrence_qualifier(
                                        value,
                                        action_start=action_start,
                                        action_end=action_end,
                                        modality=modality,
                                    )
                                }
                            ),
                        )
                    )
            continue
        for action_index, action in enumerate(selected):
            action_start = (
                modal.end() + action.start("action")
                if relative_actions
                else action.start("action")
            )
            action_end = (
                modal.end() + action.end("action")
                if relative_actions
                else action.end("action")
            )
            modal_owned_predicate_spans.add((action_start, action_end))
            projection = _predicate_relation(value, action_start, action_end)
            if not _relation_is_assertive(
                value,
                projection,
                action_start,
                action_end,
            ):
                continue
            local_prefix = (
                governed[
                    (
                        selected[action_index - 1].end("action")
                        if action_index
                        else 0
                    ):action.start("action")
                ]
                if relative_actions
                else value[hard_start:action_start]
            )
            action_negated = re.search(
                r"\bне\s*$",
                local_prefix,
                re.IGNORECASE,
            ) is not None
            action_surface = value[action_start:action_end]
            predicate = _canonical_mandatory_predicate(action_surface)
            if not (
                _strong_modal_predicate_is_relation_owned(
                    action_surface,
                    predicate.removesuffix(":reflexive"),
                )
                and _strong_modal_mature_action_is_coherent(
                    value,
                    action_start=action_start,
                    action_end=action_end,
                    modal_surface=modal.group("modal"),
                )
            ):
                continue
            claims.add(
                _strong_modal_family_claim(
                    predicate=predicate,
                    polarity=(
                        "negative"
                        if modal_negated or prohibited or action_negated
                        else "positive"
                    ),
                    modality=modality,
                    tense=tense,
                    scope=frozenset(
                        {
                            qualifier
                            for enabled, qualifier in (
                                (
                                    modal_negated,
                                    "modal_scope:negated_modal",
                                ),
                                (
                                    action_negated,
                                    "modal_scope:negated_action",
                                ),
                                (
                                    prohibited,
                                    "modal_scope:prohibited",
                                ),
                            )
                            if enabled
                        }
                    )
                    | tense_auxiliary_qualifiers
                    | frozenset(
                        {
                            _strong_modal_complete_occurrence_qualifier(
                                value,
                                action_start=action_start,
                                action_end=action_end,
                                modality=modality,
                            )
                        }
                    ),
                )
            )

    for action, irregular, force_unresolved in (
        _strong_modal_semantic_finite_candidates(value)
    ):
        action_start, action_end = action.span()
        hard_start, hard_end = _hard_clause_bounds(
            value,
            action_start,
            action_end,
        )
        # A non-assertion is not a reason to stop checking.  Dropping the
        # claim is conservative for a source (fewer proved facts) but
        # fail-open for an *output*: zero extracted claims mean there is
        # nothing left to compare, so one leading ``Возможно,`` used to
        # launder an arbitrary recombination.  The epistemic frame is
        # therefore blanked with same-length masks, the clause is read by the
        # ordinary assertive contracts, and each frame surface is carried as
        # its own scope atom below.
        epistemic = _relation_epistemic_frame(value, action_start, action_end)
        framed = value if epistemic is None else epistemic[0]
        opening = _relation_discourse_opening(framed, action_start, action_end)
        # A proven discourse opening is read as what it is: an optional
        # preamble.  The clause is then parsed on the masked surface by the
        # ordinary assertive contracts instead of being replaced by a verbatim
        # clause digest, and the opening itself is carried as its own scope
        # atom below so it can neither be invented nor dropped silently.
        reading = framed if opening is None else opening[0]
        if (
            any(
                owned_start < action_end and action_start < owned_end
                for owned_start, owned_end in modal_owned_predicate_spans
            )
            or (action_start, action_end) in (
                subordinate_finite_spans
                if reading is value
                # A masked opening is no longer a subordinate marker, so the
                # branch fence has to be re-read on the surface the roles are
                # actually read from.  Any *other* marker in the clause keeps
                # owning its predicate exactly as before.
                else _strong_modal_subordinate_finite_spans(reading)
            )
            or "?" in reading[hard_start:hard_end]
        ):
            continue
        projection = _predicate_relation(reading, action_start, action_end)
        if not _relation_is_assertive(
            reading,
            projection,
            action_start,
            action_end,
        ) and not _relation_wh_ambiguity_is_forced_unresolved(
            reading,
            projection,
            action_start,
            action_end,
        ):
            continue
        surface = action.group(0)
        folded = surface.casefold().replace("ё", "е")
        event = _relation_event(surface)
        tense = (
            "modal_tense:past"
            if event in {"past", "past_passive"}
            or irregular
            and re.search(r"(?:л|ла|ло|ли|[её]л)$", folded) is not None
            else "modal_tense:present"
        )
        finite_scope: set[str] = set()
        if opening is not None:
            finite_scope.add(
                _strong_modal_digest_qualifier(
                    # Композиция волны 9: вид зачина различается по его
                    # поверхности, иначе доказанно НЕОБЯЗАТЕЛЬНЫЙ оборот
                    # нельзя отбросить, хотя устройство само доказало,
                    # что он необязателен.
                    _relation_discourse_opening_kind(opening[1]),
                    opening[1],
                )
            )
        if epistemic is not None:
            finite_scope.update(
                _strong_modal_digest_qualifier(
                    _RELATION_EPISTEMIC_FRAME_KIND,
                    marker,
                )
                for marker in epistemic[1]
            )
        if _is_locally_negated(reading, action_start, action_end):
            finite_scope.add("finite_scope:negated")
        truth = _build_relation_truth(
            reading,
            action_start=action_start,
            action_end=action_end,
            modality="definite",
        )
        # Split the one boolean into its two meanings.  ``withheld_assertion``
        # is the source declining to assert - a forced-unresolved span, an
        # action-local non-assertion, a non-assertive reading.  Everything
        # below it is the projector failing to parse a clause the source did
        # assert.  The verdict is unchanged (the conjunction is the same);
        # only the reason becomes readable.
        withheld_assertion = (
            force_unresolved
            or _strong_modal_action_local_nonassertion(
                reading,
                action_start=action_start,
                action_end=action_end,
                action_surface=surface,
            )
            or not truth.assertive
        )
        coherent_truth = (
            not withheld_assertion
            and truth.grammatical
            and truth.patient_grammatical
            and truth.actor_grammatical
            and truth.action_span == (action_start, action_end)
            and truth.operative_actor
            and truth.direct_object
        )
        finite_predicate = _canonical_mandatory_predicate(surface)
        if coherent_truth and truth.event == "present_passive":
            # ``-ся`` is reflexive/middle in the open vocabulary.  Strip it
            # only for a mature passive family whose RelationTruth proved the
            # nominative patient and instrumental actor; arbitrary
            # ``уничтожается`` remains an exact reflexive predicate.
            # WAVE 9.  ``truth.event == "present_passive"`` IS that proof:
            # it is set either by the closed present-passive inventory or
            # by ``_relation_reflexive_passive_is_proved`` — a ``-тся``
            # form whose instrumental actor the same role parser bound.
            # Re-asking the closed inventory made the strip a white list
            # again, so an honest voice alternation kept a predicate key
            # no active clause could equal.  Nothing below is loosened.
            finite_predicate = finite_predicate.removesuffix(":reflexive")
        if coherent_truth:
            finite_scope.add(
                _strong_modal_complete_occurrence_qualifier(
                    reading,
                    action_start=action_start,
                    action_end=action_end,
                    modality="definite",
                )
            )
        else:
            # The fallback digest stays on the RAW clause: a masked surface
            # would hash equal to a clause that never carried the opening.
            # The epistemic frame is the deliberate exception - it is already
            # carried by its own atom above, so hashing it a second time
            # inside the clause would make a hedged output unable to match its
            # own hedged source.
            clause_surface, marker_names = _strong_modal_marker_named_clause(
                framed,
                hard_start,
                hard_end,
            )
            unresolved_qualifier = _strong_modal_digest_qualifier(
                "unresolved_finite_clause",
                clause_surface,
            )
            if not withheld_assertion:
                _UNRESOLVED_CLAUSE_PARSER_GAP_ATOMS.add(unresolved_qualifier)
            finite_scope.add(unresolved_qualifier)
            finite_scope.update(marker_names)
        claims.add(
            _strong_modal_family_claim(
                predicate=finite_predicate,
                polarity=(
                    "negative"
                    if _is_locally_negated(reading, action_start, action_end)
                    else "positive"
                ),
                modality="definite",
                tense=tense,
                scope=frozenset(finite_scope),
            )
        )
    return claims


_SPECIAL_MODAL_ASSERTION_RE = re.compile(
    r"\b(?:обязательн(?:о|а|ы)?|подлежит|подлежат|"
    r"обязуется|обязуются)\b|"
    r"\b(?:обязанност\w*[^.;!?\r\n]{0,160}возлож\w*|"
    r"возло(?:жен|жена|жено|жены|жила|жили|жило|жил)\w*"
    r"[^.;!?\r\n]{0,160}обязанност\w*|"
    r"возлага\w*[^.;!?\r\n]{0,160}обязанност\w*)",
    re.IGNORECASE,
)
_STRONG_MODAL_NOUN_DUTY_RE = re.compile(
    r"\bобязанност\w*\b",
    re.IGNORECASE,
)
_STRONG_MODAL_NOUN_DUTY_PREDICATE_RE = re.compile(
    r"\b(?:име\w*|вход\w*|включ\w*|состо\w*|заключа\w*|явля\w*)\b",
    re.IGNORECASE,
)
_STRONG_MODAL_NOUN_DUTY_NOMINAL_RE = re.compile(
    r"\b[а-яё-]{4,}(?:ни(?:е|я|ю|ем|и)|ци(?:я|и|ю|ей))\b",
    re.IGNORECASE,
)


def _strong_modal_noun_duty_is_operative(
    clause: str,
    *,
    cue_start: int,
    cue_end: int,
) -> bool:
    """Require a predicated action, not a topical ``права и обязанности``."""

    complements: list[tuple[int, int]] = []
    for infinitive in _INFINITIVE_ACTION_RE.finditer(clause):
        # ``обязанность`` itself ends in ``-ть`` and is therefore a lexical
        # false positive for the productive infinitive regex.
        if infinitive.start() < cue_end and cue_start < infinitive.end():
            continue
        complements.append(infinitive.span("action"))
    complements.extend(
        nominal.span()
        for nominal in _STRONG_MODAL_NOUN_DUTY_NOMINAL_RE.finditer(clause)
    )
    complements = [span for span in complements if span[0] >= cue_end]
    if not complements:
        return False
    first_complement_start = min(start for start, _end in complements)
    bridge = clause[cue_end:first_complement_start]
    return bool(
        re.search(r"(?:[:\u2014\u2013-])", bridge) is not None
        or _STRONG_MODAL_NOUN_DUTY_PREDICATE_RE.search(clause) is not None
    )


def _extract_special_modal_sentinel_claims(
    value: str,
) -> set[_QualitativeClaim]:
    """Fail closed for common duty/prohibition grammars not yet role-parsed."""

    claims: set[_QualitativeClaim] = set()
    seen_bounds: set[tuple[int, int]] = set()
    for cue in _SPECIAL_MODAL_ASSERTION_RE.finditer(value):
        hard_start, hard_end = _hard_clause_bounds(
            value,
            cue.start(),
            cue.end(),
        )
        if (hard_start, hard_end) in seen_bounds:
            continue
        seen_bounds.add((hard_start, hard_end))
        clause = value[hard_start:hard_end]
        if (
            "?" in clause
            or re.search(
                r"\b[а-яё-]{3,}(?:ться|чь|ть|ти|ает|яет|ует|ит|"
                r"ят|ут|ил|ила|или|ило|ание|ение|иние|тию|нию)\b",
                clause,
                re.IGNORECASE,
            )
            is None
        ):
            continue
        folded = clause.casefold().replace("ё", "е")
        prohibited = re.search(r"\bнельзя\b", folded) is not None
        negated = re.search(
            r"\bне\s+(?:подлежит|подлежат|обязуется|обязуются|"
            r"возлага\w*|возло\w*|обязательн\w*)\b",
            folded,
            re.IGNORECASE,
        ) is not None
        claims.add(
            _QualitativeClaim(
                action="strong_modal_action",
                object="unresolved_special_modal_clause",
                polarity=("negative" if prohibited or negated else "positive"),
                modality="mandatory",
                qualifiers=frozenset(
                    {
                        _strong_modal_digest_qualifier(
                            "unresolved_special_modal_clause",
                            clause,
                        ),
                        (
                            "modal_scope:prohibited"
                            if prohibited
                            else "modal_scope:negated_modal"
                            if negated
                            else "modal_scope:positive"
                        ),
                    }
                ),
            )
        )
    for cue in _STRONG_MODAL_NOUN_DUTY_RE.finditer(value):
        hard_start, hard_end = _hard_clause_bounds(
            value,
            cue.start(),
            cue.end(),
        )
        bounds = (hard_start, hard_end)
        if bounds in seen_bounds:
            continue
        clause = value[hard_start:hard_end]
        if not clause.strip() or "?" in clause:
            continue
        relative_start = cue.start() - hard_start
        relative_end = cue.end() - hard_start
        operative = _strong_modal_noun_duty_is_operative(
            clause,
            cue_start=relative_start,
            cue_end=relative_end,
        )
        if not operative and re.match(
            r"^\s*права\s+и\s+обязанност\w*\b",
            clause,
            re.IGNORECASE,
        ) is not None:
            # A catalogue/section heading names the topic but asserts no duty.
            # Other truncated duty clauses remain exact sentinels so an
            # operative source cannot be reduced to ``Обязанность суда``.
            continue
        seen_bounds.add(bounds)
        negated = re.search(
            r"\b(?:не|нет)\b",
            clause,
            re.IGNORECASE,
        ) is not None
        claims.add(
            _QualitativeClaim(
                action="strong_modal_action",
                object="unresolved_noun_duty_clause",
                polarity="negative" if negated else "positive",
                modality="mandatory",
                qualifiers=frozenset(
                    {
                        _strong_modal_digest_qualifier(
                            "unresolved_noun_duty_clause",
                            clause,
                        ),
                        (
                            "modal_scope:negated_modal"
                            if negated
                            else "modal_scope:positive"
                        ),
                        (
                            "modal_noun_duty:operative"
                            if operative
                            else "modal_noun_duty:incomplete"
                        ),
                    }
                ),
            )
        )
    return claims


def _strong_modal_governed_end(
    value: str,
    *,
    modal_end: int,
    hard_end: int,
) -> int:
    """Stop one modal before a following independent modal relation.

    A hard sentence may contain ``может X, но не обязан Y``.  Scanning every
    later infinitive from the first modal makes Y inherit the wrong modality
    and polarity.  The next strong modal owns its own relation; ordinary
    coordinated infinitives without another modal remain in the same scope.
    """

    following = _GENERIC_MODAL_RE.search(value, modal_end, hard_end)
    return following.start() if following is not None else hard_end


def _extract_strong_modal_action_claims(
    value: str,
) -> set[_QualitativeClaim]:
    """Project every explicit strong-modal predicate, regardless of actor.

    This is intentionally grammar-driven instead of relying on a closed list
    of courts, agencies, people, actions, or objects.  Each claim remains
    bound to one subject, predicate lexeme, polarity, and local arguments.
    """

    value = _strong_modal_mask_envelope_label(value)
    claims: set[_QualitativeClaim] = set(
        _extract_strong_modal_family_claims(value)
    )
    claims.update(_extract_special_modal_sentinel_claims(value))
    emitted_modals: set[tuple[int, int]] = set()
    for modal in _GENERIC_MODAL_RE.finditer(value):
        hard_start, hard_end = _hard_clause_bounds(
            value,
            modal.start(),
            modal.end(),
        )
        governed_end = _strong_modal_governed_end(
            value,
            modal_end=modal.end(),
            hard_end=hard_end,
        )
        modal_surface = modal.group("modal")
        modality = (
            "may"
            if _GENERIC_MODAL_MAY_RE.fullmatch(modal_surface) is not None
            else "mandatory"
        )
        modal_prefix = value[hard_start:modal.start()]
        shared_scope_qualifiers = _strong_modal_condition_qualifiers(
            modal_prefix,
            include_broad_leading_condition=True,
        )
        modal_negated = re.search(
            r"\bне\s*$",
            modal_prefix,
            re.IGNORECASE,
        ) is not None
        prohibited = (
            _GENERIC_MODAL_PROHIBITION_RE.fullmatch(modal_surface) is not None
        )
        personal = (
            _GENERIC_MODAL_PERSONAL_RE.fullmatch(modal_surface) is not None
        )
        governed_tail = value[modal.end():governed_end]
        first_infinitive = _INFINITIVE_ACTION_RE.search(governed_tail)
        modal_tense_qualifier = _strong_modal_tense_qualifier(
            modal_surface,
            (
                governed_tail[:first_infinitive.start("action")]
                if first_infinitive is not None
                else ""
            ),
        )

        # Productive passive fallback.  ``быть`` is an auxiliary, never the
        # semantic action.  Known participles remain exclusively owned by the
        # mature relation parser; unknown but morphologically proved short
        # participles receive the same actor/patient contract as active open
        # infinitives.  This supports the safe inanimate active/passive case
        # without inventing broad participial morphology.
        if (
            first_infinitive is not None
            and first_infinitive.group("action").casefold().replace("ё", "е")
            == "быть"
        ):
            passive_modal_prefix = modal_prefix
            passive_governed_tail = governed_tail
            actor_candidates = tuple(
                ("prefix", phrase)
                for phrase in _relation_complete_passive_actor_phrases(
                    modal_prefix
                )
                if not phrase.key.startswith(
                    _RELATION_UNRESOLVED_ACTOR_PREFIX
                )
            ) + tuple(
                ("governed", phrase)
                for phrase in _relation_complete_passive_actor_phrases(
                    governed_tail
                )
                if not phrase.key.startswith(
                    _RELATION_UNRESOLVED_ACTOR_PREFIX
                )
            )
            subject = ""
            actor_surface = ""
            if len(actor_candidates) == 1:
                zone, actor = actor_candidates[0]
                subject = "subject:" + actor.key
                if zone == "prefix":
                    actor_surface = modal_prefix[actor.start:actor.end]
                    passive_modal_prefix = (
                        modal_prefix[:actor.start]
                        + " " * (actor.end - actor.start)
                        + modal_prefix[actor.end:]
                    )
                else:
                    actor_surface = governed_tail[actor.start:actor.end]
                    passive_governed_tail = (
                        governed_tail[:actor.start]
                        + " " * (actor.end - actor.start)
                        + governed_tail[actor.end:]
                    )
            passive = _GENERIC_MODAL_PASSIVE_RE.match(
                passive_governed_tail
            )
            unresolved_passive = passive is None
            if passive is None:
                passive = _GENERIC_MODAL_UNRESOLVED_PASSIVE_RE.match(
                    passive_governed_tail
                )
            if passive is None:
                continue
            action_start = modal.end() + passive.start("participle")
            action_end = modal.end() + passive.end("participle")
            projection = _predicate_relation(value, action_start, action_end)
            if not _relation_is_assertive(
                value,
                projection,
                action_start,
                action_end,
            ):
                continue
            predicate = (
                _strong_modal_digest_qualifier(
                    "unresolved_modal_passive",
                    passive.group("participle"),
                )
                if unresolved_passive
                else _canonical_strong_modal_passive_predicate(
                    passive.group("participle")
                )
            )
            if not predicate:
                continue
            if _strong_modal_predicate_is_relation_owned(
                passive.group("participle"),
                predicate,
            ):
                if _strong_modal_mature_action_is_coherent(
                    value,
                    action_start=action_start,
                    action_end=action_end,
                    modal_surface=modal_surface,
                    analytic_passive=True,
                ):
                    emitted_modals.add((modal.start(), modal.end()))
                continue
            patient = _strong_modal_impersonal_patient(
                passive_modal_prefix
            )
            tail = passive_governed_tail[
                passive.end("participle"):
            ]
            tail_without_context, tail_scope_qualifiers = (
                _strong_modal_context_contract(tail)
            )
            scope_qualifiers = set(shared_scope_qualifiers)
            scope_qualifiers.update(tail_scope_qualifiers)
            scope_qualifiers.add(modal_tense_qualifier)
            if unresolved_passive:
                scope_qualifiers.add("modal_passive:unresolved")
            scope_qualifiers.update(
                _strong_modal_actor_qualifiers(
                    actor_surface,
                    role="instrumental",
                )
            )
            scope_qualifiers.update(
                _strong_modal_passive_agreement_qualifiers(
                    patient,
                    modal_surface,
                    passive.group("participle"),
                    personal=personal,
                )
            )
            if modal_negated:
                scope_qualifiers.add("modal_scope:negated_modal")
            if passive.group("action_negated"):
                scope_qualifiers.add("modal_scope:negated_action")
            if prohibited:
                scope_qualifiers.add("modal_scope:prohibited")
            claims.add(
                _strong_modal_claim(
                    value,
                    action_start=action_start,
                    action_end=action_end,
                    subject=subject,
                    polarity=(
                        "negative"
                        if modal_negated
                        or passive.group("action_negated")
                        or prohibited
                        else "positive"
                    ),
                    modality=modality,
                    predicate=predicate,
                    arguments=_mandatory_argument_qualifiers(
                        tail_without_context,
                        leading_value=patient,
                    ),
                    qualifiers=frozenset(scope_qualifiers),
                )
            )
            emitted_modals.add((modal.start(), modal.end()))
            continue

        raw_actions = tuple(_INFINITIVE_ACTION_RE.finditer(governed_tail))
        if not raw_actions:
            continue
        first_prefix = governed_tail[:raw_actions[0].start("action")]
        tense_auxiliary_qualifiers = (
            _strong_modal_tense_auxiliary_qualifiers(
                first_prefix,
                modal_surface=modal_surface,
            )
        )
        first_prefix = _strong_modal_without_tense_auxiliary(first_prefix)

        if personal:
            subject, leading_patient, actor_surface = (
                _strong_modal_personal_roles(
                    modal_prefix,
                    modal_surface,
                )
            )
            if not subject:
                subject, actor_surface, first_prefix = (
                    _strong_modal_postmodal_actor_prefix(first_prefix)
                )
            if not subject:
                continue
            impersonal_actor_qualifiers = frozenset()
        else:
            (
                subject,
                leading_patient,
                actor_surface,
                impersonal_actor_qualifiers,
            ) = _strong_modal_impersonal_roles(modal_prefix)

        first_prefix_without_context, first_scope_qualifiers = (
            _strong_modal_context_contract(first_prefix)
        )
        postmodal_leading_patient = ""
        if (
            _GENERIC_MODAL_PRE_ACTION_RE.fullmatch(
                first_prefix_without_context
            )
            is not None
        ):
            first_incoming = first_prefix_without_context
        else:
            postmodal_leading_patient = (
                _strong_modal_bounded_pre_action_patient(
                    first_prefix_without_context
                )
                or ""
            )
            if not postmodal_leading_patient:
                continue
            first_incoming = ""

        # Each record is (action, incoming bridge kind, incoming modifiers,
        # leading argument).  A comma alone never proves
        # co-action; a purpose/subordinate infinitive therefore remains inside
        # the first action's exact context and is not emitted as a new fact.
        governed_actions: list[
            tuple[re.Match[str], str, str, str]
        ] = []
        incoming_kinds: list[str] = ["single"]
        argument_ends: list[int] = []
        incoming_scope_qualifiers: list[frozenset[str]] = [
            first_scope_qualifiers
        ]
        for action_index, action in enumerate(raw_actions):
            if action_index == 0:
                governed_actions.append(
                    (
                        action,
                        "single",
                        first_incoming,
                        postmodal_leading_patient,
                    )
                )
                continue
            previous = governed_actions[-1][0]
            between = governed_tail[
                previous.end("action"):action.start("action")
            ]
            if _GENERIC_MODAL_SUBORDINATE_RE.search(between) is not None:
                break
            bridge = _relation_action_bridge_span(between)
            if bridge is None:
                break
            bridge_kind, bridge_start, bridge_end = bridge
            incoming_raw = between[bridge_end:]
            incoming, incoming_scope = _strong_modal_context_contract(
                incoming_raw
            )
            incoming_leading = ""
            if _GENERIC_MODAL_PRE_ACTION_RE.fullmatch(incoming) is None:
                incoming_leading = (
                    _strong_modal_bounded_pre_action_patient(incoming) or ""
                )
                if not incoming_leading:
                    break
                incoming = ""
            argument_ends.append(previous.end("action") + bridge_start)
            incoming_kinds.append(bridge_kind)
            incoming_scope_qualifiers.append(incoming_scope)
            governed_actions.append(
                (action, bridge_kind, incoming, incoming_leading)
            )
        argument_ends.append(len(governed_tail))

        coordination_qualifiers: list[frozenset[str]] = [
            frozenset() for _ in governed_actions
        ]
        bridge_kinds = tuple(incoming_kinds[1:])
        bridge_topology = frozenset(bridge_kinds)
        if bridge_kinds and bridge_topology in {
            frozenset({"conjunctive"}),
            frozenset({"alternative"}),
        }:
            kind = next(iter(bridge_topology))
            shared_coordination = frozenset(
                {f"modal_coordination:{kind}:{len(governed_actions)}"}
            )
            coordination_qualifiers = [
                shared_coordination for _ in governed_actions
            ]
        elif bridge_kinds:
            coordination_qualifiers = [
                frozenset(
                    {
                        "modal_coordination:v1:"
                        f"{index}:{len(governed_actions)}:"
                        f"{incoming_kinds[index] if index else 'start'}:"
                        f"{incoming_kinds[index + 1] if index + 1 < len(incoming_kinds) else 'end'}"
                    }
                )
                for index in range(len(governed_actions))
            ]

        actor_qualifiers = _strong_modal_actor_qualifiers(
            actor_surface,
            governor=modal_surface,
            role="nominative",
        ) if personal else impersonal_actor_qualifiers

        local_argument_surfaces: list[str] = []
        local_argument_scope_qualifiers: list[frozenset[str]] = []
        for index, (action, _kind, _incoming, _leading) in enumerate(
            governed_actions
        ):
            local_surface, local_scope = _strong_modal_context_contract(
                governed_tail[action.end("action"):argument_ends[index]]
            )
            local_argument_surfaces.append(local_surface)
            local_argument_scope_qualifiers.append(local_scope)
        argument_contracts = [
            _mandatory_argument_qualifiers(
                local_argument_surfaces[index],
                leading_value=" ".join(
                    part
                    for part in (
                        leading_patient if index == 0 else "",
                        leading_argument,
                    )
                    if part
                ),
            )
            for index, (
                _action,
                _kind,
                _incoming,
                leading_argument,
            ) in enumerate(governed_actions)
        ]
        topology = frozenset(incoming_kinds[1:])
        nonempty_argument_contracts = {
            contract for contract in argument_contracts if contract
        }
        if (
            len(argument_contracts) > 1
            and topology in {
                frozenset({"conjunctive"}),
                frozenset({"alternative"}),
            }
            and len(nonempty_argument_contracts) == 1
        ):
            # Tight same-topology actions may share one physical left- or
            # right-node patient (``destroy and burn the archive``).  An
            # explicit different object creates two contracts and disables
            # inheritance.  OR remains distinguishable through the exact
            # coordination qualifier on every alternative branch.
            shared_argument = next(iter(nonempty_argument_contracts))
            argument_contracts = [
                contract or shared_argument for contract in argument_contracts
            ]

        for index, (action, _kind, incoming, _leading) in enumerate(
            governed_actions
        ):
            action_start = modal.end() + action.start("action")
            action_end = modal.end() + action.end("action")
            action_surface = action.group("action")
            if action_surface.casefold().replace("ё", "е") == "быть":
                continue
            projection = _predicate_relation(value, action_start, action_end)
            if not _relation_is_assertive(
                value,
                projection,
                action_start,
                action_end,
            ):
                continue
            predicate = _canonical_mandatory_predicate(action_surface)
            if _strong_modal_predicate_is_relation_owned(
                action_surface,
                predicate.removesuffix(":reflexive"),
            ):
                continue
            action_negated = re.search(
                r"\bне\s*$",
                incoming,
                re.IGNORECASE,
            ) is not None
            scope_qualifiers = set(shared_scope_qualifiers)
            scope_qualifiers.update(incoming_scope_qualifiers[index])
            scope_qualifiers.update(
                local_argument_scope_qualifiers[index]
            )
            scope_qualifiers.update(actor_qualifiers)
            scope_qualifiers.add(modal_tense_qualifier)
            scope_qualifiers.update(tense_auxiliary_qualifiers)
            if modal_negated:
                scope_qualifiers.add("modal_scope:negated_modal")
            if action_negated:
                scope_qualifiers.add("modal_scope:negated_action")
            if prohibited:
                scope_qualifiers.add("modal_scope:prohibited")
            scope_qualifiers.update(coordination_qualifiers[index])
            local_modifier = re.sub(
                r"\bне\s*$",
                " ",
                incoming,
                flags=re.IGNORECASE,
            ).strip(" \t\r\n,;:.\u2014\u2013-")
            if local_modifier:
                scope_qualifiers.add(
                    _strong_modal_digest_qualifier(
                        "modal_pre_action",
                        local_modifier,
                    )
                )
            claims.add(
                _strong_modal_claim(
                    value,
                    action_start=action_start,
                    action_end=action_end,
                    subject=subject,
                    polarity=(
                        "negative"
                        if modal_negated or action_negated or prohibited
                        else "positive"
                    ),
                    modality=modality,
                    predicate=predicate,
                    arguments=argument_contracts[index],
                    qualifiers=frozenset(scope_qualifiers),
                )
            )
            emitted_modals.add((modal.start(), modal.end()))

    # Bounded inverted grammar: ``Уничтожить архив обязан суд``.  It is
    # intentionally handled after the forward modal scan, and only when no
    # governed infinitive follows the modal, so the same physical action is
    # never projected twice with two incompatible role layouts.
    for modal in _GENERIC_MODAL_RE.finditer(value):
        if _GENERIC_MODAL_PERSONAL_RE.fullmatch(modal.group("modal")) is None:
            continue
        hard_start, hard_end = _hard_clause_bounds(
            value,
            modal.start(),
            modal.end(),
        )
        if _INFINITIVE_ACTION_RE.search(value[modal.end():hard_end]) is not None:
            continue
        preceding_actions = tuple(
            _INFINITIVE_ACTION_RE.finditer(value, hard_start, modal.start())
        )
        if not preceding_actions:
            continue
        action = preceding_actions[-1]
        action_start, action_end = action.span("action")
        projection = _predicate_relation(value, action_start, action_end)
        if not _relation_is_assertive(
            value,
            projection,
            action_start,
            action_end,
        ):
            continue
        predicate = _canonical_mandatory_predicate(action.group("action"))
        if _strong_modal_predicate_is_relation_owned(
            action.group("action"),
            predicate.removesuffix(":reflexive"),
        ):
            continue
        postmodal_surface = value[modal.end():hard_end]
        subject, actor_surface = _strong_modal_postposed_actor(
            postmodal_surface
        )
        between_surface = value[action_end:modal.start()]
        modal_negated = re.search(
            r"\bне\s*$",
            between_surface,
            re.IGNORECASE,
        ) is not None
        between_without_negation = re.sub(
            r"\bне\s*$",
            "",
            between_surface,
            flags=re.IGNORECASE,
        )
        if subject:
            trailing_argument = between_without_negation
        else:
            subject, actor_surface, trailing_argument = (
                _strong_modal_premodal_actor_suffix(
                    between_without_negation
                )
            )
        if not subject:
            continue
        action_negated = re.search(
            r"\bне\s*$",
            value[hard_start:action_start],
            re.IGNORECASE,
        ) is not None
        leading_argument = re.sub(
            r"\bне\s*$",
            "",
            value[hard_start:action_start],
            flags=re.IGNORECASE,
        )
        leading_argument, leading_scope = _strong_modal_context_contract(
            leading_argument
        )
        trailing_argument, trailing_scope = _strong_modal_context_contract(
            trailing_argument
        )
        postmodal_without_context, postmodal_scope = (
            _strong_modal_context_contract(postmodal_surface)
        )
        if subject and postmodal_without_context.strip(
            " \t\r\n,;:.\u2014\u2013-"
        ) not in {"", actor_surface}:
            # A proved post-modal actor may be surrounded only by context that
            # received its own exact contract; arbitrary residue is unresolved.
            continue
        qualifiers = set(leading_scope)
        qualifiers.update(trailing_scope)
        qualifiers.update(postmodal_scope)
        qualifiers.add(
            _strong_modal_tense_qualifier(
                modal.group("modal"),
                postmodal_surface,
            )
        )
        qualifiers.update(
            _strong_modal_actor_qualifiers(
                actor_surface,
                governor=modal.group("modal"),
                role="nominative",
            )
        )
        if modal_negated:
            qualifiers.add("modal_scope:negated_modal")
        if action_negated:
            qualifiers.add("modal_scope:negated_action")
        claims.add(
            _strong_modal_claim(
                value,
                action_start=action_start,
                action_end=action_end,
                subject=subject,
                polarity=(
                    "negative"
                    if modal_negated or action_negated
                    else "positive"
                ),
                modality=(
                    "may"
                    if _GENERIC_MODAL_MAY_RE.fullmatch(
                        modal.group("modal")
                    )
                    is not None
                    else "mandatory"
                ),
                predicate=predicate,
                arguments=_mandatory_argument_qualifiers(
                    trailing_argument,
                    leading_value=leading_argument,
                ),
                qualifiers=frozenset(qualifiers),
            )
        )
        emitted_modals.add((modal.start(), modal.end()))

    # Any still-unowned assertive modal clause receives an exact fail-closed
    # sentinel.  This is the safety net for punctuation/list gaps, finite or
    # nominal complements, unsupported word order and genuinely unfamiliar
    # modifiers.  A mature lexeme suppresses it only when RelationTruth proves
    # the same physical action, actor, modality and grammar.
    for modal in _GENERIC_MODAL_RE.finditer(value):
        modal_span = (modal.start(), modal.end())
        if modal_span in emitted_modals:
            continue
        hard_start, hard_end = _hard_clause_bounds(
            value,
            modal.start(),
            modal.end(),
        )
        clause = value[hard_start:hard_end]
        if "?" in clause:
            continue
        infinitives = tuple(
            _INFINITIVE_ACTION_RE.finditer(value, hard_start, hard_end)
        )
        finite_or_nominal = re.search(
            r"\b[а-яё-]{3,}(?:ает|яет|ует|ит|ят|ут|ил|ила|или|ило|"
            r"ание|ение|иние|тие)\b",
            clause,
            re.IGNORECASE,
        )
        if not infinitives and finite_or_nominal is None:
            continue
        if infinitives and all(
            _strong_modal_mature_action_is_coherent(
                value,
                action_start=action.start("action"),
                action_end=action.end("action"),
                modal_surface=modal.group("modal"),
            )
            for action in infinitives
        ):
            continue
        modal_prefix = value[hard_start:modal.start()]
        prohibited = (
            _GENERIC_MODAL_PROHIBITION_RE.fullmatch(modal.group("modal"))
            is not None
        )
        modal_negated = re.search(
            r"\bне\s*$",
            modal_prefix,
            re.IGNORECASE,
        ) is not None
        claims.add(
            _strong_modal_unresolved_claim(
                value,
                hard_start=hard_start,
                hard_end=hard_end,
                modal_surface=modal.group("modal"),
                modality=(
                    "may"
                    if _GENERIC_MODAL_MAY_RE.fullmatch(modal.group("modal"))
                    is not None
                    else "mandatory"
                ),
                polarity=(
                    "negative"
                    if prohibited or modal_negated
                    else "positive"
                ),
            )
        )

    # Bounded imposed duty: ``На суд возлагается обязанность уничтожить
    # архив``.  The whole role phrase is canonicalized as one actor; the
    # complete post-action tail remains the exact patient/context contract.
    imposed_duty_re = re.compile(
        r"\bна\s+(?P<subject>[^,;.!?\r\n]{1,120}?)\s+"
        r"возлага\w*\s+обязанност\w*\s+"
        r"(?P<negated>не\s+)?"
        r"(?P<action>[а-яё-]{3,}?(?:ться|чь|ть|ти))\b",
        re.IGNORECASE,
    )
    for duty in imposed_duty_re.finditer(value):
        action_start, action_end = duty.span("action")
        projection = _predicate_relation(value, action_start, action_end)
        if not _relation_is_assertive(
            value,
            projection,
            action_start,
            action_end,
        ):
            continue
        predicate = _canonical_mandatory_predicate(duty.group("action"))
        if _strong_modal_predicate_is_relation_owned(
            duty.group("action"),
            predicate.removesuffix(":reflexive"),
        ):
            continue
        actor_surface = duty.group("subject").strip()
        actor = _relation_actor_key(actor_surface, preserve_complete=True)
        if not actor:
            continue
        hard_start, hard_end = _hard_clause_bounds(
            value,
            action_start,
            action_end,
        )
        tail_without_context, tail_scope = _strong_modal_context_contract(
            value[action_end:hard_end]
        )
        leading_without_context, leading_scope = (
            _strong_modal_context_contract(value[hard_start:duty.start()])
        )
        qualifiers = set(tail_scope)
        qualifiers.update(leading_scope)
        if duty.group("negated"):
            qualifiers.add("modal_scope:negated_action")
        claims.add(
            _strong_modal_claim(
                value,
                action_start=action_start,
                action_end=action_end,
                subject="subject:" + actor,
                polarity=(
                    "negative" if duty.group("negated") else "positive"
                ),
                modality="mandatory",
                predicate=predicate,
                arguments=_mandatory_argument_qualifiers(
                    tail_without_context,
                    leading_value=leading_without_context,
                ),
                qualifiers=frozenset(qualifiers),
            )
        )
    return claims


def _strong_modal_productive_occurrence_digest(
    value: str,
    action: re.Match[str],
) -> str | None:
    """Return one exact assertive raw occurrence, or a safe local fence.

    An unmatched productive token is source-relevant regardless of the
    residue that made ordinary extraction fail.  Only action-local evidence
    may suppress it: the action itself is inside a complete balanced wrapper,
    existing assertiveness grammar marks the clause as a query/epistemic
    statement, or the action remains inside a bounded modal/subordinate
    branch.  Every one of those fences is read through the shared delimiter
    contract, so a marker written inside a name never reaches them; a
    malformed wrapper switches all of them off and the occurrence is hashed
    on the exact raw bytes.
    """

    action_start, action_end = action.span("action")
    syntax = _strong_modal_wrapper_syntax(value)
    hard_start, hard_end = _strong_modal_wrapper_clause_bounds(
        value,
        action_start,
        action_end,
    )
    clause = value[hard_start:hard_end]
    if syntax.malformed:
        return _strong_modal_digest_qualifier(
            "productive_finite_clause",
            clause,
        )
    if syntax.encloses(action_start, action_end):
        return None
    if not _relation_is_assertive(
        value,
        _predicate_relation(value, action_start, action_end),
        action_start,
        action_end,
    ):
        # The same fail-open as in claim extraction, in the second consumer
        # of the verdict: returning ``None`` here means "stop auditing this
        # occurrence", so one ``Возможно,`` in front of a fabricated sanction
        # bought silence instead of scrutiny.  The epistemic frame is masked
        # instead and the occurrence is still hashed, so it still has to be
        # one the source actually wrote.  The frame surface is deliberately
        # NOT hashed here - the claim-level atom already carries it - so an
        # output that merely weakens a categorical source keeps matching.
        frame = _relation_epistemic_frame(value, action_start, action_end)
        if frame is None:
            return None
        value = frame[0]
        clause = value[hard_start:hard_end]
    projection = _predicate_relation(value, action_start, action_end)
    if not _relation_is_assertive(
        value,
        projection,
        action_start,
        action_end,
    ):
        return None

    prefix = value[hard_start:action_start]

    def independent_subject_after(marker_end: int) -> bool:
        local_marker_end = marker_end - hard_start
        comma = prefix.rfind(",", local_marker_end)
        if comma < local_marker_end:
            return False
        local = prefix[comma + 1:]
        intro = re.match(
            r"\s*(?:(?:а|но|и)\s+)?",
            local,
            re.IGNORECASE,
        )
        if intro is None:
            return False
        return bool(
            _strong_modal_action_slot_subject_proof(
                local[intro.end():],
                action.group("action"),
            )
        )

    subordinate = tuple(
        _GENERIC_MODAL_SUBORDINATE_RE.finditer(
            syntax.surface,
            hard_start,
            action_start,
        )
    )
    if subordinate and not independent_subject_after(
        subordinate[-1].end()
    ):
        return None
    modals = tuple(
        _GENERIC_MODAL_RE.finditer(
            syntax.surface,
            hard_start,
            action_start,
        )
    )
    if modals and not independent_subject_after(modals[-1].end()):
        return None
    return _strong_modal_digest_qualifier(
        "productive_finite_clause",
        clause,
    )


def _validate_strong_modal_productive_residual_source_evidence(
    source_text: str,
    output_text: str,
    *,
    field: str,
) -> None:
    """Reject changed unmatched occurrences of a source-owned predicate."""

    source_value = _strong_modal_mask_envelope_label(source_text)
    source_claim_predicates = {
        claim.object
        for claim in _extract_strong_modal_action_claims(source_text)
        if claim.action == "strong_modal_family"
        and claim.modality == "definite"
    }
    source_occurrences: dict[str, set[str]] = {}
    for action in _STRONG_MODAL_PRODUCTIVE_ET_FINITE_RE.finditer(
        source_value
    ):
        predicate = _canonical_mandatory_predicate(
            action.group("action")
        )
        if predicate not in source_claim_predicates:
            continue
        digest = _strong_modal_productive_occurrence_digest(
            source_value,
            action,
        )
        if digest is not None:
            source_occurrences.setdefault(predicate, set()).add(digest)
    if not source_occurrences:
        return

    output_value = _strong_modal_mask_envelope_label(output_text)
    # A forced-unresolved emission is precisely an occurrence whose roles were
    # NOT resolved: it carries a raw hard-clause digest instead of a grammatical
    # actor/patient pair.  Such an occurrence is still unmatched residue, so the
    # source-owned raw audit below must keep owning it.  Only occurrences that
    # ordinary extraction resolved are handed over to the ordinary contracts.
    output_emitted_spans = {
        action.span()
        for action, _irregular, force_unresolved in (
            _strong_modal_semantic_finite_candidates(output_value)
        )
        if not force_unresolved
    }
    for action in _STRONG_MODAL_PRODUCTIVE_ET_FINITE_RE.finditer(
        output_value
    ):
        if action.span() in output_emitted_spans:
            continue
        predicate = _canonical_mandatory_predicate(
            action.group("action")
        )
        source_digests = source_occurrences.get(predicate)
        if not source_digests:
            continue
        digest = _strong_modal_productive_occurrence_digest(
            output_value,
            action,
        )
        if digest is None or digest in source_digests:
            continue
        raise ValueError(
            f"{field}: productive finite predicate {predicate!r} "
            "changed its source-owned raw occurrence"
        )


